-- Falas de Pokemon Gold em portugues brasileiro.
-- Chave = ponteiro da ROM USA, no formato que o gen1recomp usa.
-- Vazio ou ausente = cai em ingles.
return {
  ["40:4615"] = "Bom dia!\nBem-vindo ao\vCENTRO POKéMON!",
  ["40:4640"] = "Oi! Seja bem\nvindo ao CENTRO\vPOKéMON.",
  ["40:4664"] = "Boa Noite!\nVoce chegou tarde.\fBem-vindo ao\nCENTRO POKéMON!",
  ["40:469f"] = "Podemos curar\ntotalmente o\vseu POKéMON.    \fEu posso curar\nseu POKéMON?",
  ["40:46e2"] = "Me entregue seus\nPOKéMONS!",
  ["40:46fc"] = "Obrigado por\nesperar. \fSeus POKéMONS\nestao curados!",
  ["40:4730"] = "Esperamos ve-lo\nde novo.",
  ["40:4766"] = "Seus POKéMONS\nparecem ter\vmicroorganismos\vgrudados neles.\fSeus POKéMONS\nestao saudaveis e\vparecem estar bem.\fMas nao podemos\ndizer mais nada\vno CENTRO POKéMON.",
  ["40:4801"] = "Lotado de livros\ndificeis.",
  ["40:484a"] = "REVISTAS POKéMON…\nJOGOS DE POKéMONS…\fMANUAIS POKéMON…\nGRAFICO POKéMON…",
  ["40:48ef"] = "O que é isso?\fOh, é um porta\nincensos!",
  ["40:4934"] = "Este é o MAPA.",
  ["40:4965"] = "E uma Televisao.",
  ["40:49cd"] = "Nao ha nada aqui…",
  ["40:4a43"] = "Tudo que o POKéMON\nprecisa!\fLOJA POKéMON.",
  ["40:4a66"] = "Agora julgaremos\no POKéMON que voce\vcapturou.\f…\n…\fEscolhemos os\nvencedores!\fVoces estao\npreparados?",
  ["40:4ac8"] = "Uau! Que celular\nbonito.\fMe de o seu\nnumero do celular?\fTe ligo para uma\nrevanche!",
  ["40:4b39"] = "{PLAYER} guardou\nnumero de {STRBUF}.",
  ["40:4b7a"] = "Certo…\nE so falar de\vnovo comigo se\vquiser o meu\vtelefone.",
  ["40:4bef"] = "Eu o aguardava.\nVamos batalhar!",
  ["40:4c77"] = "Anotar numero de\nCELULAR?",
  ["40:4cb0"] = "Te ligarei se\nocorrer algo.",
  ["40:4d12"] = "Seu telefone nao\ntem memoria,\vpara por mais\vnumeros!",
  ["40:4d6a"] = "{PLAYER} ganha o\n{STRBUF}ü premio, o(a)\v{STRBUF}!",
  ["40:4d90"] = "{PLAYER} recebeu\n{STRBUF}.",
  ["40:4da3"] = "Comparecam no\nproximo Concurso!",
  ["40:4dc9"] = "Todos ganham um\nGRAO como premio\vde consolacao!",
  ["40:4dff"] = "Esperamos melhoras\nna proxima.",
  ["40:4e21"] = "Devolveremos seus\nPOKéMONS que\vguardamos.\fAqui estao!",
  ["40:4e96"] = "{STRBUF}\nGINASIO POKéMON",
  ["40:5014"] = "Oh? Sua BOLSA esta\ncheia.\fNos guardaremos\nisso hoje, entao\vvolte quando\vliberar espaco.",
  ["42:4087"] = "Todos seres\ncoexistem dentro\vduma cooperacao. \fDevemos ficar bem\ngratos por isso.",
  ["42:40dc"] = "So obtera um HM\nse voce chegar ao\vtopo daqui.",
  ["42:410e"] = "A TORRE BROTINHO\nfoi feita ha um\vtempo para o\vtreino POKéMON.",
  ["42:414d"] = "Um BELLSPROUT de\n33 metros…\fDizem que ele se\ntornou o pilar\vcentral desse\vlugar.",
  ["42:41a1"] = "Ve o pilar\ntremendo?\fHa pessoas\ntreinando la em\vcima.",
  ["42:42d0"] = "NHO ficara\vforte.",
  ["42:4373"] = "Tentei copiar os\nmovimentos do\vBELLSPROUT para\vbatalhar…  \fMas eu nao treinei\no bastante.",
  ["42:452b"] = "LIDER: Sem duvida\nvoce é um otimo\vtreinador.\fComo prometi, aqui\nesta o HM.\fMas quero avisar\nlhe:\fVoce deve tratar\nmelhor seus\vPOKéMONS. \fSeu estilo de luta\né inadequado.\fOs POKéMONS nao\nsao armas de\vguerra…",
  ["42:45f0"] = "…\n…Bah! Ele diz ser\vo LIDER mas ele\vé bem fraco. \fE muito\ncertinho.\fNunca perderei\npara bobos que\fficam sendo legais\ncom os POKéMONS.\fSo ligo para\nPOKéMONS fortes\vque podem vencer.\fEu nao me\nimportaria com\vPOKéMONS fracos.",
  ["42:46cc"] = "{RIVAL} usou\nCORDADEFUGA!",
  ["42:46e4"] = "Fico feliz por\nvoce chegar aqui!\fA TORRE BROTINHO\né um lugar de\vtreino.\fPessoas e POKéMONS\nse testam aqui\vpara fazerem\vjuntos um bom\vfuturo.\fSou o teste final.\fDeixe-me checar\nos lacos entre\vvoce e os seus\vPOKéMONS!",
  ["42:47b6"] = "Ah, brilhante!",
  ["42:47c6"] = "Voce e seus\nPOKéMONS nao terao\vproblemas ao\vusarem esse golpe.\fPegue esse HM\nLUZES.",
  ["42:4817"] = "LUZES ilumina até\nos lugares mais \vescuros.\fMas para usa-lo\nfora de batalhas,\vvoce precisa da\vINSIGNIA DA BRISA.",
  ["42:488c"] = "Espero que aprenda\ne cresca na sua\vjornada.",
  ["42:4b20"] = "Estou tentando\nencobrir o segredo\vdo lendario\vPOKéMON que\vaparenta estar\vaqui.\fDizem que o\nPOKéMON voa\vcontinuamente\vdesde quando a\vTORRE do oeste foi\vincendiada.\fEntao, eu pensei\nque se eu tivesse\vo que o POKéMON\vtem, ele seria\vatraido por esse\vitem.\fEu acho que\nesse item é\vprovavelmente…\fA ASA ARCO IRIS!\fMas, onde eu\npoderia achar\vuma?",
  ["42:4f24"] = "……………\f…Oh, é voce.\fVoce queria ficar\nbem forte, entao \vveio em busca do\vPOKéMON lendario\vque supostamente\vesta aqui.\fEsta é sua\nhistoria, né?\fBem, isso nao vai\nacontecer.\fPorque eu vou\npega-los!\fEu serei o melhor\ntreinador do\vmundo, entao um\vPOKéMON lendario\vseria perfeito\vpara mim.\f…Bem, de qualquer\nmaneira, estou\vficando cansado de\vter um bobao como\vvoce sempre\vaparecendo.",
  ["42:5093"] = "…Humph!\fPor isso eu odeio\nbatalhar com\vbobos.\fNao ha desafio\nnisto.",
  ["42:50da"] = "…Aw, por mais que\nvoce tente, nunca\vpegara um POKéMON\vlendario.",
  ["42:5124"] = "…Humph!\fPoro isso odeio\nbatalhar com\vbobos.\fE jogar meu tempo\nfora.",
  ["42:516d"] = "Ei, estou\ntreinando\vsecretamente\vaqui!\fNao me embarasse\npelo olhar!",
  ["42:519a"] = "barasse\npelo olhar!",
  ["42:51ac"] = "Queimei até\nvirar cinzas…",
  ["42:51cb"] = "Me empolguei tanto\nno treinamento que\vcai nesse buraco.",
  ["42:5204"] = "aco.",
  ["42:5236"] = "Nao esta quente o\nbastante.",
  ["42:524d"] = " quando\vqueima!",
  ["42:528b"] = "numa velocidade\valtissima.  \fDizem que eles\ncorrem como o\vvento.\fSe voce procurar\npor um na grama,\veles fugirao\vpara longe.",
  ["42:552a"] = "Um bando de\nDIGLETTS sairam do\vchao!\fIsto foi chocante.",
  ["42:562d"] = "… … …\fJa faz tempo,\n{PLAYER}.\f…Desde que perdi\npara voce, pensei\vcomo era carente\vcom os meus\vPOKéMONS…\fE temos uma\nresposta para lhe\vdar.\fVamos lhe mostrar,\n{PLAYER}!",
  ["42:56c5"] = "… … …\fPensei que treinei\nmeu POKéMON para\vele poder fazer\vo melhor…\f…Mas nao foi\no suficiente…",
  ["42:5722"] = "… … …\f…Voce venceu\njusto e limpo.\fEu admito.\nMas isto nao\vacabou.\fEu sempre vou ser\no maior treinador\vPOKéMON.\fPorque estes caras\nestao atras de\vmim.   \f…Escute,\n{PLAYER}.\fUm dia deste vou\nlhe mostrar o\vquanto sou bom\vconseguindo\vvencer-lhe.",
  ["42:5808"] = "… … …\fReembolsei minha\ndivida contigo.\fCom meu POKéMON,\nvou ganhar do\vCAMPEAO e me\vtornarei o melhor\vtreinador POKéMON\vdo mundo.",
  ["42:5a87"] = "Espere.\f…Voce esta indo\nencarar o desafio\vda LIGA POKéMON?\f…Nao me faca rir.\fVoce é bem mais\nfraco que eu.\fEu nao sou mais\ncomo antes.\fAgora eu tenho os\nmelhores e mais\vfortes POKéMONS\vcomigo.\fEstou invencivel!\f{PLAYER}! Eu\ndesafio voce!",
  ["42:5b65"] = "…Nao pude vencer…\fEu dei tudo o que\ntinha…\fO que voce tem\nque eu nao tenho…\fEstou comecando\na entender o que o\vmestre de dragoes\vme disse…",
  ["42:5bf6"] = "…Eu nao desisti de\nme tornar o melhor\vtreinador…\fEu descobrirei\npor que eu nao\vposso ganhar e ser\vforte…\fQuando acabar,\neu desafiarei\vvoce.\fE eu vencerei voce\ncom todo o meu\vpoder.\f…Humph! Voce\nestara o mesmo até\vla.",
  ["42:5cd2"] = "…Humph!\fQuando se trata\ndisso, nada supera\vo poder.\fEu nao preciso de\nmais ninguém.",
  ["42:d54c"] = "Eu moro aqui.\fVoce pode, também,\nse gostar.\fComo ve, tem muito\nespaco aqui.",
  ["43:4196"] = "Olhe! Olhe minha\nmala!\fEu imprimi meus\nfavoritos da\vPOKéDEX e os\vprendi na minha\vmala.",
  ["43:41f1"] = "Eu recebi essa\nCARTA da minha\vfilha. Eu fiquei\vfeliz.",
  ["43:4228"] = "Preste atencao!\f…Opa, tenho que\nparar de pensar\vcomo professores\vo tempo todo.\fVoce deve ser um\ntreinador POKéMON.\fComo esta\ntrabalhando duro,\veu quero que voce\vleve isso.",
  ["43:4320"] = "Estou brincando\ncom figuras\vque imprimi na\vPOKéDEX.",
  ["43:4352"] = "Se eu vencer,\npegarei as figuras\vdo garoto.",
  ["43:43ed"] = "Estou imprimindo\nminha POKéDEX.\fVoce pode imprimir\nCARTAS e BOXES do\vcomputador.",
  ["43:44a7"] = "O-o-o que?",
  ["43:44b6"] = "Tenho muito a\naprender.\fPor exemplo…\fExistem 50 tipos\nde TMs.\fOs POKéMONS\ntrocados crescem\vrapido.",
  ["43:48e0"] = "DON: Eu vou\nvencer! Nao me\vatrapalhe.",
  ["43:4907"] = "ED: Com ESPOROS,\nmeu PARASECT faz\vPOKéMONS dormirem.",
  ["43:4937"] = "NICK: Treino\nrapido POKéMONS\vpara batalharem.",
  ["43:4960"] = "WILSON: Nao me\ninteresso em\vvencer.\fEu apenas procuro\npor POKéMONS\vraros.",
  ["43:49a9"] = "BENNY: Ssh! Voce\nvai espantar o\vSCYTHER.\fTe vejo depois.",
  ["43:49e6"] = "BARRY: Canse os\nPOKéMONS insetos\vantes de jogar uma\vPOKé BOLA.",
  ["43:4a25"] = "CINDY: O que foi?\fAchou engracado\nver meninas\vcapturando os\vPOKéMON insetos?",
  ["43:4a70"] = "JOSH: Eu coleciono\nPOKéMONS insetos\vdesde quando eu\vera um bebe.\fNao ha maneiras de\neu perder!",
  ["43:4acd"] = "SAMUEL: Se tiver\ntempo disponivel,\vva procurar\vPOKéMONS insetos.",
  ["43:4b0c"] = "KIPP: Eu estudei\nmuito os POKéMONS\vinsetos.\fCom certeza eu\nvencerei.",
  ["43:4e16"] = "{PLAYER}a\v{STRBUF}{STRBUF}Bem-vindo!",
  ["43:4e29"] = "Ola. Perdao, mas\nnao sortearemos\vnenhuma viagem\vhoje.",
  ["43:4ee2"] = "O numero de\nIDENTIFICA'sAO\vdessa semana é\v{STRBUF}.",
  ["43:4f02"] = "Deixe-me ver se\nvoce ganhou.",
  ["43:4f21"] = "…\n…",
  ["43:4f26"] = "Volte na proxima\nsemana para o\vNUMERO DA SORTE.",
  ["43:4f5d"] = "Uau! Voce acertou\ntodos os cinco\vnumeros!\fNos temos um\ngrande\nvencedor!\fVoce ganhou uma\nMASTER BOLA!",
  ["43:4fcb"] = "Ei! Voce acertou\nos ultimos tres\vnumeros!\fVoce ganhou o\vsegundo premio, o\vDIVIDE EXP.!",
  ["43:501e"] = "Oh, voce acertou\nos dois ultimos\vnumeros.\fVoce ganhou o\nterceiro premio, o\vPP MAIS.",
  ["43:5068"] = "Voce nao acertou\nnumero algum.",
  ["43:508e"] = "Voce nao tem lugar\npara o premio.\fLibere espaco e\nvolte em seguida.",
  ["43:50d5"] = "Nos temos\num concurso\vde perguntas\vfuncionando.\fAcerte cinco\nperguntas para\vreceber um CARTAO\vDE RADIO.\fColoque-o na sua\nPOKéGEAR para\vescutar radio a\vqualquer hora ou\vlugar.\fVoce deseja\nparticipar?",
  ["43:519a"] = "Pergunta 1:\fO MAPA pode ser\nmostrado na\vPOKéGEAR?",
  ["43:5204"] = "Na mosca!\nPergunta 3:\fKURT, o homem das\nPOKé BOLAS, usa\vTRUTAS?",
  ["43:524d"] = "Muito bem!\nPergunta 4:\fMAGIKARP nao\naprendera nenhum\vgolpe TM?",
  ["43:528b"] = "Uau!\nCerto novamente!\vVamos para a\vpergunta final:\fO programa de\nradio do PROFESSOR\vCARVALHO é muito\vfamoso.\fMARIE é a DJ do\nprograma?",
  ["43:530b"] = "Legal! Conseguiu!\nParabéns!    \fAqui esta o seu\npremio, o CARTAO\vDE RADIO!",
  ["43:5350"] = "A POKéGEAR de\n{PLAYER} pode ser\vum radio agora!",
  ["43:5375"] = "Sintonize na nossa\nprogramacao.",
  ["43:5399"] = "Desculpe-me, mas\nvoce errou.\fTente de novo!",
  ["43:53d3"] = "Ah, entendo. Tente\nse voce mudar de\vidéia.",
  ["43:5403"] = "BEN é um otimo DJ.\fSua doce voz me\nderrete!",
  ["43:5439"] = "Eu amo MARY, do\nSHOW POKéMON.\fEmbora eu saiba\napenas o que ela\vpareca gostar.",
  ["43:570b"] = "Pode escutar ao\nradio de todo\vlugar. Sintonize!",
  ["43:5740"] = "As cancoes do\nradio podem fazer\vPOKéMONS dormirem.",
  ["43:576d"] = "Por que eles\nqueriam dominar a\vTORRE DE RADIO?",
  ["43:57b5"] = "Perdao. So pessoas\nautorizadas podem\vpassar daqui.\fNao era assim\nantes.\fTem algo de errado\ncom o DIRETOR…",
  ["43:582e"] = "Voce pode ir a\nqualquer lugar\vaqui dentro.\fO DIRETOR esta bem\nde novo, como era\vantes.",
  ["43:5cbf"] = "Temos gravacoes\ndos sons de todos\vos POKéMONS que\vforam achados.\fDevemos ter uns\n200 tipos.",
  ["43:5d89"] = "Funcionamos 24\nhoras por dia para\vtransmitir bons\vprogramas.\fFarei o meu melhor\npara correr contra\vo tempo!",
  ["43:5e69"] = "O DIRETOR esta\nsalvo?",
  ["43:5e80"] = "Obrigado!\nVoce é meu heroi!\fIsso é um presente\nmeu para voce.",
  ["43:5ebf"] = "E o DIA DE SOL.\nIsso ajuda ataques\vde fogo por um\vtempo.",
  ["43:5efa"] = "Agiu de maneira\nexcelente!",
  ["43:6142"] = "E o encaixe para\no CARTAO.",
  ["43:615a"] = "{PLAYER} colocou\no CARTAO.",
  ["43:62b0"] = "Eu escutei ao\nradio enquanto\vestava nas RUINAS.\fEu ouvi um\nprograma estranho\vla.",
  ["43:6306"] = "MARY: Por que?\nPor que tenho que\vpassar por isso?\fMEOWTH, ajude-me!",
  ["43:6349"] = "MARY: Oh! Voce é\nmeu pequeno heroi!\fLevara isso como\nagradecimento?",
  ["43:638d"] = "MARY: E muito bom\npara POKéMONS que\vsabem golpes do\vtipo normal.",
  ["43:686a"] = "V-voce veio me\nresgatar aqui?",
  ["43:6889"] = "Era isso o que\nestava esperando?\fErrado!\nSou um impostor!\fPretendo ser o\nverdadeiro para\veu tomar posse\vdaqui.\fDeseja saber onde\no verdadeiro\vDIRETOR esta?\fClaro, eu te\ncontarei.\fMas so se voce me\nderrotar!",
  ["43:6965"] = "Certo. Vou lhe\ncontar onde ele\vesta.",
  ["43:6988"] = "Nos colocamos\no verdadeiro\vDIRETOR no\vSUBTERRAREO, no\vDEPOSITO.\fEsta no final\ndo SUBTERRANEO.\fMas duvido que\nvoce chegue la.",
  ["43:6b23"] = "Oh? Voce conseguiu\nchegar aqui?\fVoce deve ser um\notimo treinador.\fPretendemos\ndominar essa\vESTA'sAO DE RADIO\ve anunciar nosso\vretorno.\fIsso deve trazer\nnosso chefe\vGIOVANNI de volta\vdo seu treinamento\vsolo.\fVamos recuperar\nnossa gloria\vanterior.\fNao permitirei\nvoce de interferir\vnossos planos.",
  ["43:6c45"] = "Nao! Perdoe-me,\nGIOVANNI!",
  ["43:6d04"] = "DIRETOR: {PLAYER},\nobrigado!\fSuas acoes\ncorajosas salvaram\vtoda a nacao\vPOKéMON.\fEu sei que nao é\nmuito, mas leve\visso aqui.",
  ["43:6d7e"] = "Isso era uma torre\nna CI……\vGOLDENROD.\fMas ela estava\nmuito velha e\vacabada.\fEntao nos a\nsubstituimos pela\vnossa TORRE DE\vRADIO.\fDurante a\ndemolicao, nos\vencontramos algo\vno topo.\fDisseram que\num POKéMON gigante\vsobrevoava por\vGOLDENROD no\vpassado.\fTalvez aquele\nPOKéMON caiu.\fEle devia ser como\naquele que aparece\vna TORRE ESTRANHA\vna CI……\vECRUTEAK.\fBom, é melhor eu\nir ao meu\vESCRITORIO.",
  ["43:7049"] = "DIRETOR: Ola,\n{PLAYER}!\fVoce sabe, eu amo\nPOKéMONS.\fEu construi essa\nTORRE DE RADIO\vpara eu expressar\vo meu amor.\fSeria bom se as\npessoas gostassem\vdos programas\vapresentados na\vnossa RADIO.",
  ["43:70e3"] = "BEN: Voce escuta\na nossa musica?",
  ["44:409f"] = "Ha? Isso é uma\nPOKéDEX, nao é?\vPosso ve-la?\fExistem muitos\ntipos de POKéMONS.\fHa? O que é isso?\nQue POKéMON é\vesse?\fSe parece com os\nestranhos desenhos\vdas paredes das\vRUINAS. \fSe aqueles\ndesenhos sao\vmesmo POKéMONS,\ventao devem haver\vmuito mais.   \fJa sei! Deixe-me\natualizar a sua\vPOKéDEX. Siga-me.",
  ["44:4275"] = " nao se sabe\no significado das\vestatuas POKéMON. \fIsso tudo é um\nenorme mistério…",
  ["44:4461"] = "Um POKéMON que\nvoava com suas\vasas com cores do\varco-iris.",
  ["44:4516"] = "Bem-vindo a esse\nsalao.\fAqui ha painéis\nmoveis feitos\vpor ancioes que\vformam o desenho\vde um POKéMON.\fMova o painel para\nformar uma figura.\fAo lado direito,\nha a descricao\vdesse POKéMON.",
  ["44:45f0"] = "Um POKéMON que se\nesconde no chao.\fSeus olhos nas\ncostas checam o\vlocal.",
  ["44:46e0"] = "Esse POKéMON\nflutuava no mar\vbatendo seus dez\vtentaculos.",
  ["44:47ba"] = "Esse POKéMON\nvoador atacavasuas\vvitimas com presas\vtipo serras.",
  ["44:484a"] = "Ha uma estranha\npresenca aqui…",
  ["44:486d"] = "Essa é uma\ngrande sala, mas\vnada ha aqui.",
  ["44:489b"] = "Esse lugar tem\num estilo muito\vmistico.\fUma espécie de\nforca oculta.",
  ["44:48e5"] = "Lugares atigos\nas vezes sao\vtumbas de reis.\fComo as piramides,\npor exemplo.",
  ["44:4b1e"] = "Pronto! Atualizei\nsua POKéDEX.\fAdicionei uma\nPOKéDEX opcional\vpara os UNOWNS.\fEla os grava na\nordem em que voce\vos capturou.",
  ["44:4bb7"] = "O UNOWN que\ncapturar sera\vgravado.\fCheque para saber\nquantos tipos\vexistem.",
  ["44:4c05"] = "Voce capturou\ntodas formas de\vUNOWNS?\fQue otima\ndescoberta!\fEu ajeitei a\nimpressora para\vo manuseio de\vUNOWNS.\fSinta-se livre\npara usa-la.",
  ["44:4c93"] = "As RUINAS tem\nuns 1500 anos.\fMas nao se sabe\nporque elas foram\vfeitas--ou por\vquem.",
  ["44:4ceb"] = "Quantos tipos de\nPOKéMONS devem\vhaver nas RUINAS?",
  ["44:4d1e"] = "Apareceram\nPOKéMONS nas\vRUINAS?\fQue noticia\nincrivel!\fPrecisaremos\ninvestigar isto.",
  ["44:4d71"] = "Existem simbolos\nraros desenhados\vnas paredes das\vRUINAS.\fEles devem ser a\nchave para revelar\vos mistérios\vdas RUINAS.",
  ["44:4ded"] = "Viu os POKéMONS\nestranhos nas\vRUINAS?\fEles se parecem\nmuito com aqueles\vdesenhos das\vparedes de la.\fHum…Isso deve\nsignificar que\vexistem muitos\vtipos deles…",
  ["44:52b1"] = "Me queimei!",
  ["44:534d"] = "E o fogo do meu\nPOKéMON que\vilumina esta\vcaverna.",
  ["44:5841"] = "O estilo de seu\nPOKéMON é legal\ve colorido, eu\vconfesso.\fVoce sempre\nestara melhorando!",
  ["44:5b06"] = "KURT: Ola,\n{PLAYER}!\fOs guardas acima\nme empurraram\vquando eu os\vgritei.\fMas eu acabei\ncaindo para dentro\vdo PO'sO.\fEu bati minhas\ncostas com forca,\ve nao posso me\vmover.\fRatos! Se eu\ntivesse desmaiado,\vmeu POKéMON os\vpuniria…\fAh, ele nao pode\nser ajudado.\f{PLAYER}, mostre a\neles a sua raiva\vno meu lugar!",
  ["44:6023"] = "Um SLOWPOKE sem a\nsua CAUDA…\fHa? Ele tem uma\nCARTA. Quer Ler?",
  ["44:6061"] = "{PLAYER} le a\nCARTA.\fSeja bom e olhe\npela casa com o\vvovo e o SLOWPOKE.\fCom amor, Papai.",
  ["44:60b9"] = "Um SLOWPOKE sem\na sua CALDA…",
  ["44:624a"] = "Eu vou ser como\num SLOWPOKE.\fEu vou esperar\npacientemente,\ventao vou poder\vver um evoluir.",
  ["44:62c5"] = "As pessoas treinam\nneste FAROL.\fNao é facil subir\ndevido aos\vtreinadores de\vPOKéMONS.",
  ["44:631a"] = "No passado,\nos POKéMONS\viluminavam o mar o\vredor de OLIVINE.\fO FAROL foi\nconstruido em\vhomenagem a estes\vPOKéMONS.",
  ["44:64a1"] = "Hum!\nPerdi!",
  ["44:64af"] = "Que poder! Voce\ngostaria de\vvelejar pelo\vmundo comigo?",
  ["44:6dbd"] = "JASMIM: Este\nPOKéMON sempre\vmanteve o mar\viluminado a noite.\f…Mas ele ficou\ndoente…   \fEle esta\nofegante…\fEu sei que existe\numa FARMACIA\vmaravilhosa na\vCI…… CIANWOOD.\fMas tem que\natravessar o mar…\fEu nao posso\ndeixar AMPHY\vsozinho…",
  ["44:6ea0"] = "…Voce poderia\npegar o REMEDIO em\vCIANWOOD?\fPor favor!",
  ["44:6ed5"] = "JASMINE: …Este\nmedicamento curara\vAMPHY?",
  ["44:6eff"] = "{PLAYER} deu a\nPO'sAO SECRETA a\vJASMINE.",
  ["44:6f26"] = "JASMIM: …Hum, por\nfavor, nao se\vofenda…\n\fA AMPHY nao aceita\nnada de ninguém,\vso de mim…",
  ["44:6f80"] = "JASMIM: …\fAMPHY como se\nsente?",
  ["44:6fa8"] = "JASMIM: …Oh,\nestou aliviada…\fIsto é maravilhoso\namigo!…\fObrigado mesmo,\nmuito obrigado.\f…Voltarei ao meu\nGINASIO.",
  ["44:701b"] = "JASMINE: …Eu entendo…",
  ["44:702d"] = "…AMPHY, aguente!",
  ["44:7055"] = "Sua respiracao\nesta muito\vrapida!…",
  ["45:4126"] = "Arrgh…\nVoce descobriu\vnossa escada\vsecreta…",
  ["45:41bc"] = "Urrgh…\fO POKéMON dragao\ndo cara é\vpoderoso…",
  ["45:41e5"] = "LANCE: DRAGONITE,\nHIPER RAIO.",
  ["45:4204"] = "O que o trouxe,\n{PLAYER}?\fComo eu pensei,\naquele estranho\vsinal de radio\vesta vindo daqui.",
  ["45:4259"] = "As escadas ficam\naqui.",
  ["45:4275"] = "LANCE: {PLAYER},\ndevemos ir checar\vesse lugar.\fEu irei primeiro.",
  ["45:47cd"] = "Ei!\nAlerta intruso!",
  ["45:47e3"] = "Nao… Eu falhei…",
  ["45:47f4"] = "E minha vez!\nNao tem saida!",
  ["45:4814"] = "Existem sensores\nde movimento nas\vestatuas dos\vPOKéMONS.\fApareceremos até\nvoce achar o botao\vsecreto.",
  ["45:4a37"] = "E uma estatua de\num PERSIAN…\fSeus olhos tem um\nbrilho estranho.",
  ["45:4f65"] = "Fique parado ai!",
  ["45:5044"] = "Ei! Nao se ache o\nmelhor. Divirta-se\vpor aqui.",
  ["45:5290"] = "LANCE:\nConseguimos. Nos\vderrotamos todos\vos ROCKETS aqui.\fMas me intrigo com\no jovem rapaz que\veu batalhei por\vaqui…",
  ["45:5306"] = "Perdao, {PLAYER}.\nEu vi como voce\vera bom, entao eu\vrecuei.\fAgora o que resta\nfazer é desativar\vesse estranho\vsinal de radio.",
  ["45:5387"] = "E essa maquina que\nesta causando\vtodos problemas.\fNao vejo um\ninterruptor nela…\fNao temos escolha.\nTemos que\vfazer todos\vos ELECTRODES\vdesmaiarem.\fIsso deve fazer\nessa maquina parar\vde transmitir\vestranhos sinais.\fNao é culpa dos\nPOKéMONS, e isso\vme deixa furioso.\f{PLAYER}, vamos\ncomecar o\vtrabalho.",
  ["45:54a2"] = "LANCE: Eu fico com\neste lado.",
  ["45:54c1"] = "LANCE: Aquele\nsinal estranho\vfinalmente parou.\fO LAGO deve voltar\nao normal.\fVoce é o heroi!\fDeixe-me\nagradece-lo em\vnome de todos os\vPOKéMONS.\fOh, sim. Voce deve\nlevar isso.\fEu achei isso\naqui, mas eu nao\vpreciso disso.",
  ["45:55b0"] = "E o REDEMOINHO.\nEnsine-o a um\vPOKéMON para\vatravessar aguas\vselvagens.\fMas lembre-se\ndisso:\fVoce so pode\nusa-lo fora de\vbatalhas se\vpossuir a INSIGNIA\vdo GINASIO\vMAHOGANY.",
  ["45:564c"] = "{PLAYER}…\fA jornada para se\ntornar um MESTRE\vPOKéMON é longa e\vdificil.\fSabendo disso,\nvoce pretende\vcontinuar?\f…\fEntendo. Nao, voce\ntem razao.\fSe desistisse\nfacilmente, voce\vnunca teria\vseguido o sonho do\vprimeiro lugar.\fEu espero ve-lo\nnovamente!",
  ["45:574f"] = "LANCE: Voce esta\nbem?\fSeu POKéMON esta\nferido e cansado.\fPara isso, lhes de\nalguns dos meus\vremédios.",
  ["45:57af"] = "LANCE: {PLAYER},\nvamos dar o nosso\vmelhor para os\vPOKéMONS.",
  ["45:58d2"] = "Eu perdi na\nultima missao para\vum garoto também.\fQuando estavamos\nmaltratando\vPOKéMONS, esse\vgaroto com longo\vcabelo vermelho e\vcom um estranho\volhar me derrotou…",
  ["45:59f1"] = "A porta esta\nfechada…\fEla precisa da\nsenha para abrir.",
  ["45:5a23"] = "A porta esta\nfechada.\f{PLAYER} usou a\nsenha.\fA porta abriu!",
  ["45:5e2f"] = "LANCE: Precisamos\nde duas senhas\vpara acessar a\vsala do chefe.\fSo alguns ROCKETS\nsabem essas\vsenhas.\fFoi um ROCKET que\nme contou isso.\f{PLAYER}, vamos\nprocurar essas\vsenhas.",
  ["45:5eeb"] = "Urrggh…\nO rapaz com capa é\vincrivelmente\vpoderoso…",
  ["45:61c7"] = "Eu… Nada pude\nfazer…\fGIOVANNI, por\nfavor, perdoe-me…",
  ["45:61fe"] = "Nao, nao posso\ndeixar isso me\vafetar.\fDevo informar aos\noutros…",
  ["45:623b"] = "MURKROW: A senha\né…\fGRANDE GIOVANNI.",
  ["45:6626"] = "A porta esta\nfechada…\fEle usa duas\nsenhas para abrir.",
  ["45:6659"] = "A porta esta\nfechada…\f{PLAYER} usou as\nduas senhas.\fA porta foi\naberta!",
  ["45:6a44"] = "Ah, cara…\nMeu chefe vai\vficar irritado… \fO FARFETCH'D que\nCORTA arvores para\vfazer carvao\vfugiu.\fNao posso\nprocura-lo aqui\vna FLORESTA ILEX.\fEla é grande,\nassustadora e\vescura demais para\vmim.",
  ["45:6b01"] = "Uau! Muito\nobrigado!\fO POKéMON do meu\nchefe nao me\vobedece porque\veu nao tenho\vINSIGNIAS.",
  ["45:6b57"] = "Este é o POKéMON\nperdido.",
  ["45:6b6e"] = "FARFETCH'D: FARF!",
  ["45:6ca8"] = "Deseja aprender\ncomo se fabrica\vcarvao comigo? \fVoce sera o\nprimeiro em dez\vanos!",
  ["45:6d03"] = "O que estou\nfazendo?\fEstou sacudindo as\narvores usando\vCABE'sADA.\fE divertido. Tente\ntambém!",
  ["45:6d55"] = "Balance as arvores\nusando a CABE'sADA.\fTem vezes que os\nPOKéMONS caem\vdormindo.",
  ["46:45c3"] = "Bem-vindo!\fEu comando o SALAO\nPOKéMON.\fDos IRMAOS\nCABELEIREIRO,\veu sou o mais\vvelho e melhor\vcabeleireiro.\fPosso deixar seu\nPOKéMON mais\vbonito por apenas\v¥500.\fVoce quer que eu\nfaca isso?",
  ["46:4664"] = "Em qual POKéMON\neu devo trabalhar?",
  ["46:4682"] = "Certo! Veja como\nficou bonito!",
  ["46:46a2"] = "Isso! Tudo pronto!",
  ["46:46b4"] = "Voce esta certo?\nQue vergonha!",
  ["46:46d3"] = "Voce precisa de\nmais dinheiro que\visso.",
  ["46:46f5"] = "So faco um corte\npor dia.\fEu ja fiz um hoje.",
  ["46:4726"] = "Bem-vindo ao\nSALAO POKéMON!\fEu sou o mais\njovem e barato\vcabeleireiro\vdos IRMAOS\vCABELEIREIROS! \fMudo o visual do\nseu POKéMON por\vapenas ¥300.\fO que voce acha?",
  ["46:47bb"] = "De qual POKéMON\neu devo cortar?",
  ["46:47d8"] = "Bom! Eu melhorarei\no visual!",
  ["46:47f4"] = "Ai esta.\nEsta pronto!",
  ["46:480c"] = "Nao?\nQue chato, cara!",
  ["46:4825"] = "Voce esta com\npouco dinheiro.",
  ["46:4845"] = "Eu so faco um\ncorte por dia.\fPerdao, eu ja\ntrabalhei muito\vhoje.",
  ["46:4889"] = "{STRBUF} parece\num pouco feliz.",
  ["46:48a6"] = "{STRBUF} parece\nfeliz.",
  ["46:48b8"] = "{STRBUF} parece\nencantado!",
  ["46:48ce"] = "Nao estamos\nabertos hoje.",
  ["46:4f27"] = "…Por que…\nPor que eu perdi?\fEu escolhi o\nPOKéMON mais\vforte.\fEu nao facilitei.\fMas por que eu\nperdi?",
  ["46:4f8c"] = "…Eu nao entendo…\fSera que o LANCE\ndisse a verdade?  \fQue eu nao trato\ndireito os\vPOKéMONS?\fAmor…\fConfianca…\fE disso mesmo que\neu preciso?\fEles estao me\nimpedindo de\vvencer?\fEu… eu nao\nentendo.\fMas isso nao vai\nacabar aqui.\fNao agora. Nao\ndevido a isso.\fNao desistirei do\nmeu sonho de me\vtornar o melhor\vtreinador POKéMON\vdo mundo!",
  ["46:5140"] = "Eu fui desafiado\npara uma batalha\vla embaixo.\fLa é muito\ndesagradavel.\fTome cuidado.",
  ["46:519a"] = "Ha algumas Lojas\nai em baixo…\fMas ha treinadores\ntambém la.\fEu tenho medo de\ndescer la!",
  ["46:5795"] = "Ei, garoto! Voce\nesta atrapalhando.\fNosso dever é\ntrabalhar em luga-\vres onde ninguém\vnos veja!",
  ["46:57f7"] = "Eu perco a\npaciencia quando\valguém me ve\vtrabalhando.\fEi, garoto,\nfuja.",
  ["46:5840"] = "Oohah! Oohah!\fO negocio no chao\né um lixo.\fLeve-o se voce\nquiser!",
  ["46:5c24"] = "DIRETOR: Use-o\npara abrir persi-\vanas no 3ü ANDAR.",
  ["46:5c56"] = "Estou implorando\npela sua ajuda.\fNem imagino o\nque eles farao se\vcontrolarem o\vtransmissor.\fEles podem até\ncontrolar POKéMONS\vusando um sinal\vespecial!\fVoce é o unico que\neu posso confiar.\fPor favor, salve\na TORRE DE RADIO…\fE toda a nacao\nPOKéMON!",
  ["46:5f3d"] = "Ei!\fEu sou o REI\nCARATE!\fEu treino sozinho\naqui no escuro!\fVoce! Batalhe\ncomigo!\fHwaarggh!",
  ["46:5f99"] = "Arrrgghh!\nFui derrotado!",
  ["46:5fb0"] = "Eu… Eu fui\ntriturado…\fMeu treinamento\nainda nao é o\vbastante…\fMas uma derrota é\numa derrota.\vEu admito.\fComo prova que\nme derrotou, eu\vlhe darei um raro\vPOKéMON lutador.",
  ["46:6045"] = "{PLAYER} recebeu\nTYROGUE.",
  ["46:605a"] = "TYROGUE é do tipo\nlutador.\fEle evolui em um\nPOKéMON mais\vforte.\fContinue treinando\nduro.\fEu também\vtreinarei.\fAté mais!",
  ["46:60cf"] = "Nao tem lugar na\nsua equipe!",
  ["46:6267"] = "Esta todo\nimobilizado no\vgelo.",
  ["47:438b"] = "Uau! Voce me\nsurpreendeu!\fEstava de\nOCULOSESCURO, dai\vnem notei sua\vpresenca. \fO que eu faco\naqui?\fEi, nao se\npreocupe com isso.\fEu lhe darei\num par de\vOCULOSESCURO,\ventao esqueca que\vme viu, certo?",
  ["47:4458"] = "Os OCULOSESCURO\najuda golpes do\vtipo escuro.",
  ["47:459c"] = "CLAIR: Certo.\nEu reconheco o\vseu poder real.\fEsta INSIGNIA é\nsua.",
  ["47:45e1"] = "{PLAYER} foi\npresenteado com\vuma INSIGNIA\vCRESCENTE do\vGINASIO da VILA\vBLACKTHORN.",
  ["47:45fa"] = "A INSIGNIA CRES-\nCENTE permitira\vseu POKéMON usar o\vgolpe para escalar\vcachoeiras.\fE seu POKéMON o\nreconhecera como\vum treinador e\vobedecera todas\vas ordens sem\vquestionar.\fE eu também quero\nque voce leve\visso aqui.",
  ["47:46d6"] = "Isto contém o\nSOPRO DRAGAO.\fNao tem nada a ver\ncom a ver com o\vmeu sopro.\fSe nao quiser,\nvoce nao é\vobrigado a levar.",
  ["47:4754"] = "Entao voce\ncolecionou todas\vas INSIGNIAS.\fSua destinacao é\na LIGA POKEMON no\vPLANALTO INDIGO.\fVoce sabe como\nchegar la?\fDaqui, va a\nCIDADE NEW BARK.\fDepois SURFE ao\nleste. Aquela rota\vé bem dificil.\fNao se atreva a\nperder na LIGA\vPOKEMON!\fCaso o faca, me\nsentirei pior\vainda do que ter\vperdido para\vvoce!",
  ["47:48d6"] = "…\nO que? {PLAYER}?\f…Nao batalharei com\nti agora…\fMeus POKéMONS nao\nestao prontos para\vos seus.\fNao posso exigir\nmuito agora.\fTenho que ser\ndisciplinada para\vtornar-me a melhor\vtreinadora POKéMON\vde todos os\vtempos.",
  ["47:4980"] = "…\fBom…\fAprenda a ficar\nlonge do meu\vcaminho…",
  ["47:49a6"] = "{PLAYER} achou o(a)\n{STRBUF}!",
  ["47:49b8"] = "Mas {PLAYER} nao\npode pegar mais\vitens.",
  ["48:4101"] = "Uau, sua POKéGEAR\né incrivel!\fFoi sua mae quem\nlhe deu ela?",
  ["48:413e"] = "Ei, {PLAYER}!",
  ["48:4148"] = "O que voce esta\ntentando fazer?",
  ["48:4168"] = "E perigoso sair\nsem um POKéMON,\vnao sabia?\fOs POKéMONS\nselvagens aparecem\vda grama para\vlutar nessas\vrotas.",
  ["48:41ce"] = "Ah! Seu POKéMON\né amavel. Queria\vum para mim!",
  ["48:41fc"] = "Oi, {PLAYER}!\nSaindo de novo?\fVoce deve avisar\na sua mae que\vja vai sair!",
  ["48:4240"] = "Ligue sempre do\ncelular para sua\vmae, e lhe diga\vseu estado.",
  ["48:427e"] = "Oi, {PLAYER}!\fEu ouvi dizer\nque encontraram\vnovos POKéMONS!",
  ["48:42d7"] = "… O que voce esta\nolhando?",
  ["48:45ae"] = "Voce é um treina-\ndor novato, nao é?\vEu ja sabia!\fTudo bem!\nTodos sao novatos\vem alguma coisa.\fSe voce quiser,\nte ensino umas\vcoisas.",
  ["48:463a"] = "Tudo bem!\nSiga-me!",
  ["48:4650"] = "Este é o CENTRO\nPOKéMON. Eles\vajudam seu POKéMON\va qualquer hora!  \fSeu POKéMON confia\nmuito em voce,\vpor isto é melhor\ventende-lo!",
  ["48:46cf"] = "Esta é a LOJA\nPOKéMON.\fEles vendem\nPOKé\nBOLAS, para pegar\vPOKéMONS, e outros\vitens super uteis.",
  ["48:4724"] = "Existem POKéMONS\nna ROTA 30.\fOs treinadores vao\nlutar com seus\vPOKéMONS nesta\vROTA!",
  ["48:4772"] = "Este é o mar, como\nvoce pode ver.\fVarios POKéMONS\nsao encontrados na\vagua.",
  ["48:47b7"] = "Ei…\fEsta é minha casa.\nObrigado pela\vcompanhia.\fVou lhe dar um\npresente!",
  ["48:481c"] = "A POKéGEAR se\ntornou mais util\vdo que ja era! \fEu desejo sorte\nna sua jornada.",
  ["48:48ad"] = "…\fVoce pegou\num POKéMON no\vLABORATORIO?\fQue pena! Porque\nvoce vai ter que\vlutar.\fEu tenho um\nPOKéMON também.\fNa verdade, um\notimo POKéMON.\fVou lhe mostrar\ncomo sou bom!",
  ["48:4942"] = "Hum… Voce\nrealmente venceu!\n",
  ["48:4961"] = "…\fMeu nome? \fVou viajar, e\nme tornar um\vtreinador melhor\vque voce.",
  ["48:49a5"] = "Isto é um\ndesperdicio de\vtempo.",
  ["48:49c7"] = "…\fMeu nome?   \fEu vou me tornar o\nmelhor treinador\vPOKéMON do\vmundo.",
  ["48:4a0b"] = "Voce falou com\no velho proximo\vao CENTRO POKéMON?\fEle coloca um\nmapa dentro da\vsua POKéGEAR.",
  ["48:4a63"] = "Quando voce viaja\ncom seu POKéMON,\vé divertido.",
  ["48:4a91"] = "A casa do SENHOR\nPOKéMON esta um\vpouco longe.",
  ["48:4abc"] = "Eu batalhei com\nuns treinadores.\fMeu POKéMON\nperdeu. Nao\vtreinei ele bem!\fDai o levei ao\nCENTRO POKéMON.",
  ["48:4b21"] = "O POKéMON que\npeguei tinha um\vitem.\fEra a\nAGUA MISTICA.\fEu nao preciso\ndela, voce a quer?",
  ["48:4b7c"] = "Entao va pescar\ncomo eu\vfaco.",
  ["48:4d62"] = "Ooh, la la! Isso\né muito bom!",
  ["48:4d81"] = "Entao é isso?\nVoce tem que\vestudar! Venha!",
  ["48:4daf"] = "Ei, eu sou\nprofessor.\fE bom voce estudar\naqui!",
  ["48:4ddf"] = "Dizem que existem\nfantasmas na\vTORRE BROTINHO.\fE que tipos\nnormais de\vPOKéMONS nao fazem\vnenhum efeito\vneles.",
  ["48:4e49"] = "Voce é um treina-\ndor POKéMON?\n \fSe vencer o\nLIDER desse\vGINASIO, voce\vprovara que é\vmuito bom!",
  ["48:4ea5"] = "FALKNER, o lider\ndo GINASIO DA\vCI…… VIOLETA\vé um otimo\vtreinador.\fEle herdou o\nGINASIO do pai e\vagora esta\vfazendo um bom\vtrabalho com ele.",
  ["48:4f1b"] = "Eu vi uma\narvore doida por\vaqui!\fSe toca-la,\nela requebra e\vdanca! E legal!",
  ["48:51b9"] = "{PLAYER}s……{PLAYER}o……{PLAYER}",
  ["48:51e7"] = "…Diga-me a\nresposta.\fE verdade que a\nEQUIPE ROCKET\vretornou?\fO que? Voce os\nderrotou? Ah!\vMentiroso.\fIsso nao é piada?\nVamos ver se voce\vé bom mesmo.",
  ["48:5280"] = "… Humph! POKéMON\ninutil!\fEscute cara, so\nvenceu porque meus\vPOKéMONS sao\vfracos.",
  ["48:52cd"] = "Odeio treinadores\nPOKéMON fracos. \vNao importa quem\vou o que.\fEu serei forte e\nvou exterminar os\vfracos.\fIsso serve para\na EQUIPE ROCKET\vtambém.\fEles sao poderosos\nquando em grupo.\fMas sozinhos eles\nsao uns fracos.\fEu odeio todos\neles.\fE voce desapareca.\nUm fracote como\vvoce é apenas uma\vdistracao.",
  ["48:53f5"] = "…Humph! Sabia que\nvoce mentia.",
  ["48:5415"] = "E inseguro ir la\ndentro, mas eu\vestarei atento.\fNao sou um Bom\nSamaritano?",
  ["48:5461"] = "Voce sabe algo do\nRABOSLOWPOKE?\vSoube que é otimo!\vNao fica feliz\vsabendo disso?",
  ["48:54b5"] = "Os SLOWPOKES\ndesapareceram da\vcidade…\fSoube que suas\nCALDAS sao\vvendidas por ai.",
  ["48:550d"] = "Os SLOWPOKES\nvoltaram.\fConhecendo eles,\nsei que nao\vestavam passeando\vem algum lugar.",
  ["48:5568"] = "Veio aqui para que\nKURT faca BOLAS\vpara voce?\fMuitas pessoas so\nfazem isso.",
  ["48:564a"] = "SLOWPOKE: …\f……………",
  ["48:565d"] = "………Yawn?",
  ["48:5936"] = "Voce cruzou o mar\npara chegar aqui?\fDeve ter sido\nduro.\fIsto seria mais\nfacil se seu\vPOKéMON tivesse\va técnica VOAR…",
  ["48:5a28"] = "E a INSIGNIA DA\nTEMPESTADE!\fEntao voce pode\nlevar o HM!",
  ["48:5a62"] = "Ensine VOAR ao\nseus POKéMONS.\fVoce podera voar\nrapidamente para\vum lugar que voce\vja visitou.",
  ["48:5abc"] = "Meu marido perdeu\npara voce, entao\vele precisa\vtreinar.\fQue bom, porque\nele ja estava\vficando gordo.",
  ["48:5b24"] = "Se voce usar o\nVOAR, voce voltara\va OLIVINE\vrapidamente.",
  ["48:5ec3"] = "Eles contruiram\na nova TORRE\vde RADIO para\vsubstituir a velha\vque estava em\vruinas.",
  ["48:5f06"] = "Eu sei que tem uma\nnova LOJA DE\vBICICLETAS, mas\veu nao consigo\vencontra-la.",
  ["48:5fd0"] = "A TORRE DE RADIO\nem GOLDENROD é um\vponto turistico.\fEles estao fazendo\numa campanha\vpromocional agora\vmesmo.\fEstao modificando\nas POKéGEARS, que\vpoderao funcionar\vcomo radios!",
  ["48:6071"] = "Oh, sua POKéGEAR\nfunciona como um\vradio!",
  ["48:6093"] = "E-he-he-he…\fEu me encrenquei\npor jogar no\vporao da LOJA DE\vDEPARTAMENTOS.",
  ["48:60e0"] = "O homem daquela\ncasa altera os\vnomes dos\vPOKéMONS.\fEle pode alterar\nos dos seus.",
  ["48:612c"] = "Uau! Essa é uma\ngrande cidade.\fEu nao sei onde\nficam as coisas.",
  ["48:616a"] = "Entao essa é a\nTORRE DE RADIO…",
  ["48:6187"] = "O que voce quer,\nseu peste? Saia\vdaqui!",
  ["48:61ab"] = "Saia do meu\ncaminho, idiota!",
  ["48:61ca"] = "Roubar esta TORRE\nDE RADIO…\fO que? Isto nao é\nda sua conta!",
  ["48:6207"] = "POKéMONS? Eles nao\nsao nada mais\vque fabricas de\vdinheiro!",
  ["48:623f"] = "Um dia nosso\nsonho sera real…\fFoi um grande\nempenho…",
  ["48:627c"] = "Ei, pirralho! Voce\nnao é deste lugar.\fSaia daqui!",
  ["49:4235"] = "As estradas\nescuras sao\vperigosas. \fMas no periodo da\nnoite, o mar é\vaté mais\vtraicoeiro!\fSem a luz do FAROL\npara iluminar o\vmar, nenhum navio\vpode velejar\vpela noite!",
  ["49:42e1"] = "Aquela coisa que\nvoce tem é uma\vPOKéGEAR certo?\vUau, incrivel.",
  ["49:431e"] = "Uau, voce tem uma\nPOKéDEX!\fIsto é tao legal!",
  ["49:434e"] = "Ola, treinador!\nO mar esta doce!\fCante comigo!\nYo-ho! Temos que\vpegar POKéMONS…",
  ["49:4604"] = "ECRUTEAK tem duas\ntorres:\fuma ao leste e\noutra ao oeste.",
  ["49:4646"] = "Ah, jovem.\nVoce aprendeu a\vdancar como as\vGAROTAS KIMONO?\fSe ir ao seu\nTEATRO DE DAN'sA,\vum estranho senhor\vlhe dara algo\vmuito bom, eu ouvi\vdizer.",
  ["49:46de"] = "Eu vou praticar no\nTEATRO DE DAN'sA.\fSe importa de ir\ncomigo?",
  ["49:471d"] = "Ela era para ser a\ntorre mais alta,\vmas ela foi\vqueimada pelo\vfogo.",
  ["49:4761"] = "Tres grandes\nPOKéMONS correram\vpara direcoes\vdistintas.\fQuem foram eles?",
  ["49:47a4"] = "Ouvi um boato\nsobre o FAROL DE\vOLIVINE.\fO POKéMON que\nservia como guia,\vficou doente.\fParece que eles\nestao encrencados.",
  ["49:481d"] = "O POKéMON no FAROL\nDE OLIVINE foi\vcurado.\fAgora os barcos\npodem navegar\vseguros pela\vnoite.",
  ["49:487e"] = "Ouvi dizer que os\nPOKéMONS estao\vfazendo alvorocos\vno LAGO DA RAIVA.\vEu gostaria de ver\visto.",
  ["49:4c03"] = "Bom! Muito bom!",
  ["49:4c14"] = "Nao tem o valor\nnecessario.",
  ["49:4c31"] = "Oh, tudo bem…",
  ["49:4c41"] = "Nao tem lugar\npara isso.",
  ["49:4cda"] = "As MAGIKARPS\nretornaram ao LAGO\vDA RAIVA.\fIsso deve ser uma\nboa noticia para\vos pescadores de\vla.",
  ["49:4d33"] = "Como chegou a esse\nponto, dedique-se\vpara fazer coisas\vimportantes.\fVoce deve ir ao\nnorte e checar o\vLAGO DA RAIVA\vagora.",
  ["49:4daf"] = "Visite a Loja da\nVovo.\fEla vende coisas\nque ninguém tem.",
  ["49:5063"] = "Esse lago é cheio\nde GYARADOS e\vnada mais…\fIsso porque as\nMAGIKARPS sao\vforcadas a\vevoluir…",
  ["49:50c0"] = "Voce veio aqui\ndevido aos boatos?\fVoce é {PLAYER}?\nEu sou LANCE, um\vtreinador como\vvoce.\fEu ouvi boatos,\nentao eu vim aqui\vinvestigar…\fEu vi a maneira\nque batalha,\v{PLAYER}.\fPosso lhe dizer\nque é um treinador\vcom grandes\vhabilidades.\fSe nao se\nimportar, poderia\vme ajudar a\vinvestigar?",
  ["49:51d2"] = "LANCE: Descobri! \fParece que as\nMAGIKARPS do LAGO\vsao forcadas a\vevoluir.\fUm misterioso\nprograma de radio\vvindo de MAHOGANY\vé o responsavel.\fEstarei te\naguardando,\v{PLAYER}!",
  ["49:527d"] = "Oh… Bem, se\nmudar de idéia,\vvenha me ajudar.",
  ["49:52b1"] = "LANCE: Hm? Voce\nvai me auxiliar?",
  ["49:52eb"] = "{PLAYER} obteve uma\nESCAMA RUBRA.",
  ["49:532d"] = "Hahah!\nAs MAGIKARPS estao\vmordendo!",
  ["49:549b"] = "Eu nao perco como\npescador!\fPego POKéMONS o\ndia todo.",
  ["49:5690"] = "WESLEY: Ola, como\nvai voce? Como\vsabe, hoje é\vQuarta-feira.\fSou WESLEY, das\nQuartas.",
  ["49:56e9"] = "Prazer em\nconhece-lo.\fLeve uma\nlembrancinha.",
  ["49:5717"] = "WESLEY: A\nFAIXAPRETA melhora\vos golpes do tipo\vluta.",
  ["49:5750"] = "WESLEY: Como me\nachou, voce deve\vter conhecido meus\virmaos e irmas.\fOu voce apenas\nteve sorte?",
  ["49:57b5"] = "WESLEY: Hoje nao\né Quarta. E uma\vpena.",
  ["49:5ad0"] = "So usuarios de\ndragoes podem\vtreinar aqui.\fSaia por favor.",
  ["49:5b0e"] = "Como CLAIR, a\nmestra em dragoes,\vpermitiu, voce\vpode entrar.",
  ["49:5b4e"] = "Meu radio esta\nquebrado?\fE depois eu so\nrecebia esse\vestranho sinal.",
  ["49:5b87"] = "Aroo! Vozes na\nminha cabeca!\fHa? Estou ouvindo\no radio!",
  ["49:5bc1"] = "Voce fara\nseus POKéMONS\vesquecerem alguns\vgolpes?",
  ["49:5bf5"] = "Serei um usuario\nde dragoes como\va CLAIR.",
  ["49:5c1f"] = "SANTOS: …\fE Sabado…\fSou SANTOS dos\nSabados…",
  ["49:5c4f"] = "Leve isso aqui…",
  ["49:5c63"] = "SANTOS: …\fTALAOENCANTO.\fGolpes\ntipo fantasma\vmelhorarao.\fVai\nimpressiona-lo…",
  ["49:5cae"] = "SANTOS: …\fTe vejo em outro\nSabado…\fEu nao terei mais\nnenhum presente…",
  ["49:5cf8"] = "SANTOS: Hoje nao é\nSabado…",
  ["49:5d16"] = "Uau, voce\natravessou o\vCAMINHO DE GELO?\fVoce é\num treinador\vcorajoso!",
  ["4a:4386"] = "Eu derrotei os\noito LIDERES DE\vGINASIO, por isso\vestou confiante.\fDevo treinar mais\npara a proxima.",
  ["4a:446e"] = "POKéMONS nao sao\narmas de guerra.",
  ["4a:4488"] = "Os POKéMONS sao\namigos sem valor\vmonetario.",
  ["4a:4527"] = "As pessoas e os\nPOKéMONS crescem a\npartir de suas\vexperiencias.\fNao seja um inutil\ne preguicoso.",
  ["4a:486a"] = "Ei!",
  ["4a:4870"] = "Sabe o que acabou\nde fazer?\fVoce deu seu\nprimeiro passo em\vKANTO.\fOlhe o MAPA da sua\nPOKé GEAR e\vconfira.",
  ["4a:4c39"] = "Piu!",
  ["4a:4d4d"] = "{PLAYER}{RIVAL}dROTA 28.",
  ["4a:4ed2"] = "Os POKéMONS se\nescondem na grama.\fEles aparecem\nde repente!",
  ["4a:4f0a"] = "Eu nunca o vi por\naqui, amigo.\fQuantos POKéMONS\nvoce ja capturou?\fQuer que eu te\nensine a capturar\vPOKéMONS, amigo?",
  ["4a:4f78"] = "E assim que se\ncaptura!\fSe voce os\nenfraquecer\vprimeiro, sera\vmais facil!",
  ["4a:4fc2"] = "Tudo bem! \fMesmo assim,\nse voce quiser\vpegar todos, voce\vtem que procurar.",
  ["4a:500e"] = "Como? Voce quer\nque ensine a\vcaptura-los agora?",
  ["4a:503f"] = "Oi. Como vai seu\nPOKéMON?\fSe seu POKéMON\nestiver fraco,\vfique longe de\vareas com essas\vgramas!",
  ["4a:5097"] = "Esta vendo estas\nelevacoes? Nao da\vpara pula-las de\vbaixo!\fPara ir a NEW\nBARK, voce deve\vseguir a grama.",
  ["4a:5104"] = "Eu desejei\ndescansar e por\visto eu salvei\vo meu progresso!",
  ["4a:5177"] = "Eu estou esperando\npelos POKéMONS\vnoturnos.",
  ["4a:51a7"] = "Eu estou esperando\npelos POKéMONS\vda manha.",
  ["4a:51dd"] = "TUSCANY: Eu nao acredito, essa é a primeira vez que nos encotramos?\fPermita que eu me apresente a voce.\fEu sou TUSCANY da Terca.",
  ["4a:525a"] = "Como introducao,\npor favor aceite\vesse presente, o\vARCO ROSA.",
  ["4a:529a"] = "TUSCANY: Voce nao\nacha adoravel?\fIsso fortalece\ngolpes do tipo\vnormal.\fTenho certeza que\ntera utilidade.",
  ["4a:5312"] = "TUSCANY: Voce ja\nconheceu M'lNICA,\vminha irma mais\vvelha?\fOu meu irmao mais\nnovo, WESLEY?\fEu sou a segunda\nde sete criancas.",
  ["4a:5384"] = "TUSCANY: Hoje nao\né Terca. Que coisa\vtriste…",
  ["4a:5592"] = "{PLAYER}E",
  ["4a:5595"] = "{PLAYER}g",
  ["4a:55ad"] = "Vai RATTATA!\fAGARRAR!",
  ["4a:55c3"] = "O que? E uma\ngrande batalha!\fSaia daqui!",
  ["4a:581a"] = "Todos se divertem\nbatalhando. Voce\vdevia também!",
  ["4a:584a"] = "Nao sou\ntreinadora.\fMas se olhar meu\nolhos um vez,\vprepare-se para\vbatalhar.",
  ["4a:5b1e"] = "CAVERNA ESCURA…\fSe meu POKéMON\ntivesse LUZES, eu\va exploraria.",
  ["4a:5bf8"] = "…Puxa …Ha?\fEu andei bastante\nhoje procurando\vPOKéMONS.\fMeus pés estao\nferidos e eu estou\vsonolento…\fSe eu fosse um\nPOKéMON selvagem,\veu seria capturado\vfacilmente…\f…Zzzz…",
  ["4a:5c80"] = "…Zzzz… Ha?\fO que foi? Voce\ntem uma CARTA para\vmim?",
  ["4a:5caf"] = "{PLAYER} entregou o\nPOKéMON segurando\va CARTA.",
  ["4a:5cd9"] = "Vamos ver…\f…CAVERNA ESCURA\nvai a outra rota…\fE bom saber disto.\fObrigado por\ntrazer a CARTA\vpara mim.\fMeu amigo é um\nbom rapaz, e voce\vé uma pessoa legal\vtambém!\fEu gostaria de\nlhe dar algo em\vtroca!\fEu sei! Eu quero\nque voce leve\visso!",
  ["4a:5dbb"] = "O TM50 é o\nPESADELO.\fE um golpe perigo-\nso que reduz\vconstantemente o\vPS de um inimigo\vadormecido.\fOoooh…\nIsso é assustador…\fNao quero ter\nsonhos ruins.",
  ["4a:5e46"] = "Essa CARTA nao é\npara mim.",
  ["4a:5e5e"] = "Por que esse\nPOKéMON é tao\vespecial?\fEle nao tem\nCARTA.",
  ["4a:5e97"] = "O que? Voce nao\nquer nada?",
  ["4a:5eb6"] = "Se eu tirar esse\nPOKéMON de voce,\vo que usara para\vpara batalhar?",
  ["4a:5efa"] = "Peguei um bom\nPOKéMON na\vCARVERNA ESCURA.\fDesafiarei meu\namigao, o FALKNER.\fEle é o lider do\nGINASIO DA CI……\vVIOLETA.",
  ["4b:42a5"] = "Espere!\nPor que a pressa?",
  ["4b:42c0"] = "E ai {PLAYER}?\nUm cara usando\voculos procurava\vpor voce.\fConverse com ele.\nO rapaz o espera\vla no CENTRO\vPOKéMON.",
  ["4b:43c5"] = "Voce ja foi ao\nGINASIO POKéMON? \fVoce pode testar\nvoce e seu POKéMON\vno GINASIO.\fTodos treinadores\nprecisam ir até\vla!",
  ["4b:443a"] = "Voce tem bons\nPOKéMONS com voce.\fDeve ser devido\nao treinamento\fdeles ao redor da\nCI…… VIOLETA. \fO treinamento\nno GINASIO deve\fter ajudado\nbastante.\fComo lembranca da\nCI…… VIOLETA,  \vleve isso aqui.\fIsso melhora o\npoder dos POKéMONS\vdo tipo grama.",
  ["4b:452a"] = "Suas experiencias\nna CI…… VIOLETA \vserao uteis na\vsua aventura.",
  ["4b:456e"] = "Voce gostaria de\nter esse gostoso\ve nutritivo \vRABOSLOWPOKE?\fPara voce faco por\napenas ¥1,000,000!\fVoce vai querer!",
  ["4b:45e4"] = "Ah! Achei\nque os jovens\vde hoje eram\vricos…",
  ["4b:4611"] = "Voce nao quer?\nPoxa! Mas que\vpena!",
  ["4b:4765"] = "udar as coisas\vpara mim.",
  ["4b:4a3e"] = "Se nao quiser lu-\ntar, afaste-se dos\vtreinadores.",
  ["4b:4ad2"] = "Pega leve meu\namigo!",
  ["4b:4aed"] = "Estava rolando\num papo legal.",
  ["4b:4c4e"] = "FRIEDA: Oba!\nHoje é Sexta!\fSou FRIEDA da\nSexta! Prazer em\vconhece-lo!",
  ["4b:4c91"] = "Aqui esta uma\nBARBA VENENO para\vvoce.",
  ["4b:4caf"] = "FRIEDA: De isso\na um POKéMON que\vtenha ataques do\vtipo veneno.\fOh!\fE perigoso!\fVoce\nficara chocado\vquando ver os\vresultados nos\vgolpes do tipo\vveneno!",
  ["4b:4d27"] = "FRIEDA: Ola!\nDe qual dia voce\vgosta?\fEu amo Sexta.\nSem duvida alguma!\fVoce nao acha\notima também?",
  ["4b:4d8c"] = "FRIEDA: Nao é\nSexta hoje?\fE chato quando\nnao é Sexta!",
  ["4b:52d5"] = "{PLAYER}q",
  ["4b:52d8"] = "{PLAYER}/",
  ["4b:54ea"] = "Quem esta ai?\nE quem voce é?",
  ["4b:550f"] = "Voce é poderoso,\ngarotinho!",
  ["4b:552a"] = "Sim, nao vi nada\nerrado hoje.\fVoce é bom, fique\nfora de encrencas!",
  ["4b:5570"] = "Estou patrulhando\na procura de\vpessoas suspeitas.",
  ["4b:5688"] = "IRENE: Minha irma\nKATE vai ganhar\vde voce.",
  ["4b:56b6"] = "IRENE: Esta praia\nnao é boa?\fE o nosso refugio\nsecreto.",
  ["4b:5c4d"] = "A musica do radio\nmuda o humor\vdos POKéMONS\vselvagens!",
  ["4b:5cd0"] = "Fui humilhado em\nfrente a minha\vnamorada…",
  ["4b:5f61"] = "Entendo. E assim\nque voce batalha!",
  ["4b:6037"] = "Perigos espreitam\na noite!",
  ["4b:6053"] = "Droga!",
  ["4b:605c"] = "Voce sabe que a\nnoite é pura\vadrenalina,\vnao é?\fMas nao se exceda!",
  ["4b:60a3"] = "Seu POKéMON\nparece forte.\fVoce pode ir a\ntodo lugar com\vseguranca!",
  ["4b:63a7"] = "Wa-hey!\fEu ia destruir\naquela arvore\fcom a forca dos\nmeus bracos.\fMas nao consegui!\nQue fiasco!",
  ["4b:6408"] = "Voce destruiu\naquela arvore\vvelha?\fIsso é muito\nlegal! \fLeve isso aqui.",
  ["4b:6464"] = "Aparenta ser o\nQUEBRA PEDRA.\fVoce pode quebrar\npedras com um\vsimples uso de\vforca.\fSe tiver pedras\nno seu caminho,\vapenas de um fim\vnelas!",
  ["4b:64f0"] = "Uma arvore rara\nesta na rota para\va CI…… GOLDEN-\vROD.\fEla me impede de\nfazer compras.\fAlgo deve ser\nfeito acerca\vdisto.",
  ["4b:6568"] = "Aquela arvore\ndesapareceu sem\vnenhum rastro.\fOh! A arvore era\nmesmo um POKéMON?",
  ["4b:65e8"] = "Eu seria forte se\nso eu pudesse\vcontar o que meu\voponente pensa.",
  ["4b:665a"] = "Opa! Erro de\ncomputacao?",
  ["4b:6674"] = "Droga. Eu estudo\ncinco horas por\vdia.\fNem tudo que\nse aprende esta\vescrito nos\vlivro.",
  ["4b:66cc"] = "ARTHUR: Quem é\nvoce?\fEu sou ARTHUR da\nQuinta.",
  ["4b:66f9"] = "Ei. Leve isso com\nvoce.",
  ["4b:6713"] = "ARTHUR: Um POKéMON\nque usa golpes do\vtipo pedra deve\vsegurar isto.\fEle melhora\nos ataques do tipo\vpedra.",
  ["4b:6776"] = "ARTHUR: Eu sou\nARTHUR da Quinta.\fFui o segundo a\nnascer de sete\vcriancas.",
  ["4b:67bf"] = "ARTHUR: Hoje nao\né Quinta. Que\vtristeza.",
  ["4c:41e5"] = "Fazer os POKéMONS\ndormirem ou\vparalisa-los sao\vboas técnicas de\vbatalha.",
  ["4c:422d"] = "SUNNY: Oi! Eu sou\nSUNNY do Domingo.\fIsso significa\nque hoje é\vDomingo!",
  ["4c:4269"] = "Me disseram para\nte dar isso se eu\vte visse.",
  ["4c:4294"] = "SUNNY: Aquela\ncoisa…\fHum…\f… O que era\naquilo…\f…\fOh! Agora eu\nlembrei!\fUm POKéMON que\nsabe golpes\velétricos deve\vsegurar isso.\fMinha irma M'lNICA\ndisse que isso\vmelhora golpes do\vtipo elétrico!",
  ["4c:4336"] = "SUNNY: Meus irmaos\nsao: M'lNICA,\vTUSCANY, WESLEY,\vARTHUR, FRIEDA e\vSANTOS.\fTodos eles sao\nmais velhos que\veu!",
  ["4c:43a8"] = "SUNNY: Hoje nao\né Domingo? Hum…\vEu esqueci!",
  ["4c:4661"] = "Eu nao estudei\nbem, eu acho.",
  ["4c:4681"] = "Eu tenho que fazer\nmais testes, mas\veu nao tenho tempo\vpara POKéMONS!\fQuando jogo sério,\neu me concentro\vbastante.",
  ["4c:472e"] = "Entendo. Voce\nbatalha assim, né?",
  ["4c:4752"] = "Eu conheco algo\nbom!\fO leite da FAZENDA\nMOOMOO é famoso\vpelo sabor.",
  ["4c:4872"] = "Todas as pessoas\ndo mundo vivem\valegremente com\vseus POKéMONS!",
  ["4c:4b10"] = "Meus POKéMONS\nforam capturados\ve criados no\vexterior.\fEles sao meus\ncompanheiros nas\vlongas viagens.",
  ["4c:4ccd"] = "Ooh, seus POKéMONS\ntem potencial.",
  ["4c:4ced"] = "Voce sabia que\nos POKéMONS tem\vhabilidades\vdistintas?\fAs pessoas sao\nassim também.\fTodos tem diferen-\ntes potenciais.",
  ["4c:4fd7"] = "A CI…… CIANWOOD\né bem longe daqui.",
  ["4c:5183"] = "Embora voce nao\nconsiga ver daqui,\vCIANWOOD esta apos\vo mar.",
  ["4c:51c4"] = "M'lNICA: Fico feliz\nem conhece-lo.\vEu sou M'lNICA da\vSegunda.",
  ["4c:51f4"] = "Como prova da\nnossa amizade, eu\vlhe darei um\vpresente.",
  ["4c:522a"] = "M'lNICA: E um\nitem que melhora o\vpoder dos golpes\vdo tipo voador.\fVoce deve equipar\num POKéMON passaro\vcom este item.",
  ["4c:529a"] = "M'lNICA: Meus\nirmaos estao em\vtodos os lugares.\fTente achar todos\neles!",
  ["4c:52f5"] = "M'lNICA: Eu acho\nque hoje nao é\vSegunda. Que pena…",
  ["4d:44a2"] = "O que esta havendo\nno LAGO DA RAIVA?\fPlanejavamos\nacampar la.",
  ["4d:5162"] = "Hahaha! Sou o\nperdedor!",
  ["4d:5220"] = "Derrotas…\nElas estao também!",
  ["4d:53d5"] = "nutil usar\ngolpes fortes sem\vpensar antes.",
  ["4d:5674"] = "Acabou. Eu nao\nligo. Nos\vANDARILHOS somos\vassim.",
  ["4d:588a"] = "Voce visitou o\nGINASIO PEWTER?\fO LIDER usa\nPOKéMONS do tipo\vpedra.",
  ["4d:58c8"] = "A noite, CLEFAIRYS\nvem brincar fora\vdo MONTE LUA.\fMas nem sempre.",
  ["4d:590e"] = "Oh, voce percorreu\na distancia de\vJOHTO até aqui?\fIsto melhora a\nmemoria.\fQuando jovem, fui\na JOHTO para\vtreinar.\fVoce se parece\nmuito comigo,\vquando eu era\vapenas um jovem.\fEi. Quero que\nfique com este\vitem.\fAchei em JOHTO.",
  ["4d:59f2"] = "Va a novos lugares\ndesconhecidos e\vconheca pessoas…\fEstes sao\nmotivos para\vviajar.",
  ["4e:405f"] = "Ei, garoto! Acabo\nde tomar duas\vdoses de café e\vestou sem sono.\fPreciso falar com\nalguém, pode ser\vcom voce mesmo.\fPode nao parecer,\nmas ja fui um\vperito em capturar\vos POKéMONS.\fVoce acredita\nem mim?",
  ["4e:40b4"] = "Preciso falar com\nalguém, pode ser\vcom voce mesmo.\fPode nao parecer,\nmas ja fui um\vperito em capturar\vos POKéMONS.\fVoce acredita\nem mim?",
  ["4e:412c"] = "Bom, bom. Sim, eu\nera algo fora do\vcomum, deixe-me\vcontar a voce!",
  ["4e:4174"] = "O que?\nSeu pirralho!\fSe eu fosse um\npouco mais jovem,\veu lhe mostraria\vumas coisas!",
  ["4e:41ce"] = "Este GINASIO, nao\ntinha LIDER até\vrecentemente.\fUm jovem de PALLET\nse tornou LIDER,\vmas ele sempre\vviaja.",
  ["4e:423b"] = "Vai batalhar com\no LIDER?\fBoa sorte, pois\nvoce vai precisar.",
  ["4e:4281"] = "Uah! Devo ter\ncochilado no sol.\f…Tive um sonho\nque um DROWNZEE\vcomia o meu sonho.\fMisterioso, hein?\fHa? O que é isto?\fDe onde veio este\nTM?\fIsto é\nfantasmagorico!\fEi, pode ficar\ncom este TM.",
  ["4e:4343"] = "O TM42 contém o\nCOME SONHOS\f…\fZzz…",
  ["4e:4367"] = "Ouvi dizer que\nha muitos itens no\vchao da FLORESTA\vDE VERIDIANA.",
  ["4e:46c2"] = "Estou criando\nPOKéMONS também.\fEles servem como\nsegurancas.",
  ["4e:46fb"] = "A tecnologia é\nincrivel!\fVoce pode trocar\nPOKéMONS através\vdo tempo como\ve-mail.",
  ["4e:49a7"] = "Quem é voce?\fBem, é obvio que\nvoce é um\vtreinador…\fMeu nome é GARY.\fEu ja fui o\nCAMPEAO, mas foi\vpor pouco tempo…\fAquele intrometido\ndo ASH tomou o\vmeu lugar…   \fBom, o que voce\nquer? Quer me\vdesafiar ou é\voutra coisa?\f…Eu odeio dizer\nisso, mas estou\vsem animo para\vbatalhar agora.\fDe uma olhada ao\nseu redor…\fUm vulcao entrou\nem eurupcao, e\visso fez uma\vcidade inteira\vdesaparecer.\fNos podemos vencer\ne perder com os\vPOKéMONS.\fSe nao ficarmos\natentos, podemos\vperder em um\vsegundo.\f…\fAs coisas\nfuncionam desse\vmodo…\fMas, eu ainda sou\num treinador.\fSe eu vir um\noponente forte,\vfico com vontade\vde batalhar.\fSe quiser batalhar\ncomigo, venha ao\vGINASIO DE\vVERIDIANA.\fLa eu aceitarei\no seu desafio.",
  ["4e:4d3a"] = "{PLAYER}M\nMe sinto bem mais\nleve na agua.",
  ["4e:4fa0"] = "{PLAYER}!{PLAYER}{PLAYER}{RIVAL}Voce ja foi nadar\nno mar de noite?",
  ["4e:4fdf"] = "O mar se torna\npreto a noite.\fParece até que ele\nvai te engolir.",
  ["4e:51da"] = "Perdao. A estrada\nesta fechada para\vobras.\fSe quiser ir a\nCINNABAR, é melhor\vvoce ir pelo sul\vda CI…… PALLET.",
  ["4e:524f"] = "Eu estou todo\nsuado. Hora de\vnadar!",
  ["4e:5270"] = "Quem sabe quanto\ntempo eu levaria\vpara mover esta\vpedra…",
  ["4e:52a8"] = "A obra da estrada\nfinalmente acabou.\fAgora eu posso ir\npescar de novo.",
  ["4e:599c"] = "Andar sem as maos\né considerado\vlegal, nesta\vESTRADA.",
  ["4e:5a0a"] = "Os acidentes\nacontecem por\vfalta de calma!",
  ["4e:5b3a"] = "Este POLIWRATH é\nmeu amigo.\fEu me pergunto se,\nele evoluira num\vsapo POKéMON.",
  ["4e:5b9b"] = "Eu perdi novamente\nnestas maquinas…\fNos meninas,\ntambém jogamos.\fVoce deve checa-\nlas também.",
  ["4e:5c00"] = "Os GRIMERS\ntem aparecido\vultimamente.\fVeja aquela lagoa\nem frente a esta\vcasa.\fOs GRIMERS vivem\nla agora.\fDe onde sera que\nvieram?\fIsto é um problema\nsério…",
  ["4e:5c99"] = "Uau! Este GINASIO\né otimo!\fSo meninas podem\nentrar!",
  ["4e:5d12"] = "Estao realizando\numa competicao la\vno restaurante.\fSo vou assistir,\nou irei sair de la\vbem gordo…",
  ["4e:5e18"] = "Olhar para o chao\nenquanto caminho\vme faz ficar\vtonta.",
  ["4f:5045"] = "Existem muitos\nprédios, nao é?\fEssa é a TORRE DE\nRADIO DE KANTO.",
  ["4f:5080"] = "O continente\nKANTO tem muitos\vprogramas de\vradio de otima\vqualidade.",
  ["4f:50a2"] = "As pessoas vem de\ntodos as lugares\vpara pagar devotos\vas almas de\vPOKéMONS.",
  ["4f:50f2"] = "Para acordar\nPOKéMONS adormeci-\vdos, voce deve ter\va POKé FLAUTA. \fTodo treinador tem\nque saber disso!",
  ["4f:5308"] = "O PORTO DE\nVERMILION é a rota\vlitoranea do\vcotinente KANTO.\fLuxuosos navios de\ntodo o mundo vem\vpara ca.",
  ["4f:5362"] = "Meu POKéMON esta\npreparando o\vterreno para a\vconstrucao.\fMas eu nao tenho\ndinheiro para\viniciar o projeto…",
  ["4f:53d5"] = "O MACHOP rosna\nenquanto achata a\vsuperficie.",
  ["4f:540d"] = "Existem oito\nGINASIOS em KANTO.\fEsta grande\nconstrucao é o\vGINASIO POKéMON\vde VERMILION.",
  ["4f:5457"] = "O SNORLAX esta\ndormindo em paz…",
  ["4f:5477"] = "A POKéGEAR foi\ncolocada em\vfrente ao SNORLAX\vdorminhoco…\f… O SNORLAX\nacordou!",
  ["4f:54bb"] = "Treinadores\nhabilidosos se\vreunem em KANTO.\fOs lideres de\nGINASIO sao muito\vfortes.\fNao sera nada\nfacil derrota-los.",
  ["4f:551e"] = "Voce comecou a\ncolecionar as\vINSIGNIAS dos\vGINASIOS de KANTO?\fEsta achando os\ntreinadores daqui\vbem poderosos?",
  ["4f:557b"] = "Eu acho que\nem breve voce\vconquistara todos\vos GINASIOS de\vKANTO.\fDeixe me saber se\nvoce colecionou\vtodas as oito\vINSIGNIAS.",
  ["4f:55e6"] = "Parabéns!\fVoce colecionou\ntodas as INSIGNIAS\vdos GINASIOS de\vKANTO.\fEu vou\nrecompensa-lo pelo\vseus esforcos.",
  ["4f:563d"] = "Ter uma variedade\nde tipos de\vPOKéMONS deve lhe\vdar vantagens em\vuma batalha.\fTenho certeza que\nas INSIGNIAS dos\vGINASIOS de KANTO\vvao ajuda-lo.",
  ["4f:5820"] = "A estrada ficara\nfechada até o\vproblema na USINA\vDE ENERGIA for\vresolvido.",
  ["4f:5920"] = "Uma pequena menina\nque é otima em\vimitar pessoas\vmora aqui.\fEla até\nimita pessoas\vque estiver\vconversando.\fE bem confuso.",
  ["4f:59a3"] = "A garota imitadora\nparece infeliz.\fEla disse que\nperdeu sua BONECA\vfavorita-CLEFAIRY.",
  ["4f:59f6"] = "Voce veio do\ncontinente JOHTO?\fVoce poderia\nretornar a sua\vcasa se o TREM\vMAGNETO estivesse\vfuncionando.",
  ["4f:5a44"] = "Voce veio do\ncontinente JOHTO?\fVoce pode retornar\na sua casa com o\vTREM MAGNETO agora\vque ele esta\vfuncionando.",
  ["4f:5a94"] = "Eu fui ao GINASIO\nquerendo batalhar\vcontra os\vtreinadores…\fEle se virou e eu\ntropecei no\vGINASIO sem uso\vacima.\fCara, eu estava\ntao atrapalhado.",
  ["4f:5b92"] = "Chew… Chew…\fSoube que ha um\ngrande problema na\vUSINA DE ENERGIA.\fChew… Chew…",
  ["4f:5be1"] = "Chew… Chew…\fSoube que houve um\ngrande problema na\vUSINA DE ENERGIA.\fChew… Chew…\nCansei disso!",
  ["4f:5c3b"] = "Ir a um estadio\npela primeira vez\vme deixa muito\vancioso.",
  ["4f:5cdb"] = "Nossa cidade foi\ndestacada num\vprograma de radio.\fE bom ouvir\nelogios da sua\vcidade, mas é bem\vembaracoso também.",
  ["4f:5f1e"] = "A estrada estara\nfechada até o\vproblema na USINA\vDE ENERGIA for\vresolvido.",
  ["4f:60aa"] = "4YA USINA DE ENERGIA\nde KANTO é em\vdirecao ao fim da\vROTA 9.\fOcorreu um tipo de\nacidente la.",
  ["4f:610c"] = "Voce esta\ncolecionando todos\vos tipos de\vPOKéMONS?\fDeve ser um grande\ndesafio, mas\vparece divertido.",
  ["4f:6170"] = "A PENINSULA\nao norte é um\vbom lugar para\vencontros.\fAs garotas adoram!",
  ["4f:61c2"] = "Meu SLOWBRO e eu\nfazemos uma otima\vcombinacao!",
  ["4f:61f1"] = "SLOWBRO, mostre-me\nsua CONFUSAO!",
  ["4f:6216"] = "Eu sou um grande\nfa do GINASIO\vde CERULEANA da\vMISTY.",
  ["4f:623d"] = "Eu vi esse rapaz\nsuspeito indo\vem direcao a\vPENINSULA DE\vCERULEANA.",
  ["4f:6271"] = "Ali existia uma\ncaverna que dentro\vdela havia um\vPOKéMON com forca\vincrivel.",
  ["4f:62b6"] = "O que?\fMeu ACHA ITENS\nesta respondendo…",
  ["50:4157"] = "Nos preparamos\nvarias refeicoes\ve dividimos.\fElas sao\ndeliciosas!",
  ["50:41d1"] = "Desculpe-me.\nVoce nao estava\vbaguncando. Foi\verro meu.",
  ["50:4353"] = "A USINA DE ENERGIA\né apos um pequeno\vrio.",
  ["50:4574"] = "Arrrgh! Nao,\nnao, nao posso\vacreditar!\fVoce é forte\ndemais!\fEu nao sou pareo\npara ti!",
  ["50:4ae9"] = "Fiz o melhor\nque pude. Nao me\varrependo.",
  ["50:4b32"] = "uro!",
  ["50:4c3c"] = "Fiz o melhor\nque pude. Nao me\varrependo.",
  ["50:4d1c"] = "Voce teve uma\nbatalha a mais do\vque esperava, mas\vvoce ganhou mesmo\vassim.\fComo prometi, voce\nganhou um premio.",
  ["50:4d7e"] = "Apos ver como\nvoce batalha, eu\vquero ver como eu\vme saio.\fO que acha?\nDeixe-me testa-lo.",
  ["50:4dde"] = "Nunca tive uma\nbatalha tao boa!",
  ["50:4e01"] = "Foi uma grande\nbatalha!\fVoce e seus\nPOKéMONS sao\vincrivelmente\vfortes!",
  ["50:5223"] = "Eu devo ir a USINA\nDE ENERGIA.\fE perto do T→NEL\nDE PEDRA?",
  ["50:5790"] = "Minha gripe me faz\nespirrar!\vAhahah-tchim!",
  ["51:400e"] = "Os marinheiros\nsao generosos.\fEle ensinou FOR'sA\nao meu POKéMON.\fEle agora move\numas pedras.",
  ["51:4067"] = "Existe uma pessoa\nna CI……\vCIANWOOD, que fica\vapos o mar.\fEu o ouvi falando\nsobre seu POKéMON\vraro.",
  ["51:429c"] = "…Voce é o melhor\ntreinador, pois\vpossui habilidades\v e compaixao.\fConforma a lei\nda LIGA, eu lhe\vconcedo esta\vINSIGNIA.",
  ["51:431b"] = "{PLAYER} foi\npresenteado com\vuma INSIGNIA\vMINERAL do GINASIO\vda CI…… OLIVINE.",
  ["51:4335"] = "A INSIGNIA MINERAL\ncria a DEFESA do\vPOKéMON.\fPor favor pegue\nisto…",
  ["51:4386"] = "…Voce pode ensinar\nao POKéMON o\vRABO DE FERRO.",
  ["51:43b2"] = "Hum… Nao sei\ncomo dizer, mas\vboa sorte amigo.",
  ["51:43e3"] = "JASMINE usa um\nnovo tipo de\vPOKéMON do tipo\vA'sO.\fEu nao sei muita\ncoisa desse\vPOKéMON.",
  ["51:4432"] = "Isto é incrivel!\nPOKéMONS do tipo\vA'sO hein?\fNao sei por que\neu nao encontro\vestes POKéMONS.",
  ["51:4580"] = "Quando meu POKéMON\nadoece, o\vFARMACEUTICO em\vECRUTEAK faz\vremédios para mim.",
  ["51:4621"] = "No caminho para\nCIANWOOD, existem\vquatro ilhas\vdesertas.\fAs criancas ruins\nsao levadas para\vla como castigo!",
  ["51:4692"] = "Toda vez que me\nencrenco, papai\vsempre me assusta.",
  ["51:472a"] = "OLIVINE esta no\nmar!\fE se esta no mar,\nexistem milhoes\vde peixes aqui!\fEu pesquei aqui\ndurante 30 anos.\fVoce gostaria de\nenfrentar uns\vpeixes?",
  ["51:47bc"] = "Ah, hahah!\nNos arrumamos um\vnovo pescador!",
  ["51:47e8"] = "Peixes nao sao\nencontrados so\vno mar.\fEles estao onde\nexiste agua.",
  ["51:482d"] = "O quee? Voce nao\ncurte pescar!?\vIncompreensivel!",
  ["51:4860"] = "Como vao as\ncoisas, meu amigo?",
  ["51:4980"] = "No mar, a unica\ncoisa com que\vvoce pode contar,\vé com voce mesmo!\fEstou orgulhoso\ndo meu POKéMON!",
  ["51:49e0"] = "Cruzar o mar?\nEntao escute isto!\fHa redemoinhos na\nagua a caminho de\vCIANWOOD.     \fSeu POKéMON deve\nconhecer um golpe \vque acabe com os\vredemoinhos.",
  ["51:4aaa"] = "Seu POKéMON\nconhece um golpe\vaquatico que\vtransporta pessoas\vna agua?",
  ["51:4aec"] = "Meu namorado me\nmandou o\vBUTTERFREE do\vexterior.\fEle trouxe uma\ncarta dele!\fQuer saber o que\nhavia nela?\fVamos ver… Nao!\nE secreto!",
  ["51:4bb0"] = "De onde voce disse\nque veio?\fCI…… NEW\nBARK?\fO PROFESSOR ELM\nmora la, nao é?\fVoce andou\nbastante até\vchegar aqui.",
  ["51:4d04"] = "A MOOMOO esta\ndoente.\fEla precisa de\nmuitos GRAOS.",
  ["51:4d30"] = "Nos estamos\nalimentando a\vMOOMOO!",
  ["51:4d56"] = "Seu mugido esta\nfraco…",
  ["51:4d77"] = "Dar um GRAO a\nMILTANK?",
  ["51:4d91"] = "{PLAYER} deu um\nGRAO a MILTANK.",
  ["51:4dad"] = "A MILTANK ficou um\npouco saudavel.",
  ["51:4dd1"] = "A MILTANK ficou\nmais saudavel!",
  ["51:4df0"] = "A MILTANK esta\ntotalmente curada!",
  ["51:4e11"] = "{PLAYER} nao possui\nGRAOS…",
  ["51:4e24"] = "{PLAYER} nao deu\nGRAO a MILTANK.\fA MILTANK parece\ntriste.",
  ["51:4f0a"] = "Minha MILKTANK\nnao esta dando\vmais leite.\fEssa FAZENDA tem\num leite famoso.\fQuase todos querem\nbeber.\fEla te da muito\nleite se alimenta-\vla com muitos\vGRAOS.",
  ["51:4fb7"] = "O que voce acha do\nLEITE MOOMOO?\fEle me orgulha e\nme alegra.     \fDe ele a um\nPOKéMON para\vrestaurar seu PS.\fTe vendo ele por\n¥500.",
  ["51:5031"] = "Aqui esta! Beba-o\ne aproveite!",
  ["51:5050"] = "Desculpe-me,\nfilho!\fSem dinheiro, sem\nvenda!",
  ["51:506f"] = "Eu percebi que sua\nBOLSA esta cheia,\vfilho.",
  ["51:508e"] = "Voce nao o quer?\nVolte outra hora,\vcerto?",
  ["51:50b3"] = "E melhor eu ir\ntirar leite.",
  ["51:50cd"] = "Até para KANTO\nnosso leite vai.\fSe a nossa MILTANK\nnao produzir mais\vleite, nos vamos\vter problemas.",
  ["51:512d"] = "Voce curou nosso\nMILTANK, rapaz. Agora ela da LEITE\nMOOMOO de novo.\vEu tenho algo bom\vpara voce.",
  ["51:519e"] = "Isso é o RONCAR.  \fE um golpe raro\nque so funciona\venquanto o POKéMON\vestiver dormindo.\fVoce decide como\nvai usar isso,\vrapaz.",
  ["51:52de"] = "Meu programa de\nradio favorito?\vE a M→SICA\vPOKéMON.",
  ["51:530d"] = "Eu me divirto\nescutando ao\vradio…\nE bem engracado.",
  ["51:545d"] = "Os POKéMONS\ntem muitas\vexperiencias em\vsuas vidas, como\vnos. \fEu, também, vi e\npassei por muitas\vcoisas na minha\vvida.\fTenho mais\nexperiencia e\vmostrarei o que eu\vquero dizer.\fEstive com\nPOKéMONS desde\vantes de voce\vnascer.\fNao perco\nfacilmente.\fEu, PRYCE--o\ntreinador do\vinverno--mostrarei\vmeu poder!",
  ["51:5583"] = "Ah, estou\nimpressionado com\vvoce.\fCom sua forca,\nsei que voce\vpassara por todos\vos obstaculos da\vvida.\fVoce merece essa\nINSIGNIA!",
  ["51:560b"] = "{PLAYER} foi\npresenteado com\vuma INSIGNIA\vGLACIAL do GINASIO\vda CI……\vMAHOGANY.",
  ["51:5625"] = "Essa INSIGNIA\nmelhorara o estado\vESPECIAL dos\vPOKéMONS.\fTambém permite\nseus POKéMONS\vusarem o\vREDEMOINHO para\vatravessar grandes\vredemoinhos.\fE isso… E um\npresente meu para\vvoce!",
  ["51:5729"] = "Quando o gelo e a\nneve derretem, a\vprimavera chega.\fVoce e seu POKéMON\nestarao sempre\vjuntos por muitos\vanos.\fAproveite esse\ntempo de uniao!",
  ["51:58ad"] = "Esse GINASIO é\notimo.\fAdoro deslizar\ncom meus POKéMONS!",
  ["51:5a5f"] = "Eu nao devia me\ngabar quanto ao\vesqui…",
  ["51:5a8f"] = "PRYCE é um\nveterano que\vtreina POKéMONS\vpor mais de 50\vanos.\fEle diz ser bom em\ncongelar os\voponentes como\vgolpes do tipo\vgelo.\fQuer dizer que\nvoce deve\vderrete-lo com sua\vquente ambicao!",
  ["51:5b45"] = "PRYCE é algo, mas\nvoce é algo mais!\fEssa foi a quente\nbatalha que trouxe\va tona o espaco\vdas geracoes!",
  ["51:5c83"] = "Eu impeco meus\nPOKéMONS de\vevoluirem cedo.\fAssim aprendem\ngolpes mais cedo\vdo que aprenderiam\vevoluidos.",
  ["51:5ce8"] = "Os POKéMONS ficam\nmais fortes quando\vevoluem, mas\vaprendem golpes\vmais lentamente.",
  ["51:5d88"] = "A MONTANHA\nMORTEIRO é um\vlabirinto.\fCuidado para nao\nse perder.",
  ["52:413f"] = "A TORRE ESTRANHA\na frente foi feita\vcomo um lar para\vo POKéMON voador.",
  ["52:417d"] = "A TORRE ESTRANHA\ntremeu!\fUm POKéMON deve\nter retornado ao\vtopo!",
  ["52:41b9"] = "Duas torres…\nDois POKéMONS…\fMas quando uma\nqueimou, ambos\vPOKéMONS voaram e\vnunca retornaram.",
  ["52:4304"] = "Oi, sou BILL. E\nquem é voce?\fHmm, {PLAYER}, ha?\nVoce veio na hora\vcerta.",
  ["52:4581"] = "O jeito que as\nGAROTAS KIMONO\vdancam é\vexplendido!\fDo jeito que\nelas usam seus\vPOKéMONS!",
  ["52:46d0"] = "Isso ocorreu\nquando eu era\vjovem.\fO céu de repente\nficou preto.\fUm POKéMON voador\ngigante bloqueou\vo Sol.\fQueria saber qual\nPOKéMON era?\fEra tipo um\npassaro com um\vdragao.",
  ["52:4782"] = "Sera que um\nPOKéMON daquele\vtamanho é real?\fSe for, ele\ndeve ser muito\vpoderoso.",
  ["52:4b94"] = "As GAROTAS KIMONO\ndancam muito bem\ve sao excelentes\vtreinadoras\vPOKéMON.\fEu sempre desafio\nelas, mas eu nunca\vconsigo ganhar…",
  ["52:4c1b"] = "Rapaz! Se puder\nderrotar todas as\vGAROTAS KIMONO, eu\vlhe darei um\vpresente.",
  ["52:4c5e"] = "A maneira que\nvoce batalhou,\vfoi como assistir\va uma danca.\fFoi uma festa rara\nde se ver.\fQuero que pegue\nisso. Nao se\vpreocupe--Leve\visso.",
  ["52:4cdf"] = "Isso é o SURFE.\fE um golpe que\npermite o POKéMON\vnadar através da\vagua.",
  ["52:4d19"] = "Queria que meus\nPOKéMONS fossem\velegantes como as\vGAROTAS KIMONO…",
  ["52:4dee"] = "As GAROTAS KIMONO\nsao tao bonitas…\fMas elas tem que\npassar por\vum rigoroso\vtreinamento.\fE elas devem\naprender a seguir\vos costumes antes\vde aparecer em\vpublico. \fMas se ama algo,\nqualquer coisa é\vpossivel.",
  ["52:4ebd"] = "E um extravagente\npainel decorado\vcom flores.",
  ["52:4f8c"] = "Meu EEVEE evoluiu\nem um ESPEON.\fMas o EEVEE do meu\namigo virou um\vUMBREON.\fPor que sera? Nos\ndois treinavamos\vo EEVEE do mesmo\vjeito…",
  ["52:5019"] = "Se voce usar o\nREVIVE, um POKéMON\vque desmaiou\vvai acordar\vrapidamente.",
  ["52:516b"] = "Que bom voce ter\nvindo.\fAqui em ECRUTEAK,\nos POKéMONS foram\vhonrados.\fDizem que\nPOKéMONS lendarios\vvao aparecer para\vo treinador\vverdadeiramente\vforte.\fEu acredito\nnesse conto,\ventao treinei\vsecretamente\vaqui toda minha\vvida.\fComo resultado\nposso ver o que\voutros nao veem.\fSo um pouco mais.\fCom um pouco mais,\neu poderia prever\vo futuro no qual\veu conheceria o\vPOKéMON lendario.\fVoce me ajudara a\nalcancar esse\vnivel!",
  ["52:52f4"] = "Nao sou boa o\nbastante ainda…\fCerto, essa\nINSIGNIA DA NEVOA\vé sua.",
  ["52:5343"] = "Por ter a INSIGNIA\nDA NEVOA, os\vPOKéMONS acima do\vNIVEL 50 vao te\vobedecer.\fE também os\nPOKéMONS que sabem\vo SURFE poderao\vusa-lo a qualquer\vhora.\fLeve isso também.",
  ["52:53d6"] = "E a BOLA SOMBRIA.\fEla causa danos\ne reduz a DEFESA\vESPECIAL.\fUse-a se lhe\nagradar.",
  ["52:542f"] = "Eu vejo…\fSua jornada te\nlevou para lugares\vdistantes.\fE voce\ntestemunhou muito\vmais que eu.\fEu te invejo por\nisso…",
  ["52:55a1"] = "Nos so\nusamos POKéMONS\vfantasmas.\fNenhum POKéMON\nnormal pode\vprejudica-los!",
  ["52:5602"] = "Aquele que\nmais quiser\vvencer--vencera!",
  ["52:56d2"] = "Os treinadores\naqui tem motivos\vsecretos.\fSe vencer, eles\ndevem contar\vlhe profundos\vsegredos de\vECRUTEAK.",
  ["52:573c"] = "Uau, {PLAYER}.\nVoce foi demais.\fEu me agachei no\ncanto livre do\vpuro terror!",
  ["52:58c9"] = "Ah. Voce esta numa\njornada com o seu\vPOKéMON?\fBem, o que é uma\njornada sem uma\vCaca ao Tesouro?\fEstou certo ou\nestou certo?",
  ["52:5945"] = "Bom! Voce entendeu\no verdadeiro\vespirito de uma\vjornada.\fGosto disso! Leve\nisso com voce.",
  ["52:5a95"] = "…Cada um deve ter\nseu gosto…",
  ["52:5ab6"] = "HISTORIA DE\nECRUTEAK.\fQuer ler?",
  ["52:5adc"] = "Em ECRUTEAK, havia\nduas torres.\fCada uma era o\nalojamento de\vpoderosos POKéMONS\vvoadores.\fMas uma das torres\nqueimou até o\vchao.\fOs dois POKéMONS\nnunca mais foram\vvistos desde\ventao…\fFicar lendo?",
  ["52:5b92"] = "ECRUTEAK era\ntambém a casa dos\vtres POKéMONS que\vcorriam pela\vcidade.\fDizia-se que eles\nforam nascidos da\vagua, do relampago\ve do fogo.\fMas eles nao\npuderam conter\vseus poderes\vexcessivos.\fDizem que eles\ncorrem como o\vvento por dentro\vda grama.",
  ["53:41cf"] = "Eu fui derrotada?\nEu nao acredito.\vDeve haver algo de\verrado…",
  ["53:4391"] = "CLAIR: Qual o\nproblema?\fEssa missao nao\nsera dificil para\vti, a nao ser que\vsua vitoria foi\vfalsa.",
  ["53:4451"] = "CLAIR: Voce\nprovou a mim que\vé competente.\fEu quero que leve\nisse TM.",
  ["53:44a7"] = "Isso contém o\nSOPRO DRAGAO.\fIsso nao tem nada a\nver como o meu\vsopro.    \fSe nao\vquiser, vocE nao\vé obrigado a\vlevar.",
  ["53:4525"] = "Entao voce\ncolecionou todas\vas INSIGNIAS.\fSua destinacao é\na LIGA POKéMON no\vPLANALTO INDIGO.\fVoce sabe como\nchegar la?\fDaqui, va a\nCI…… NEW BARK.\fDepois SURFE ao\nleste. Aquela rota\vé bem dificil.\fNao se atreva a\nperder na LIGA\vPOKéMON!\fCaso o faca, me\nsentirei pior\vainda do que ter\vperdido para\vvoce!",
  ["53:47fa"] = "Oi! Seja bem\nvindo!\fE uma grande\njornada, mas\vestamos quase\vacabando.\fConte comigo.\fCLAIR usa POKéMONS\ndragoes do tipo\vmistico e sagrado.\fVoce nao\npode feri-los\vfacilmente.\fComo sabe, eles\nsao supostamente\vfracos contra\vgolpes do tipo\vgelo.",
  ["53:48e8"] = "Voce foi otimo ao\nderrotar CLAIR!\fO que falta agora\né o desafio da\vLIGA POKéMON.\fVoce esta no\ncaminho de se\vtornar o CAMPEAO\vPOKéMON!",
  ["53:4c64"] = "CLAIR e LANCE\ntreinaram aqui\vpara melhorar\vsuas técnicas\vcomo treinadores\vPOKéMON.",
  ["53:4d20"] = "Voce nao pode\ncomprar o REVIVE\vTOTAL.\fEle restaura o\nPOKéMON desmaiado\vpor completo.\fAtencao--Ele nao\nrestaura o PP,\vnecessario para\vos golpes.",
  ["53:4d9f"] = "O REPELENTE 03\nafasta POKéMONS\vfracos de voce.\fE o REPELENTE mais\nduradouro.",
  ["53:4e3b"] = "Dentro do PLANALTO\nINDIGO esta a\vLIGA POKéMON.\fSoube que\nos melhores\vtreinadores vao la\vde todos os cantos\vdo pais.",
  ["53:4ff1"] = "Ja tem um ano que\no vulcao entrou em\veurupcao.",
  ["53:507c"] = "O vulcao de\nCINNABAR entrou\vem eurupcao.\fEle lancou pedras\nque bloquearam a\vROTA 19 por tempo\vindeterminado.\fSera que as pes-\nsoas de CINNABAR\vestao seguras…",
  ["53:50fc"] = "Nenhum habitante\nde CINNABAR foi\vferido pela eurup-\vcao vulcanica.\fIsto é otimo!",
  ["53:51ba"] = "BLAINE: Waaah!\fMeu GINASIO em\nCINNABAR foi\vqueimado.\fMeus POKéMONS tipo\nfogo e eu estamos\vsem casa devido ao\vvulcao.\fWaaah!\fMas eu estou de\nvolta ao negocios\vcomo LIDER DE\vGINASIO aqui nessa\vcaverna.\fSe voce me\nderrotar, eu te\vdarei uma\vINSIGNIA.\fE melhor voce ter\num CURA FOGO!",
  ["53:530f"] = "BLAINE: Eu perdi\ndesta vez, mas\vna proxima eu\vvencerei.\fQuando eu\nreconstruir meu\vGINASIO em\vCINNABAR nos\vteremos uma\vrevanche.",
  ["53:538e"] = "BLAINE: Meus\nPOKéMONS de fogo\vserao ainda mais\vfortes. Aguarde e\vvera!",
  ["53:53cb"] = "Voce!\f…Ha? Ja acabou?\fDesculpe-me,\namigo!\fO GINASIO CINNABAR\nfoi destruido e eu\vnao sabia onde te\vachar.\fMas, voce é bem\nforte até sem os\vmeus avisos. Sabia\vque ganharia!",
  ["53:5477"] = "Um GINASIO POKéMON\npode ser em todo\vlugar que tenha um\vLIDER DE GINASIO.\fNao precisa ser um\nprédio.",
  ["53:551e"] = "…Voce veio de\nlonge…\fAqui eu meditei.\nDentro de mim, um\vnovo poder foi\vdespertado.\fDeixe-me dividir\nmeu poder com o\vseu POKéMON. Leve\visso, garoto.",
  ["53:55b4"] = "Pode sentir?\nE o PODER OCULTO!\fEle libera o poder\ndo POKéMON para\vatacar.\fLembre-se disso:\nseu tipo e poder\vdepende do POKéMON\vque estiver\vusando.",
  ["53:5649"] = "Eu estou\nmeditando…",
  ["53:5823"] = "O LAGO esta\nestranho desde\vquando os homens\vde preto chegaram.",
  ["53:5866"] = "O LAGO DA RAIVA\nvoltou ao normal.\fAs MAGIKARPS\nvoltaram.\fAinda posso\nrealizar meu sonho\vde ver a maior\vMAGIKARP do\vmundo.  \fVoce tem uma VARA?\fPor favor,\najude-me se puder.",
  ["53:5914"] = "Ah, voce tem uma\nMAGIKARP.\fVamos ver o\ntamanho dela.",
  ["53:594d"] = "Uau! Essa é\nincrivel!\fEu tiro meu chapéu\npara voce!\fEssa é uma\nlembranca!",
  ["53:5999"] = "O recorde que é o\nimportante.\fConsidere como um\nbonus!",
  ["53:59d7"] = "Uau! Essa é\nincrivel!\f…Nao queria dizer\nisso, mas eu ja\vvi outras que sao\vbem maiores.",
  ["53:5a32"] = "Como? Isso nao é\numa MAGIKARP!",
  ["53:5a4f"] = "Oh… Entao nao tem\numa muito boa para\vme mostrar?\fTalvez na proxima.",
  ["53:5af5"] = "So pessoas\nencaminhadas ao\vLAGO DA RAIVA\vpassaram aqui bem\vtarde.",
  ["53:5b3b"] = "Atualmente ninguém\nvai ao LAGO DA\vRAIVA.",
  ["53:5ca8"] = "Parado ai,\nsenhor!\fO pedagio é ¥1000\npara atravessar.",
  ["53:5ce1"] = "Obrigado, senhor!",
  ["53:5cf2"] = "Entao pague o que\ntiver.",
  ["53:5d13"] = "He-he-he. Estamos\nficando ricos.\fTodo mundo quer\nver o que esta\vacontecendo no\vLAGO DA RAIVA.",
  ["53:5d6d"] = "Eu fui expulso do\nmeu posto por\vesses caras de\vpreto.\fEles esqueceram\nisso.\fIsso me deixa\ninconfortavel.\vPoderia levar\visso?",
  ["53:5dff"] = "Use este portao\npara nao andar na\vgrama.",
  ["54:405a"] = "Eu soube que uma\npessoa sombria\vesta escondida.\fNao ficarei\nparado caso ele\vseja um ladrao.",
  ["54:40c3"] = "Nos ja fomos\nassaltados por\vladraos no passa-\vdo.",
  ["54:414d"] = "Meu marido vive\nfeliz com os\vPOKéMONS que\vconseguiu em\vtrocas.",
  ["54:418a"] = "Ah… Estou muito\nfeliz…",
  ["54:4218"] = "A ROTA 9 vai para\no leste. A USINA\vDE ENERGIA esta\vno final.",
  ["54:4257"] = "O TREM MAGNETO\nanda a cerca de\v544 km/h.\fEle percorre entre\nKANTO e JOHTO em\vpouquissimo tempo.\fEle realmente\ntorna JOHTO\vacessivel.",
  ["54:4453"] = "Opa! Me desculpe!\nVoce nao se\vmachucou, né?\fEstou muito\nocupado, nao tenho\vtempo para\vconversar com\vvoce.\fSeria ruim se\nalguém me visse\vaqui!",
  ["54:44cc"] = "Oh nao! Voce ja me\nviu. Eu cometi um\vgrande erro!",
  ["54:44fd"] = "Ei, voce! Esqueca\nque me viu, certo?\fVoce nao me viu,\nnao me ouviu e nem\vsabe de nada,\vcerto?    \fTchau, garoto!\nAté breve!",
  ["54:4664"] = "MISTY: Voce é\nrealmente bom…\fEu admito que voce\né habilidoso…\fAqui esta. E a\nINSIGNIA DA\vCASCATA.",
  ["54:46da"] = "MISTY: Existem\nmuitos treinadores\vfortes em JOHTO?\vAssim como voce?\fUm dia eu\nviajarei, entao eu\vpoderei batalhar\vcom muitos\vtreinadores\vhabilidosos.",
  ["54:48ff"] = "Voce! CAMPEAO em\nprogresso!\fComo MISTY tinha\nsaido, eu sai\vpara me divertir\vtambém. He-he-he.",
  ["54:4952"] = "Uau, voce me\nmostrou como é\vpoderoso.\fComo sempre, foi\numa demonstracao\vde uma grande\vbatalha!",
  ["54:4a25"] = "Voce enfrentara\nmuitos treinadores\va caminho da\vPENINSULA DE\vCERULEANA.\fEles querem\ntestar as proprias\vhabilidades com\voutros treinado-\vres.",
  ["54:4a9e"] = "A MISTY é talvez\na unica pessoa na\vcidade capaz de\vderrotar os\vtreinadores da\vPENINSULA DE\vCERULEANA.",
  ["54:4b49"] = "Um CENTRO POKéMON\nperto da carverna?\fDeve ser bem util.",
  ["54:4b7e"] = "O GERENTE DA\nUSINA DE ENERGIA\vesta procurando\vpor um poderoso\vtreinador POKéMON.\fEle precisa de\nalguém que o\vajude a recuperar\valgo que foi\vroubado.",
  ["54:4c64"] = "Quando voce vai\npara fora, é\vpossivel enxergar\vo telhado de uma\vgrande construcao.\fE a USINA DE\nENERGIA DE KANTO.",
  ["54:4e31"] = "Um ladrao assaltou\na USINA DE\vENERGIA…\fOnde parara este\nmundo?",
  ["54:4e73"] = "Eu telefonei de\nCERULEANA.\fParece que um\nsujeito estranho\vesta aprontando\vpor la.",
  ["54:4ed0"] = "Eu poderia pedir\nsua cooperacao?",
  ["54:4ef3"] = "Nos teremos que\najustar o nosso\vsistema de\vseguranca.",
  ["54:4f20"] = "Alguém roubou uma\nparte essencial\vpara o gerador.\fSem essa parte,\no gerador fica\vtotalmente inutil!",
  ["54:4f89"] = "O gerador esta\nconsertado e\vfuncionado.\fAgora, esta\ndistribuindo a\veletricidade!",
  ["54:4fca"] = "Essa USINA DE\nENERGIA foi\vabandonada no\vpassado.\fNos a recuperamos\npara ela fornecer\venergia para que\vo TREM MAGNETO\vfuncionasse!",
  ["54:5040"] = "O gerador esta\nfuncionando de\vnovo agora!",
  ["54:505f"] = "O GERENTE DA\nUSINA DE ENERGIA\vesta la na frente.\fMas desde quando\nalguém quebrou o\vgerador, ele esta\vfurioso…",
  ["54:50d0"] = "Desde quando o\ngerador foi\vconsertado, o\vGERENTE esta bem\vfeliz.",
  ["54:5113"] = "O TREM MAGNETO\ngasta bastante\veletricidade.\fEle nao pode se\nmexer se o novo\vgerador nao\vfuncionar.",
  ["54:5176"] = "Que bom!\nFinalmente o\vTREM MAGNETO esta\vfuncionando de\vnovo.",
  ["54:51b5"] = "GERENTE: Eu, eu\nestou pronto para\vdestruir alguém!\fQuem ousaria\nquebrar meu\vgerador?\fEu gastei muito\ntempo nele!\fSe eu pega-lo,\nele vai testar\vmeu SUPER CANHAO!",
  ["54:5259"] = "GERENTE: Eu nao o\nperdoarei!\fO culpado pode\nchorar e se\vdesculpar, mas eu\vvou martela-lo!\fHahahaha!",
  ["54:52bf"] = "GERENTE: Ah! Bom!\fA PARTE perdida\ndo meu amado\vgerador!\fFoi voce quem\nachou?",
  ["54:5315"] = "Haha! Obrigado!\fEi! Leve esse TM\ncomo recompensa!",
  ["54:5345"] = "GERENTE: O TM07\né o meu SUPER\vCANHAO.\fE uma poderosa\ntécnica!\fNao é o que\ntodos consideram\vcorreto, mas ele\vpossui uma batida\vforte!",
  ["54:53c6"] = "GERENTE: Meu amado\ngerador!\fFica enviando\neletricidade para\vfora!",
  ["54:5612"] = "Ha? Voce conhece\nBILL? Ele é meu\vneto e esta em\vJOHTO.\fEle trabalha com\ncomputadores\venquanto eu cuido\vda casa dele.",
  ["54:5676"] = "Se voce tiver esse\nPOKéMON, eu\vpoderia ve-lo?",
  ["54:56a4"] = "Vai me mostrar?\nComo é bondoso!",
  ["54:56c8"] = "Voce nao tem? Que\npena…",
  ["54:56ea"] = "Ah, entao esse é\n{STRBUF}?\fNao é lindo?\nE muita gentileza\vda sua parte.",
  ["54:5725"] = "Obrigado!\fIsso é um presente\npara voce.",
  ["54:5752"] = "Venha me visitar\noutra hora.",
  ["54:576e"] = "Obrigado por me\nmostrar tantos\vPOKéMONS bonitos.\fEu realmente\nadorei.\fEstou feliz por\nter vivido tanto.",
  ["54:57d5"] = "Ha? Esse nao é o\nPOKéMON que eu\vmencionei.",
  ["54:5804"] = "Me neto BILL me\ncontou sobre um\vPOKéMON que tem\vuma grande lingua.",
  ["54:5843"] = "Ah, meu neto me\nfalou de um\vPOKéMON verde e\vveloz que tem\vfolhas crescendo\vna sua cabeca.",
  ["54:5897"] = "Voce conhece um\nPOKéMON do mar que\vtem uma esfera\vvermelha no seu\vcorpo?\fUm que é pontudo\ncomo uma estrela?\fOuvi dizer que ele\naparece a noite.\fEu realmente\nqueria ve-lo.",
  ["54:599b"] = "Ouvi falar sobre\num lindo POKéMON\vque tem seis\vcaudas.\fEu adoraria abracar\num lindo POKéMON\vcomo esse.",
  ["54:59f5"] = "Voce conhece\naquele POKéMON\vpopular e fofinho\vque tem um\vcorpo amarelo\ve bochechas\vvermelhas.\fEu adoraria saber\ncomo ele é antes\vde evoluir.",
  ["55:4013"] = "Seus POKéMONS\nsabem golpes\vde HM?\fEsses golpes podem\nser usados até\vse seu POKéMON\vdesmaiar.",
  ["55:4092"] = "Voce sabe algo\nsobre os FRUTOS?\fAbra uma fenda,\ndeixe o FRUTO oco\ve depois encaixe-o\vnum dispositivo\vespecial.\fAgora pode\ncapturar POKéMONS\vcom ele.\fOs FRUTOS eram\nusados como\vPOKé BOLAS.",
  ["55:41ea"] = "Todos SLOWPOKES\ndesapareceram da\vcidade.\fO protetor da\nfloresta deve\vestar nervoso com\vnos…\fIsso deve ser um\nsinal ruim.\fDevemos ficar em\nalerta.",
  ["55:4276"] = "Os SLOWPOKES\nvoltaram.\fMas meu aprendiz\nnao voltou da\vFLORESTA ILEX.\fOnde sera que\nesse preguicoso\vesta?",
  ["55:4359"] = "Para onde foram\ntodos SLOWPOKES?\vSera que estao\vbrincando por ai?",
  ["55:439e"] = "Perdao--esqueci\nde agradece-lo.\fEsse é o CARVAO\nque eu fiz.\fPOKéMONS do tipo\nfogo ficariam\vfelizes ao segurar\visso.",
  ["55:440c"] = "Os SLOWPOKES\nvoltaram, e voce\vainda achou um\vFARFETCH'D.\fVoce é o mais\nlegal!",
  ["55:44c6"] = "Nao ha SUPER BOLA\naqui. Tera que\vusar POKé BOLAS.\fQueria que KURT\nfizesse algumas\vdessas BOLAS para\vmim.",
  ["55:452f"] = "A SUPER BOLA é\nmelhor para pegar\vPOKéMONS que as\vcomuns POKé BOLAS.\fMas as de KURT\ndevem supera-las.",
  ["55:4990"] = "KURT: Oi, {PLAYER}!\fVoce se cuidou\ncomo um verdadeiro\vheroi no PO'sO.\fGosto do seu\nestilo!\fFicaria honrado ao\nfazer BOLAS para\vum treinador como\vvoce.\fE tudo que tenho\nagora, mas leve-a.",
  ["55:4a44"] = "KURT: Eu faco\nBOLAS com FRUTOS.\fPegue-os nas\narvores e traga-os\vpara mim.\fEu farei BOLAS\npara voce.",
  ["55:4ab1"] = "KURT: Voce tem\nFRUTOS para mim?\fOtimo! Vou\ntransforma-los em\vBOLAS.",
  ["55:4af4"] = "KURT: Levarei um\ndia para lhe fazer\va BOLA.\fVenha buscar\ndepois.",
  ["55:4b37"] = "KURT: Oh…\nQue humilhacao.",
  ["55:4b53"] = "KURT: Estou\ntrabalhando. Nao\vme atrapalhe!",
  ["55:4b76"] = "KURT: Ah, {PLAYER}!\nEu terminei a sua\vBOLA. Aqui esta!",
  ["55:4ba5"] = "KURT: Ela ficou\nexcelente.\fTente capturar\nPOKéMONS com ela.",
  ["55:4bde"] = "Os SLOWPOKES\nsumiram… Sera\vque pessoas ruins\vos levaram?",
  ["55:4c1a"] = "Vovo ja foi…\nQue solidao…",
  ["55:4c38"] = "O SLOWPOKE que meu\npai me deu voltou!\fSua CALDA esta\ncrescendo também!",
  ["55:4c7e"] = "Papai trabalha\nna SILPH onde\vestuda as POKé\vBOLAS.\fTenho que ficar\nem casa com o\vvovo e o SLOWPOKE.",
  ["55:4e83"] = "Sou BUGSY!\fNunca perco quando\nuso POKéMONS\vinsetos.\fMinha pesquisa me\ntornara uma\vautoridade em\vPOKéMONS insetos!\fDeixe-me\ndemonstrar o que\veu aprendi com os\vmeus estudos.",
  ["55:4f26"] = "Uau, demais! Voce\né otimo com os\vPOKéMONS!\fTenho muito\na pesquisar ainda.\fVoce venceu. Leve\na INSIGNIA DA\vCOLMEIA.",
  ["55:4fa3"] = "Voce conhece os\nbeneficios da\vINSIGNIA DA\vCOLMEIA?\fSe a tiver, os\nPOKéMONS acima do\vNIVEL 30 vao te\vobedecer.\fPOKéMONS que\naprenderam o\vCORTA, vao poder\vusar este golpe\vfora das batalhas\vtambém.\fEi, quero que leve\nisso também.",
  ["55:5060"] = "TM49 contém\nCORTE F→RIA.  \fSe voce nao errar,\nesse ataque fica\vcada vez mais\vforte.\fQuanto maior for\na batalha, melhor \vo ataque ficara.  \fIsso nao é otimo?\nFui eu quem\vdescobriu isso!",
  ["55:50fe"] = "POKéMONS insetos\nsao complexos.\fTem muitos\nmistérios a\vexplorar.\fEstude seu\nfavorito por\vcompleto.",
  ["55:519d"] = "Apenas evoluir\nnao basta!",
  ["55:53fc"] = "Ei, desafiante!\fBUGSY é jovem, mas\nseu conhecimento\vde POKéMONS\vinsetos é\vincrivel!\fSeria mais dificil\nsem meu aviso.\fVamos ver…\nPOKéMONS insetos\vnao gostam de\vfogo.\fGolpes de\nPOKéMONS AVES sao\vsuper efetivos.",
  ["55:54bf"] = "Parabéns! Isso\nfoi um otimo\vchoque de jovens\vtreinadores\vtalentosos.\fO futuro POKéMON\nsera brilhante com\vgente como voces!",
  ["56:400f"] = "Quando voce\ncaptura um\vPOKéMON, ele deve\vser fraco.\fMas com o tempo,\nele vai ficando\vforte.\fE importante\ntratar o POKéMON\vcom amor.",
  ["56:41e0"] = "Sou FALKNER, o\nLIDER desse\vGINASIO!   \fDizem que pode\njuntar as asas do\fPOKéMON voador com\no Choque do\vPOKéMON elétrico…\fNao permito\ninsultos aos\vPOKéMONS passaros!\fVou lhe mostrar o\npoder real dos\votimos POKéMONS\vpassaros!",
  ["56:42b7"] = "…Nao! Meu pai\ncuidava de\vPOKéMONS passaros.\fTudo bem. Leve\nisso.\fE uma oficial\nINSIGNIA DA BRISA\vda LIGA POKéMON.",
  ["56:431c"] = "{PLAYER} foi\npresenteado com\vuma INSIGNIA DA\vBRISA do GINASIO\vDA CIDADE VIOLETA.",
  ["56:4335"] = "A INSIGNIA DA\nBRISA melhora os\vpoderes dos\vPOKéMONS.\fTambém permite o\nPOKéMON usar\vLUZES, se tiver, a\vqualquer hora.\fLeve isso também.",
  ["56:43b5"] = "Usando um TM, o\nPOKéMON aprendera\vum golpe num\vinstante.\fPense antes de\nagir--so pode\vusar o TM uma\vvez.\fO TM31 tem o\nTAPA DE LAMA.\fEle reduz a\nprecisao do\finimigo enquanto\ncausa danos. \fEm outras\npalavras, é\vdefensivo quanto\vofensivo.",
  ["56:44a2"] = "Tem outros\nGINASIOS nas\vcidades adiante. \fVoce deve testar\nsuas técnicas\vnesses GINASIOS.\fVou treinar duro\npara me tornar\vo melhor mestre\vde passaros!",
  ["56:4666"] = "Ei! Nao sou\ntreinador mas\vposso ajuda-lo!\fAcredite em mim!\nSe acreditar, um\vsonhado\vcampeonato\vsera real.   \fVoce acredita?\nEntao escute.\fPOKéMONS do tipo\ngrama sao fracos\vcontra o tipo\vvoador.\fPense nisso.",
  ["56:4735"] = "Boa batalha!\nContinue assim e\vvoce vai ser um\vCAMPEAO em pouco\vtempo!",
  ["56:48a8"] = "Su sou EARL!\fOs POKéMONS sao\nmuito legais!\fVou ensina-lo\na ser um melhor\vtreinador!\fO que deseja\nsaber? Quer ser um\vvencedor, nao é?",
  ["56:492a"] = "Bom! Eu vou\nensina-lo!\fNa batalha, o\nPOKéMON\vtopo de lista\vsera o primeiro!\fMudando a ordem,\nvoce pode\vfacilitar a\vbatalha!\fQuer ouvir\nmais dicas?",
  ["56:49be"] = "Entao quer saber\ncomo treinar\vPOKéMONS bem?",
  ["56:49e8"] = "Bom! Eu vou\nensina-lo!  \fUm POKéMON mesmo\nfraco pode ganhar\fmuita experiencia\nnas batalhas.\fColoque o POKéMON\nfraco no topo da\vlista.\fTroque-o\nrapido! \fAssim, POKéMONS\nfracos ficam\vfortes!",
  ["56:4a9e"] = "Oh! Que bom aluno\nvoce é!\fJa te ensinei\ntudo que sei.\fVoce é otimo\ncom POKéMONS!",
  ["56:4aed"] = "Estou aprendendo\ndicas sobre os\vPOKéMONS.\fEu devo copiar o\nque esta no quadro\vtambém.",
  ["56:4b47"] = "Troquei meu\nmelhor POKéMON\vcom o cara ao\vlado.",
  ["56:4b74"] = "Ha? O POKéMON\nque eu peguei\vesta segurando\valgo!",
  ["56:4ba6"] = "Um POKéMON\nsegurando um\vfruto vai se\vcurar sozinho.\fOs POKéMONS podem\nsegurar varios\vitens…\fE melhor eu anotar\ntudo isso…",
  ["56:4ea3"] = "E o caderno do\ngaroto…\fCapturar POKéMONS\nusando POKé BOLAS.\fPode ficar com\naté 6 POKéMONS na\vequipe.\fLer mais?",
  ["56:4f04"] = "Antes de jogar a\nPOKéBOLA, deixe o\valvo fraco.\fOs POKéMONS com\nveneno ou\vqueimados sao mais\vfaceis de pegar.\fLer mais?",
  ["56:4f74"] = "Alguns movimentos\ncausam confusao.\fA confusao pode\nfazer o POKéMON se\vatacar.\fFugindo, ele\nfica curado da \vconfusao.\fLer mais?",
  ["56:4ff4"] = "Quem pega e usa\nos POKéMON nas\vbatalhas, sao\vtreinadores\vPOKéMON.\fEles devem\nvisitar GINASIOS\vPOKéMON e\vderrotar outros\vtreinadores.\fA outra pagina\nesta vazia!\fGaroto: Opa…\fNao escrevi\nmais nada…",
  ["56:5167"] = "Ela usa nomes de\nsuas comidas\vprediletas.\fEla faz isso nos\napelidos dos\vPOKéMONS pelo que\veu percebi.",
  ["56:51cb"] = "Chamo o meu PIDGEY\nde MORANGO!",
  ["56:51e9"] = "MORANGO: Pijji!",
  ["56:52c2"] = "Ha quanto tempo,\n{PLAYER}!\fO PROFESSOR ELM\nme pediu para\vacha-lo.\fEle quer um\nfavorzinho.\fDeseja levar este\nOVO POKéMON?",
  ["56:5332"] = "Ele descobriu que\no POKéMON nao\vchocara até\vcrescer dentro\vdo OVO.    \fTem que estar\njunto com POKéMONS\fativos para\nchocar.\f{PLAYER}, voce\né o unico que\fpodemos confiar.\fAvise ao PROFESSOR\nELM quando o OVO\vchocar!",
  ["56:5400"] = "Ah nao. Voce esta\ncheio de POKéMONS\vai com voce. \fVou espera-lo\naqui enquanto\vlibera espaco.",
  ["56:545f"] = "Mas o PROFESSOR\nELM te pediu…",
  ["56:547f"] = "{PLAYER}, vai\nficar com o\vOVO?",
  ["56:549a"] = "Um tal de BILL\nfez o SISTEMA DE\vARMAZENAR OS\vPOKéMONS.",
  ["56:5549"] = "Os POKéMONS sao\nespertos!\fNao obedecem a\num treinador sem\vrespeito.\fSem as INSIGNIAS\ncorretas, eles\vfarao apenas o que\vquiserem.",
  ["56:5628"] = "Os POKéMONS troca-\n\ndos crescem\vrapidamente. \fCaso nao tenha\nas INSIGNIAS\vcorretas,\veles podem\vdesobedece-lo.",
  ["56:56c7"] = "RUINAS ALFA\fUm Ponto Turistico\nbem livre.\fTente mover as\npedras do painel!",
  ["56:5712"] = "Esta estudando as\nRUINAS?\fHa cientistas\nenvolvidos nisso.",
  ["56:574e"] = "Ha desenhos no\npainel de pedra.\fEu tentei\nmove-los.\vO que eles devem\vser?",
  ["56:5814"] = "Esse é um ponto\nde pesca.\fVoce viu pessoas\npescando? O que \vachou?\fVoce quer uma\ndas minhas VARAS?",
  ["56:5879"] = "Eh, é bom ouvir\nisso.\fAgora é um\npescador também!",
  ["56:58ac"] = "Pescar é otimo!\fSe tiver agua,\nseja no mar ou\vem outro lugar,\vuse a sua VARA.",
  ["56:58fd"] = "Oh. Isso é bem\ndesapontador…",
  ["56:591e"] = "Ei, meu jovem.\nComo eles mordem?",
  ["56:5943"] = "O que devo fazer\no meu POKéMON\vsegurar?\fTalvez algo que\nmelhore o seu\vATAQUE…",
  ["56:5a70"] = "Com licenca,\namigo!\fPode me fazer um\nfavor?\fVoce pode entregar\neste POKéMON com\vuma CARTA a um\vcolega na ROTA 31?",
  ["56:5adb"] = "Voce ira? Otimo!\nObrigado!\fMeu amigo é meio\ngordo, e dorme o\vtempo todo!\fVoce o reconhecera\ncom facilidade!",
  ["56:5b4b"] = "{PLAYER} recebeu o\nPOKéMON com uma\vCARTA.",
  ["56:5b69"] = "Voce pode ler,\nmas nao a perca!\vROTA 31!\fExiste uma\narvore misteriosa\vbloqueando a\vpassagem.\fSera que eu, fui\nbem claro agora?",
  ["56:5be9"] = "Nao pode carregar\nmais POKéMONS…",
  ["56:5c07"] = "Ah… Nao tem\nproblema…",
  ["56:5c1e"] = "Obrigado, rapaz!\nVoce fez a entrega\vpara mim!\fEu tenho algo\npara te ajudar!",
  ["56:5c6c"] = "Meu amigo estava\ndormindo, certo?\fEh, o que eu digo?",
  ["56:5d2d"] = "Eu gosto da\nmelodia POKéMON\vque eles tocam\vna radio!",
  ["56:5ef2"] = "Hoje é {STRBUF}.\nSignifica que\vo Concurso\vCaca-Inseto é\vhoje.\fAs regras sao\nsimples.\fUsando um dos seus\nPOKéMONS, pegue um\vPOKéMON inseto\vpara ser julgado.\fDeseja participar?",
  ["56:60cd"] = "Opa…\fVoce tem mais do\nque um POKéMON.\fVoce tera que usar\no {STRBUF}, seu \fprimeiro POKéMON\nna sua equipe.\fTudo certo, rapaz?",
  ["56:613e"] = "Bom, ficaremos\ncom os outros\vPOKéMONS enquanto\vcompetir.",
  ["56:619e"] = "Escolha o\nPOKéMON a ser usado no\vconcurso e volte\vaqui mais tarde.",
  ["56:61e3"] = "Certo. Contaremos\ncom voce na\vproxima vez.",
  ["56:620f"] = "Opa…\fO primeiro POKéMON\nna sua equipe nao\vpode batalhar.\fTroque-o pelo\nPOKéMON que quiser\vusar e volte aqui\voutra hora.",
  ["56:6283"] = "Opa…\fTanto sua equipe\nquanto seu BOX\vestao cheios.\fVoce nao tem lugar\npara colocar o\vPOKéMON inseto que\vpegou.\fLibere espaco na\nsua equipe ou no\vBOX e retorne\vaqui.",
  ["56:6326"] = "Opa…\fO primeiro POKéMON\nda sua equipe é\vum OVO.\fTroque-o pelo\nPOKéMON que deseja\vutilizar no\vconcurso e retorne\vaqui outra hora.",
  ["56:63a1"] = "Voce ainda tem\n{STRBUF} minuto(s)\vsobrando.\fDeseja parar\nagora?",
  ["56:63e2"] = "Certo. Aguarde na\nCabine do Norte\vpara a divulgacao\vdos vencedores.",
  ["56:642a"] = "Bom, volte la e\nfique até o fim\vdo concurso.",
  ["56:6456"] = "O concurso de hoje\nacabou.\fEsperamos\nque participe\vfuturamente.",
  ["56:64df"] = "Quando acontecera\no proximo Concurso\vCaca-Inseto?",
  ["56:660d"] = "Nao queria\nsaber quem fez\valgo como isso?\vE por que?",
  ["56:6648"] = "Voce viu aquela\narvore estranha\vna estrada?\fIsso explica\npor que muitos\vturistas visitam\vas RUINAS ALPH.",
  ["56:69c0"] = "Hoje é {STRBUF}.\nSignifica que\vo Concurso\vCaca-Inseto é\vhoje.\fAs regras sao\nsimples.\fUsando POKéMONS\nseus, pegue um\vPOKéMON inseto\vpara ser julgado.\fDeseja participar?",
  ["56:6b99"] = "Opa…\fVoce tem mais\ndo que um POKéMON.\fTera que\nusar {STRBUF}, o\vprimeiro POKéMON\vna sua equipe.\fEsta tudo bem com\nvoce?",
  ["56:6c0a"] = "Otimo. Vamos ficar\ncom seus outros\vPOKéMONS enquanto\vvoce compete.",
  ["56:6c6a"] = "Escolha o POKéMON\na ser usado no\vconcurso e venha\vme ver.",
  ["56:6caf"] = "Certo. Esperamos\nque voce participe\vno futuro.",
  ["56:6cdb"] = "Opa… O primeiro\nPOKéMON na sua\vequipe nao pode\vbatalhar.\fTroque-o por outro\nPOKéMON que\vdesejar e volte\vaqui depois.",
  ["56:6d4f"] = "Opa… Sua equipe\ne seu BOX do\vcomputador estao\vcheios.\fVoce nao tem lugar\npara colocar o\vPOKéMON que\ncapturar.\fLibere espaco na\nsua equipe ou\nem seu BOX do\vcomputador e volte\vaqui depois.",
  ["56:6df2"] = "Opa… Seu primeiro\nPOKéMON na equipe\vé um OVO.\fTroque-o pelo\vPOKéMON que\vdesejar e depois\vvolte aqui.",
  ["56:6e6d"] = "Voce ainda tem\n{STRBUF} minuto(s)\vsobrando.\fDeseja parar\nagora?",
  ["56:6eac"] = "Certo. Espere aqui\npara o anuncio dos\vvencedores.",
  ["56:6ee7"] = "Certo. Fique la\naté terminar.",
  ["56:6f12"] = "O concurso de hoje\nja acabou.\fEsperamos que\nparticipe no\vfuturo.",
  ["56:6ff6"] = "ED: Eu invejo\nvoce. Eu nao fui\vcapaz desta vez.",
  ["56:7027"] = "ED: Sera que voce\nganharia com um\vPOKéMON grande?",
  ["56:7049"] = "NICK: Bom\ntrabalho! Eu vou\vtreinar melhor meu\vPOKéMON.",
  ["56:707d"] = "NICK: Talvez voce\nobtenha uma\vpontuacao maior\vcom um POKéMON de\vuma cor incomum.",
  ["56:70c1"] = "WILSON: Voce é o\nvencedor? O que\vvoce capturou?",
  ["56:70f1"] = "WILSON: Bem, eu\nestou satisfeito\vporque eu capturei\vo POKéMON que eu\vdesejava.",
  ["56:7135"] = "BENNY: Parabéns!\nVoce conquistou\vmeu respeito.",
  ["56:7163"] = "BENNY: Eu peguei\num SCYTHER\vanteriormente, mas\veu nao ganhei.",
  ["56:7197"] = "BARRY: Aquele\nPOKéMON que voce\vcapturou… é\vincrivel!",
  ["56:71c4"] = "BARRY: E facil\nvencer quando se\vpega um POKéMON\vinseto de nivel\valto.\fMas acho que\neles levam outros\vfatores em\vconsideracao.",
  ["56:7232"] = "CINDY: Voce\nvenceu? Isso é\votimo!\fLigaria se\nprocurasse\vPOKéMONS insetos\vcomigo?",
  ["56:727f"] = "CINDY: Eu\nrealmente amo\vPOKéMONS insetos!",
  ["56:729f"] = "JOSH: Eu… eu nao\nacredito que perdi\vesse concurso…",
  ["56:72d0"] = "JOSH: Ouvi dizer\nque alguém ja\vvenceu com um\vCATERPIE!",
  ["56:7302"] = "SAMUEL: Na proxima\neu ganharei.",
  ["56:7327"] = "SAMUEL: Droga.\nAchei que eu tinha\vido melhor…",
  ["56:7356"] = "KIPP: Poderia me\ndar conselhos?\fQuero estudar seu\nestilo.",
  ["56:7396"] = "KIPP: Eu estudo\nmuito, mas nao é\vo bastante para\vvencer.",
  ["56:74dd"] = "Opa… Sua BOLSA\nesta cheia.\fVamos guardar o\nseu premio, mas\vso até o fim deste\vdia.\fLibere espaco\ve depois venha\vreceber o seu\vpremio.",
  ["57:4122"] = "Oi! Sou WHITNEY!\fTodo mundo gosta\nde POKéMONS,  \vinclusive eu!\fOs POKéMONS sao\nsuper bonitos!\fVoce quer\nbatalhar?\vVou te avisar,\veu sou boa!",
  ["57:41a5"] = "Ha?…\f…Buaaaaaaa!\nVoce mentiu!\fVoce nao devia\nlutar sério!\vSua, sua,\vcrianca!",
  ["57:41f5"] = "Buaaaah!\nBuaaaaa!\f…Droga, hic…\n…Mentiroso!",
  ["57:4223"] = "…Sniff…\fO que?\nO que voce quer?\fA INSIGNIA?\fCerto.\nEu esqueci.\fLeve a INSIGNIA\nPLANA.",
  ["57:4290"] = "A INSIGNIA PLANA\npermite ao\vPOKéMON usar o HM\vFOR'sA fora de\vbatalhas.\fTambém melhora a\nVELOCI…… do\vPOKéMON.\fAh, leve isto\ntambém!",
  ["57:4307"] = "E o ATRAI!\fIsso faz com que o\nPOKéMON use seu\vCHARME!\fNao é perfeito\npara facilmente\vpegar POKéMONS?",
  ["57:447a"] = "Eu tentei ganhar\nde WHITNEY…\vEstou deprimida! \fTudo bem, vou\ntreinar mais\vduro de agora em\vdiante!",
  ["57:44de"] = "Oh, nao. Voce fez\nWHITNEY chorar.\fTudo bem, ela\nja parou.\fSempre chora\nquando perde!",
  ["57:4644"] = "Oi! Seja\nBem-vindo!\fEste GINASIO é a\ncasa dos POKéMONS\vdo tipo normal.\fEu recomendo usar\nPOKéMONS lutadores\vna batalha!",
  ["57:46b1"] = "Voce venceu?\nOtimo.\fEstava ocupado\nadmirando-as!",
  ["57:4791"] = "…Poxa…\nMe mudei para ca,\vmas nao consigo\vvender. Por que\vsera?\fVoce pode pegar\numa BICICLETA e\vfazer propaganda?",
  ["57:4802"] = "Serio?\nOtimo!\fMe de seu nome\ne numero, que\vte empresto uma\vBICICLETA, amigo.",
  ["57:4852"] = "{PLAYER} pegou\na BICICLETA.",
  ["57:4869"] = "Minhas BICICLETAS\nsao de primeira,\vsobem até\vladeiras.",
  ["57:48a2"] = "…Poxa…\nHa poucas pessoas\vgenerosas!",
  ["57:49aa"] = "Se voce tratar\nseus POKéMONS\vbem, eles irao\vte amar também.\fDeixe-me ver o seu\n{STRBUF}…",
  ["57:4a06"] = "Ele parece\nrealmente feliz.\fEle te ama\nmuito!",
  ["57:4a36"] = "Tenho certeza,\nque ele confia\vmuito em voce.",
  ["57:4a98"] = "Muito atraente.",
  ["57:4aa9"] = "Voce devia\ntrata-lo melhor.\fEle quase nao\nluta!",
  ["57:4adb"] = "Ele parece nao\ngostar de voce.\vIsso parece ruim.",
  ["57:4b0e"] = "Eu continuo\nperdendo nas\vbatalhas.\fE meu POKéMON\nfica desmaiado.\fPor isto ele nao\ngosta muito de\vmim!",
  ["57:4b71"] = "Quando eu uso um\nartigo no meu\vPOKéMON, ele fica\valegre!",
  ["57:4d49"] = "BILL: Eu sabia!\nHora de ir, heroi!\fVoce é um grande\namigo, rapaz!\fBem, eu conto com\nvoce. Cuide muito\vbem dele.",
  ["57:4db5"] = "{PLAYER} recebeu\nEEVEE!",
  ["57:4dc8"] = "BILL: O PROFESSOR\nELM afirma que o\vEEVEE pode evoluir\vde varias e\vdesconhecidas\vmaneiras.",
  ["57:4e09"] = "Opa! Voce nao pode\nlevar mais\vPOKéMONS!",
  ["57:4e34"] = "Oh… O que fazer\nagora?",
  ["57:4e93"] = "Ah, voce coleciona\nPOKéMONS?\fMeu filho BILL é\num perito.\fEle teve que\npartir para o\vCENTRO POKéMON na\vCI…… ECRUTEAK!",
  ["57:4efa"] = "Estou tao feliz\nem ver meu filho\vde novo.",
  ["57:4f1d"] = "Voce é um\ntreinador?\fEu tenho um\nnumero de telefone\vutil para voce.",
  ["57:4f58"] = "{PLAYER} gravou\no numero do BILL.",
  ["57:4f72"] = "Meu irmao fez o\nsistema de guardar\vPOKéMONS no PC.\fEu iria te dar o\ntelefone do BILL…",
  ["57:4fc5"] = "Voce nao pode\ngravar mais\vnumeros.",
  ["57:4fe8"] = "Meu irmao mais\nvelho, BILL, fez\vo sistema de\varmazenar POKéMONS\vno PC.",
  ["57:50d7"] = "O trem nao\nchegou…\fEu sei!\nOs passageiros\vvao me pedir\vexplicacoes.\fEle nao funciona.",
  ["57:512e"] = "Em breve\npartiremos para\vSAFFRON.\fVoce deseja\nembarcar?",
  ["57:5164"] = "Eu posso ver seu\nPASSE?\fCerto. E por aqui,\nsenhor.",
  ["57:51a0"] = "Perdao. Voce nao\ntem um PASSE.",
  ["57:51c3"] = "Nos esperamos\nve-lo novamente!",
  ["57:51de"] = "Nos chegamos a\nGOLDENROD.\fNos esperamos\nve-lo de novo.",
  ["57:5217"] = "Eu sou o\nPRESIDENTE.\fMeu sonho foi\nconstruir um trem\vque fosse mais\vveloz que todos\vPOKéMONS.\fEle aproxima\nJOHTO de KANTO.",
  ["57:53b6"] = "Lalala lalalala.\nTomem muita agua \vmeus amores!",
  ["57:5485"] = "Sabe algo sobre\na arvore maluca?\fSe voce rega-la,\nele da um pulo\vem voce!",
  ["57:5513"] = "O COLISEU--no\nandar superior de\vqualquer CENTRO\vPOKéMON, foi feito\vpara batalhas\vconectadas.\fOs recordes de\nbatalhas ficam\vexpostos na\vparede, entao nao\vposso pensar em\vperder.",
  ["57:5597"] = "Eu queria saber\nquantos POKéMONS\vha no mundo.\fO PROFESSOR\nCARVALHO, a tres\vanos atras, disse\vque havia 150\vtipos diferentes.",
  ["57:5614"] = "Um POKéMON de\nnivel mais alto\vnem sempre ganha.\fPois, ele pode ser\nfraco contra um\vtipo de POKéMON.\fAcho que nao\nexiste um POKéMON\vforte contra todos\vos tipos.",
  ["57:56fb"] = "Uma vez quando\nestava batalhando,\vmeu POKéMON nao\vtinha poderes.\fOs PONTOS de\nPODER, ou PP,\vcriam um tipo\vde ataque!",
  ["57:576f"] = "As vezes, um\nPOKéMON saudavel\vé incapaz de\vutilizar um\vataque.\fSe isto acontecer,\nleve-o a um CENTRO\vPOKéMON ou lhe\vde um artigo.",
  ["57:5a35"] = "A LOJA DE\nDEPARTAMENTOS tem\vuma boa selecao de\vprodutos.\fMas ha itens que\nsao apenas\vavaliaveis como\vpremios da CASA\vDE JOGOS.",
  ["57:5a38"] = "Bem-vindo a LOJA\nDE DEPARTAMENTOS\vDE GOLDENROD!",
  ["57:5a5c"] = "A LOJA DE\nDEPARTAMENTOS tem\vuma boa selecao de\vprodutos.\fMas ha itens que\nsao apenas\vavaliaveis como\vpremios da CASA\vDE JOGOS.",
  ["57:5abf"] = "Hoje eu vim fazer\ncompras de novo!",
  ["57:5adf"] = "Minha mae é boa em\npechinchar.\fEla sempre compra\ncoisas baratas.",
  ["57:5c0d"] = "Nos queremos\nvender itens para\vos POKéMONS\vsegurarem.\fLeve esse premio.\fFaca um POKéMON\nsegurar.",
  ["57:5cb7"] = "A POKéGEAR pode\narmazenar até dez\vtelefones.\fE dificil escolher\nos numeros que\vficarao.",
  ["57:5d0d"] = "Eu ganhei meu ABRA\nna CASA DE JOGOS.\fAgora é meu melhor\nparceiro.",
  ["57:5d49"] = "Esta LOJA me faz\nperceber que\vGOLDENROD é uma\vgrande cidade.\fOs produtos aqui\nnao se encontram\vem nenhum lugar!",
  ["57:5e5b"] = "Eu, eu sou muito\nimpaciente!\fEu uso RAPIDEZ\nX nas batalhas\vpara acelerar o\vPOKéMON.",
  ["57:5ea7"] = "Ei, quando\nbatalha, voce usa\vo ESPECIAL X?\fE incrivel!\fEle melhora o\nESPECIAL do\vPOKéMON!",
  ["57:5fe7"] = "O FERRO aumenta a\nDEFESA dos\vPOKéMONS.",
  ["57:6009"] = "Alguns POKéMONS so\nevoluem se forem\vtrocados através\vdo CABO LINK.\fEu sei quatro:\nMACHOKE, KADABRA,\vHAUNTER e, hum,\vGRAVELER.\fDizem que ainda\nha outros\vPOKéMONS.",
  ["57:61d5"] = "Ola. Oh, seu\nPOKéMON…",
  ["57:61ef"] = "E muito atraido a\nvoce.\fEsse golpe deve\nser perfeito para\vum par como voces.",
  ["57:623b"] = "E adoravel!\fVoce deve\nensina-lo bons\vgolpes TM.",
  ["57:626d"] = "Esse parece mau.\nQue tal esse TM\vpara ele(a)?",
  ["57:6297"] = "Certamente ha TMs\nque sao perfeitos\vpara os seus\vPOKéMONS.",
  ["57:62d6"] = "ITEM SECRETO.\fCom um pequeno\nbip, voce ganha\vpresentes!",
  ["57:630e"] = "A opcao ITEM\nSECRETO requer um\vGame Boy Color.",
  ["57:6342"] = "Aos domingos, uma\nsenhora vem ver os\vPOKéMONS.\fEla até faz\ndoacoes de TMs!",
  ["57:6388"] = "Voce nao pode\nrenomear os\vPOKéMONS trocados.\fOs nomes sao os\nreflexos dos\vsentimentos que os\vex-treinadores\vtinham por eles.",
  ["57:655d"] = "Uma Maquina de\nVenda!\vOlhe o MENU.",
  ["57:6584"] = "Click! Saiu uma\nlata de\v{STRBUF}!",
  ["57:65a7"] = "Opa, quantia\ninsufuciente.",
  ["57:65c0"] = "Nao ha mais espaco\npara isso.",
  ["57:65e0"] = "Voce ouve o CANAL\nda SORTE?\fSe voce quiser\nganhar, troque\vPOKéMONS com o\vmaximo de pessoas\vpossiveis para ter\vvarios N→MEROS DE\vIDENTIFICA'sAO.",
  ["57:665f"] = "Se estiver\ncansado, beba as\vbebidas da maquina\vde venda.\fOs seus POKéMONS\nvao adorar também!",
  ["57:6ab5"] = "Bem-vindo!\fNos trocamos suas\nmoedas por otimos\vpremios!",
  ["57:6af0"] = "De qual premio\nvoce gosta?",
  ["57:6b0d"] = "{STRBUF}.\nEsta certo?",
  ["57:6b22"] = "Aqui esta!",
  ["57:6b30"] = "Perdao! Precisa\nde mais moedas!",
  ["57:6b4d"] = "Perdao! Nao pode\ncarregar mais.",
  ["57:6b6e"] = "Bom, guarde suas\nmoedas e volte\vdepois!",
  ["57:6b9a"] = "Oh? Voce nao tem\num COFRE.",
  ["57:6bba"] = "Eu sempre jogo\nnesta maquina.\fAcho que ela paga\nmais que as\voutras.",
  ["57:6c59"] = "A vida é jogar.\nEu jogarei até\vacabar minhas\vmoedas!",
  ["57:6c90"] = "Cartoes…\fEu prefiro usar o\ncartao, porque\vé mais dificil de\vperder, nao acha?\fPorém o pagamento\né menor.",
  ["57:6cfc"] = "Eu nao saio,\naté ganhar!",
  ["57:6d16"] = "Eu ensinei\nTEMPORAL ao meu\vPOKéMON.\fFoi duro conseguir\nmoedas para isto,\vmas valeu a pena,\vcara.",
  ["57:6f2c"] = "A FLORESTA ILEX\né grande. Cuidado.\vNao se perca.",
  ["57:6f5c"] = "A FLORESTA é\nobservada pelo seu\vprotetor.\fNao faca\ntravessuras!",
  ["57:6ffe"] = "Ah, querido. Voce\nesta completando\va POKéDEX?\fDeve ser dificil\nse o POKéMON nao\vaparecer.\fTente usar esse\nTM.",
  ["57:70b6"] = "Voce viu o\nsantuario em honra\vdo protetor da\vfloresta?\fEle vigia a\nFLORESTA ha muito\vtempo.\fEu acho que ele é\num POKéMON do tipo\vgrama.",
  ["57:71b5"] = "Vovo procurava\npor voce.",
  ["59:4255"] = "O NAVIO VELOZ é um\nexcelente local\vpara treinadores\vse encontrarem e\vbatalharem.",
  ["59:4292"] = "Oh? Voce possui\nINSIGNIAS que eu\vnunca tinha visto\vantes!\fAh, agora eu\nentendi!\fVoce as obteve no\ncontinente JOHTO.",
  ["59:4468"] = "Otimo!\fPreste atencao!\fBom… o\nmeu favorito é o\vRAPIDASH.\fEle é… lindo…\namavel… esperto…\vprestativo…\vfantastico… Oh…\fVoce também acha?…\nBastante…\vselvagem… bonito…\vgentil… eu o amo!\fO abraco… quando…\ndurmo… é morno e\vmacio…\fOh, é…\nespetacular…\vencantador…\ve simplesmente\vdivino…\fOpa! Olhe as\nhoras!\fEu gastei muito\ndo seu tempo!",
  ["59:4594"] = "Obrigado por me\nescutar.\fEu quero que\naceite isso!",
  ["59:4637"] = "Ola, {PLAYER}!\fVoce veio aqui\npara saber sobre\vo meu POKéMON de\vnovo?\fNao?\fOh… Eu tenho mais\ncontos para\vcontar…",
  ["59:468f"] = "Que pena…\fVolte aqui se\nquiser escutar.",
  ["59:46c4"] = "Nosso PRESIDENTE é\nmuito oral quando\vse trata de\vPOKéMONS…",
  ["59:46f7"] = "Eu amo o jeito que\na CLEFAIRY balanca\vos dedos quando\vtenta usar o\vMETR'lNOMO.\fE tao adoravel!",
  ["59:4756"] = "Eu amo a CLEFAIRY,\nmas eu nunca\vcapturei uma.\fEu a substituo\npela BONECA que\veu achei.",
  ["59:47b1"] = "Oh, eu entendi.\nA garota que\vperdeu essa BONECA\vesta triste…\fPoderia levar esta\nBONECA aquela\vpobre garotinha?\fEu capturarei uma\nCLEFAIRY para\vmim um dia.\fSem duvidas!",
  ["59:4861"] = "{PLAYER} recebeu a\nBONECA.",
  ["59:4875"] = "Voce vera!\fEu ainda terei\numa verdadeira\vCLEFAIRY como\vamiga.",
  ["59:48af"] = "Sua BOLSA esta\nmuito cheia.",
  ["59:48ca"] = "Olhe a minha\ncorajosa BAYLEEF!\fA folha em sua\ncabeca é tao\vlinda!",
  ["59:4908"] = "E uma CLEFAIRY?\fHa?\fAh, bem. E uma\nBONECA CLEFAIRY.",
  ["59:4a14"] = "Voce sabe algo\nsobre o TREM\vMAGNETO?\fE uma estrada de\nferro que vai a\vGOLDENROD no\vcontinente JOHTO.",
  ["59:4a6d"] = "Eu quero ir a\nSAFFRON para ver\vo TREM MAGNETO.",
  ["59:4b21"] = "Estou pensando em\nir fazer compras\vem SAFFRON.",
  ["59:4b8b"] = "No passado, os\nDIGLETTS cavaram\vum largo tunel que\vvai a uma cidade\vdistante.",
  ["59:4c99"] = "SURGE: Ei,\ngarotinho!\fTenho que cuidar\nde voce.\fPode nao ser muito\nesperto em me\vdesafiar, mas \vtudo bem!\fQuando se trata\nde POKéMONS\velétricos, eu sou\vo numero um!\fEu nunca perdi no\ncampo de batalha.\fVou derrota-lo\ncomo fiz com\vmeus inimigos na\vguerra!",
  ["59:4e55"] = "SURGE: Ei, garoto!\nContinua agindo\vfeito lesma por\vai?\fMeus POKéMONS e eu\nainda somos os\vmelhores!",
  ["59:5069"] = "Ei! CAMPEAO em\nprogresso. Voce\vteve sorte desta\vvez.\fO TENENTE SURGE é\nbem cauteloso.\fEle fez armadilhas\npor todo GINASIO.\fMas, he-he-he, as\narmadilhas estao\vdesativadas.\fVoce facilmente\nalcancara o\vTENENTE SURGE.",
  ["59:5131"] = "Uau! Essa foi uma\nbatalha elétrica!\fCertamente me\ndeixou nervoso.",
  ["59:5250"] = "Bem-vindo a CI……\nSAFFRON, lar do\vTREM MAGNETO!\f…E o que eu\nnormalmente digo,\vmas o TREM\vMAGNETO nao esta\vfuncionando agora.\fNao ha\neletricidade\vporque existe algo\vde errado com a\vUSINA DE ENERGIA.",
  ["59:531d"] = "O TREM MAGNETO é a\ncoisa mais famosa\vaqui na CI……\vSAFFRON.",
  ["59:53b5"] = "{PLAYER}-POKéOi!\fASH tem estado\nfora ha muito\vtempo.\fEle nao telefona,\nentao nao tenho\vidéia de onde ele\vesta nem do que\vfaz agora.\fDizem que nenhuma\npalavra é prova\vde que ele esta\vbem.\fEstou preocupada.",
  ["59:547c"] = "Se ele estiver\ndoente ou\vmachucado?\fEle é um garoto.\fEstou orgulhosa\nporque ele faz o\vque ele quer.",
  ["59:562b"] = "DAISY: Oi! Meu\nirmao menor é\vLIDER do GINASIO\vda CI……\vVERIDIANA.\fPorém, ele\nviaja bastante,\vprejudicando mui-\vtos treinadores.",
  ["59:56b1"] = "DAISY: Oi! Tudo\nbem? \fEstou indo\vtomar um cha.\fGostaria de\njuntar-se a mim?\fOh, seus POKéMONS\nestao meio sujos. \fGostaria que eu\nlimpasse um?",
  ["59:573f"] = "DAISY: Qual deles\ndevo limpar?",
  ["59:5761"] = "DAISY: Certo,\ndeixarei ele limpo\vnum instante.",
  ["59:57f5"] = "DAISY: Eu sempre\ntomo cha nesta\vhora.\fVenha tomar um.",
  ["59:582f"] = "DAISY: Voce nao\nquer se limpar um\vpouco?\fCerto, tomaremos\num cha.",
  ["59:5872"] = "DAISY: Desculpe,\nmas eu nao posso\vlimpar OVOS.",
  ["59:5922"] = "CARVALHO: Ah,\n{PLAYER}!\fFoi bom voce ter\nandado todo esse\vcaminho em KANTO.\fO que achou dos\ntreinadores daqui?\fBem fortes, né?",
  ["59:599d"] = "Como vai indo sua\nPOKéDEX?\fVamos ver…",
  ["59:59c3"] = "Se ficar por aqui,\nespero que me\vvisite novamente.",
  ["59:5b9d"] = "CARVALHO: Hum?\nNao esta\vcolecionando as\vINSIGNIAS DE\vKANTO?\fOs LIDERES DE\nKANTO sao tao\vfortes quanto os\vde JOHTO.\fEu acho que voce\ndeve desafia-los.",
  ["59:5c37"] = "CARVALHO: Ah,\nesta colecionando\vas INSIGNIAS DE\vKANTO.\fDeve ser dureza,\nmas sua\vexperiencia lhe\vajudara.\fVenha me ver\nquando pegar todas\velas.\fTerei um presente\npara voce.\fTreine bastante,\n{PLAYER}!",
  ["59:5d54"] = "Gracas ao seu\ntrabalho na\vPOKéDEX, a\vpesquisa do\vPROFESSOR esta\vindo muito bem.",
  ["5a:400f"] = "NIDORAN, trema!",
  ["5a:41b6"] = "BROCK: Os\npoderosos ataques\vdos seus POKéMONS\vsuperaram a minha\vdefesa rochosa…\fVoce é mais forte\ndo que esperei.\fVa em frente,\nleve a INSIGNIA.",
  ["5a:4252"] = "BROCK: {PLAYER},\nObrigado.\fGostei de batalhar\ncom voce, embora\vesteja chateado.\fA INSIGNIA DA\nPEDRA fara seus\vPOKéMONS ficarem\vmais poderosos.",
  ["5a:42d5"] = "BROCK: O mundo é\nenorme.\fExistem outros\ntreinadores fortes\vcomo voce.\fSo espere e vera. \fEu vou ficar muito\nmais forte também.",
  ["5a:440a"] = "Ei voce!\fTreinador de\nJOHTO!\fBROCK é durao.\nEle lhe castigara\vse nao batalhar\vcom seriedade.",
  ["5a:4502"] = "Ei! CAMPEAO em\nprogresso!\fEste GINASIO nao\nlhe deu trabalho.\fO modo como\nbatalhou foi muito\vinspirador.\fFalo com\nseriedade.",
  ["5a:4635"] = "Existia um velho\nmisterioso que\vvendia MAGIKARP.\fEle dizia que as\nMAGIKARPS do\vLAGO DA RAIVA\veram excelentes.",
  ["5a:46fc"] = "…Sim, o\nGINASIO em\vCINNABAR fechou.\fEu estou pasma.\fSim?\nEstou no telefone.\vVa embora!",
  ["5a:4770"] = "A maioria dos\nPOKéMONS ficam\vsonolentos se o\vJIGGLYPUFF cantar.\fExistem varios\ngolpes que so sao\vusados quando o\vPOKéMON adormece.",
  ["5a:4857"] = "Gosto de dormir\ncom o radio\vligado…\f…Zzz…",
  ["5a:4aa1"] = "Espere.\fVoce recebera o\ndesafio da LIGA\vPOKéMON agora?\fIsso nao vai\nacontecer.\fMeus POKéMONS\ntreinados de mane-\vira incrivel vao\vderrota-lo.\f{PLAYER},\neu desafiarei\vvoce!",
  ["5a:4b50"] = "…Droga…\nAinda nao posso\vvencer…\fEu devo pensar\nmais nos meus\vPOKéMONS…\fTsc! Tente nao\nperder!",
  ["5a:4ba9"] = "\fCerto--Eu perdi…",
  ["5a:4c93"] = "Certo. Ilustre sua\ncasa na sua mente…",
  ["5a:4cbd"] = "Bom, te desejo a\nmelhor sorte!",
  ["5a:4ed8"] = "Eu… nao…\nacredito…",
  ["5a:5155"] = "Ah! Voce provou o\nseu valor!",
  ["5a:5176"] = "Eu submeti voce a\ntudo que eu podia.\fMas a minha\ntentativa falhou.\fEu devo afiar\nminhas técnicas.\fVa a proxima sala,\ne teste as suas\vhabilidades!",
  ["5a:53cf"] = "Por que? Como eu\npude perder?",
  ["5a:53e8"] = "Como eu perdi, eu\nnao tenho o\vdireito de dizer\vnada…\fVa em frente e\nencare o seu\vproximo desafio!",
  ["5a:55a4"] = "Bem, voce é forte.\nGosto disto num\vtreinador.",
  ["5a:55d5"] = "POKéMONS fortes.\nPOKéMONS fracos.\fIsto é so a\npercepcao egoista\vdas pessoas.\fOs treinadores\nverdadeiramente \vbons podem\vtreinar quaisquer\vPOKéMONS.\fGosto do seu\nestilo.\vVoce entende o que\vé importante.\fVa, o nosso\ncampeao o espera.",
  ["5a:5816"] = "LANCE: Eu estava\nlhe esperando.\f{PLAYER}!\nEu sabia que\vcom as suas\vhabilidades voce \vconseguiria \vchegar aqui.\fNao precisa falar\nnada agora.\fNos batalharemos\npara ver qual de \vnos dois é o mais\vpoderoso.\fComo o treinador\nmais poderoso, e\vcomo o CAMPEAO DA\vLIGA POKéMON…\fEu, LANCE o mestre\nde POKéMONS\vdragoes, aceito\vseu desafio!",
  ["5a:5953"] = "…Acabou.\nMas estou meio\vestranho.\fNao estou zangado\npela luta, acho\vque estou feliz.\fFeliz ja que\nacompanhei a\vformacao de um\vnovo CAMPEAO!",
  ["5a:59e1"] = "…Uau.\nVoce se tornou\vpoderoso,\v{PLAYER}!\fSeus POKéMONS\nlutaram de uma\vforma valente, e\vmostraram serem\vseus amigos.\fComo um teinador,\nvoce continuara a\vcrescer forte com\vseu POKéMON.",
  ["5a:5a8c"] = "MARY: Oh, nao!\nJa acabou tudo!\fSe voce nao fosse\ntao devagar,\vPROFESSOR CARVA-\vLHO…",
  ["5a:5aca"] = "CARVALHO: Ah,\n{PLAYER}!\fFaz tempo que o\nvi.\fVoce esta\nmuito mais\vamadurecido.\fSua conquista na\nLIGA foi\vfantastica!\fSua dedicacao,\nconfianca e amor\vpor seus POKéMONS \vfez isto\vacontecer.\fSeu POKéMON esta\nem excelente\vestado.  \fPorque eles\nacreditaram em\vvoce como um\vtreinador POKéMON.\fMeus Parabéns por\nisto {PLAYER}!",
  ["5a:5bf6"] = "MARY: Vamos\nentrevistar este\vnovo CAMPEAO!",
  ["5a:5c26"] = "LANCE: Isto esta\nse tornando meio\vbarulhento…\f{PLAYER}, voce\npode vir comigo?",
  ["5a:5c70"] = "MARY: Oh, pare!\nAinda nao o\vintrevistamos!",
  ["5a:5d51"] = "LANCE: Faz muito\ntempo que vim \vaqui pela ultima\vvez.\fAqui, é onde\nhonramos os\vCAMPEOES da LIGA\vpela eternidade.\fSeus corajosos\nPOKéMONS também\vterao lugar.\fHoje,\ntestemunhamos a\vsubida de um novo\vCAMPEAO da LIGA,\vum treinador que\vsente compaixao,\ve confianca pelos\vseus POKéMONS.\fUm treinador que\nteve sucesso pela\vperseveranca e\vdeterminacao.\fO novo CAMPEAO\nda LIGA, que\vtem todas as\vqualidades da\vgrandeza!\f{PLAYER},\ndeixe-me registrar\vvoce e seus\vcomanheiros como\vCAMPEOES!",
  ["5b:41b3"] = "Partiremos logo.\nVa em frente, por\vfavor.",
  ["5b:41de"] = "Desculpe-me. Voce\nnao pode embarcar\vagora.",
  ["5b:4238"] = "Posso ver sua\nPASSAGEM, senhor?",
  ["5b:4259"] = "Esperamos voltar\na ve-lo!",
  ["5b:4274"] = "{PLAYER} mostrou\nsua PASSAGEM.\fMuito bem.\nObrigado, amigo!",
  ["5b:42a9"] = "{PLAYER} tentou\nmostrar sua\vPASSAGEM…\fMas voce nao tem!\fDesculpe, voce\nso vai viajar se\vtiver uma\vPASSAGEM.",
  ["5b:4336"] = "Este NAVIO\nsaira na proxima\vSEXTA.",
  ["5b:435c"] = "Capturar SHELLDERS\naqui é facil.\fEles sao raros\nem outro lugar.",
  ["5b:439d"] = "Quantas POKé BOLAS\nvoce tem?\fTodas POKé BOLAS\npegam POKéMONS\vdiferentes.",
  ["5b:43de"] = "O NAVIO usa jatos\npara passar por\vondas!",
  ["5b:440a"] = "Existem muitos\nPOKéMONS em KANTO.\fEu quero ir la…",
  ["5b:443f"] = "Nao queremos que\nvoce caia no mar,\ventao nao passe\vdaqui agora.",
  ["5b:466e"] = "Partiremos logo.\fVa em frente,\npor favor.",
  ["5b:4699"] = "Desculpe-me. Voce\nnao pode embarcar\vagora.",
  ["5b:46f3"] = "Posso ver sua\nPASSAGEM, senhor?",
  ["5b:4714"] = "Esperamos voltar a\nve-lo!",
  ["5b:472f"] = "{PLAYER} mostrou\nsua PASSAGEM.\fOtimo. Obrigado,\nsenhor!",
  ["5b:4764"] = "{PLAYER} tentou\nmostrar a\vPASSAGEM…\f…Mas voce nao tem!\fDesculpe! Voce so\nviajara se tiver\vuma PASSAGEM.",
  ["5b:47f2"] = "O NAVIO saira no\nproximo Domingo.",
  ["5b:4818"] = "Voce veio de\nJOHTO?\fEu soube que ha\nPOKéMONS raros\vmorando la.",
  ["5b:49ad"] = "Este NAVIO esta\nnos levando a\vCI…… VERMILION.\fNos avisaremos\nquando chegarmos\vaté la.",
  ["5b:4a0d"] = "Este NAVIO esta\nnos levando a\vCI…… OLIVINE.\fNos avisaremos\nquando chegarmos\vaté la.",
  ["5b:4a6b"] = "Aqui é sua cabine.\fSe seu POKéMON\nse machucar, tire\vum cochilo.\fIsto ira curar\ntodos.",
  ["5b:4ac1"] = "Aqui é sua cabine.\fVoce pode curar\nseu POKéMON \vtirando um\vcochilo.\fO NAVIO chegara\nenquanto, voce\vestiver dormindo.",
  ["5b:4b32"] = "Todos os\npassageiros sao\vtreinadores.\fEles estao\nesperando batalhas\vnas cabines.",
  ["5b:4c04"] = "O NAVIO chegou ao\ncais da CI……\vOLIVINE.",
  ["5b:4c35"] = "O NAVIO chegou ao\ncais da CI……\vVERMILION.",
  ["5b:4f4b"] = "Eu me pergunto:\nha montanhas para\vse escalar la em\vKANTO?",
  ["5b:4f89"] = "Sim, sou um\nmarinheiro, certo?\fNao estva fugindo\ndo trabalho.\fEsta cabine estava\nvazia dai\vcochilei!\fAh, esquece isto!\nVamos lutar!",
  ["5b:500e"] = "Desculpe, sou\no culpado!",
  ["5b:5028"] = "Por eu ser\nmarinheiro uso\vmuita forca\vfisica.\fEstava esgotado!",
  ["5b:526d"] = "Estou indo a KANTO\npara fazer shows\vde sopra-fogo!",
  ["5b:570e"] = "Bem! Obrigado\npor vir junto.\fDevido aquela\npequena menina eu\vja estou esgotado.",
  ["5b:5760"] = "Como voce gostaria\nque fosse o NAVIO?\fEle praticamente\vpatina nas ondas.",
  ["5b:57aa"] = "Ola, filho…\nEu nao encontro\vminha neta.\fSe estiver no\nnavio, tudo bem. \fMas e se ela caiu\nneste mar?\fEla é uma crianca\nenérgetica, se ela\vestiver causando\vproblema a alguém?",
  ["5b:585a"] = "{PLAYER}, né?\nOuvi dizer que\vvoce divertiu a\vminha neta.\fQuero lhe dizer\nobrigado por tudo.",
  ["5b:58b2"] = "Eu sei! Eu quero\nque pegue isto!",
  ["5b:58d5"] = "Estamos viajando\npelo mundo.",
  ["5b:58f7"] = "CAPITAO, vamos\nbrincar, por\vfavor?\fChato!\fEu quero brincar!",
  ["5b:5936"] = "Oi! Voce vai\nbrincar comigo?\fOh! Vovo esta\npreocupado comigo?\fJa vou indo!\fTenho que achar\no Vovo!",
  ["5b:599b"] = "Vovo aqui estou!\nEu estava\vbrincando com o\vCAPITAO e com ele!",
  ["5b:59dd"] = "Me perdi quando\nbrincava!",
  ["5b:5d15"] = "O NAVIO VELOZ\nchegou a CI……\vVERMILION.",
  ["5b:5f4b"] = "Ei, cara.\nVoce poderia\vprocurar meu amigo?\fEle deve estar\ndormindo, aquele\vpreguicoso!\fEu queria\nprocura-lo, mas\vestou trabalhando\vagora.",
  ["5b:5fd7"] = "Oh, nao…\fO CAPITAO ficara\nfurioso…",
  ["5b:5ffe"] = "Obrigado, cara!\nEu fiz ele pensar\vno que fez e entao\vele moderou!",
  ["5b:603d"] = "Uma garotinha?\fEu acho que a vi\nindo por aqui.",
  ["5b:606d"] = "A sala de jantar\né la em cima.\fAs escadas no\nfinal vao a cabine\vdo CAPITAO.",
  ["5b:66ed"] = "O NAVIO VELOZ\nnavega todas as\vQuartas e Domin-\vgos.",
  ["5b:6882"] = "Quando o sol se\npoe, CLEFAIRYS\vsaem para brincar.",
  ["5c:424f"] = "Hahahaha…\fPerdao por\ndesaponta-lo…\fE so uma piada!\fEu sou a\nverdadeira!\fJANINE do GINASIO\nDE FUCHSIA é eu!",
  ["5c:42bb"] = "JANINE: Voce é\nforte.\fVoce venceu\ndefinitivamente.\fAqui esta a\nINSIGNIA DA ALMA.\vLeve-a!",
  ["5c:431c"] = "JANINE: Voce é\nmuito forte!\fTenho um presente\nespecial! E o\vTOXICO, um forte\vveneno que tira\vPS aos poucos da\vvitima.",
  ["5c:438e"] = "JANINE: Eu vou\nrealmente me\vaplicar e melhorar\vminhas técnicas.\fEu quero superar\no meu Pai e voce\vtambém!",
  ["5c:4440"] = "Eu enganei voce…",
  ["5c:4453"] = "Como destinguira\nnossa verdadeira\vLIDER?",
  ["5c:4480"] = "Te enganei!\nHahaha!",
  ["5c:4495"] = "Ooh… Eu perdi…\nVoce nao é fraco…",
  ["5c:44d5"] = "Eu sou JANINE!\fComo soube quem\neu era de verdade?\fVamos batalhar!",
  ["5c:450b"] = "Droga! Eu queria\nvencer!",
  ["5c:4526"] = "Voce deve estar\ncansado.",
  ["5c:4542"] = "Hahaha!\fVoce errou! Eu\nsou JANINE!",
  ["5c:456a"] = "Meu disfarce\nestava bom! Droga!",
  ["5c:458b"] = "Ei, cara.\nMeu disfarce era\vbonito ou o que?",
  ["5c:45ba"] = "Voce, CAMPEAO em\nprogresso! Opa!\vOlhe bem ao seu\vredor.\fTodos treinadores\nse parecem com\va LIDER, JANINE.\fQual deles é a\nverdadeira JANINE?",
  ["5c:4646"] = "A batalha foi\notima, treinador\vde JOHTO.",
  ["5c:46e4"] = "Meu avo esta na\ncasa do meu irmao\vBILL, na PENINSULA\vDE CERULEANA.",
  ["5c:471a"] = "Eu vi estes\nestranhos e lentos\vPOKéMONS na PISTA\vDE CICLISMO.",
  ["5c:47b5"] = "Ei! Voce tem um\nnovo tipo de\vPOKéDEX.\fFoi o PROFESSOR\nCARVALHO que te\vdeu?",
  ["5c:47fd"] = "Eu fiquei\nbem chocada no\vGINASIO.\fTodas as garotas\ntinham aparencia\videntica.",
  ["5c:484f"] = "Eu sou JANINE!\nOpa! Errei… \vPuf!",
  ["5c:486f"] = "Viu? Me pareco com\nela agora!",
  ["5c:4ac2"] = "Voce esta\ntrabalhando com a\vPOKéDEX.\fQue legal! Nao\ndesista!",
  ["5c:4c10"] = "Oh, querido.\nVoce me achou.\fNao conte a ninguém sobre mim.\fEu lhe darei\nisso por guardar\vsegredo.\fTudo bem?",
  ["5c:4c81"] = "E duro ser uma\nmuito famosa.\n     \fSeja onde eu for,\nas pessoas me\vperseguem.\fEu so quero ficar\nsozinha!",
  ["5c:4fa4"] = "Bem-vindo ao\nCOLISEU CLUBE\vCABO.  \fVoce pode\nbatalhar aqui!\fVoce quer fazer\numa batalha?",
  ["5c:50e2"] = "Seu amigo nao\nesta aqui.",
  ["5c:50fd"] = "Antes de conectar\nvoce deve salvar\vo seu jogo.",
  ["5c:5130"] = "Aguarde!",
  ["5c:513e"] = "A conexao foi\nfechada devido a\vinatividade.\fPor favor, chame\nseu amigo e venha\vnovamente.",
  ["5c:51f2"] = "Nao pode conectar\nao passado aqui.",
  ["5c:5213"] = "Seu amigo escolheu\noutra sala.",
  ["5c:5238"] = "Entre por favor.",
  ["5c:5258"] = "Perdao-{STRBUF}\nnao pode ir.",
  ["5c:5275"] = "Nao pode levar o\n{STRBUF} com   \v{STRBUF}.",
  ["5c:529c"] = "Nao pode levar o\n{STRBUF} que tem\vCARTA com voce.",
  ["5c:535d"] = "Ola! Voce é\n{PLAYER}, certo? \fEu tenho algo para\nvoce.",
  ["5c:5391"] = "Aqui esta!",
  ["5c:539f"] = "Esperamos servi-lo\nde novo.",
  ["5c:53bc"] = "Oh, voce nao tem\nlugar para isso.\fPare em qualquer\nCENTRO POKéMON\vpelo mundo e\vpegue-o.",
  ["5c:541a"] = "Nao? Isso é muito\nestranho…",
  ["5c:553d"] = "Seu amigo esta\npronto.",
  ["5c:55be"] = "Seu amigo esta\npronto.",
  ["5d:401f"] = "Ao norte de\nLAVANDA fica o\vTUNEL DE PEDRA.\fVa através dele\npara chegar a\vUSINA DE ENERGIA.",
  ["5d:4072"] = "Ha um programa de\nradio que toca a\vmusica da POKé\vFLAUTA.\fMas seu radio\nprecisa do CARTAO\vEXPANSOR para\vsintonizar nesta\vestacao!",
  ["5d:40db"] = "A ESTA'sAO DE RADIO\nnao pode operar\nporque nao tem\venergia.",
  ["5d:411e"] = "O DIRETOR da\nESTA'sAO DE RADIO\vcom certeza esta\vfeliz.\fEle disse que a\nradio voltou a\vfuncionar porque\va USINA DE ENERGIA\vesta funcionando\vnormalmente de\vnovo.",
  ["5d:421f"] = "Suitas pessoas de\ncoracao frio param\vde cuidar de seus\vPOKéMONS.\fMeu avo traz\nestes POKéMONS\vabandonados para\vcasa e cuida deles\vde maneira\vadequada.",
  ["5d:4222"] = "O SENHOR FUJI\nmora aqui, mas nao\vesta em casa\vagora.\fEle deve estar na\nCASA DA ALMA.",
  ["5d:4271"] = "Suitas pessoas de\ncoracao frio param\vde cuidar de seus\vPOKéMONS.\fMeu avo traz\nestes POKéMONS\vabandonados para\vcasa e cuida deles\vde maneira\vadequada.",
  ["5d:437b"] = "O SENHOR FUJI\nmora aqui, mas nao\vesta em casa\vagora.\fEle deve estar na\nCASA DA ALMA.",
  ["5d:437e"] = "LAVANDA é uma\ncidade pequena e\vcalma que fica\vnas bases das\vmontanhas.\fEla esta um pouco\nmais agitada\vdesde quando a\vTORRE DE RADIO foi\vconstruida.",
  ["5d:445a"] = "O REPELENTE é\nnecessario se voce\vfor explorar uma\vcaverna.\fEmbora eu goste de\nexplorar, eu ainda\vnao fiz isso em\vtodas cavernas.",
  ["5d:44dd"] = "Eu ouvi falar de\num artesao que\vfaz POKé BOLAS sob\vencomenda na\vCI…… AZALEA em\vJOHTO.\fQueria ter uma.",
  ["5d:4586"] = "SENHOR FUJI: Bem\nvindo.\fHmm… Vejo que\nvoce treina\vseus POKéMONS\vde maneira \vgentil e amorosa.\fOs amantes de\nPOKéMONS vem aqui\vpara pagar devotos\vaos POKéMONS\vfalecidos.\fSeja simpatico\ncom as almas\vdos POKéMONS\vfalecidos.\fTenho certeza que\nisso vai deixa-los\vfelizes.",
  ["5d:4680"] = "Ha outras covas de\nPOKéMONS aqui, eu\vacho.\fHa varios\ncompartimentos que\vapenas o SENHOR\vFUJI pode entrar.",
  ["5d:46e4"] = "Eu vim com minha\nmae para visitar\vas covas dos\vPOKéMONS…",
  ["5d:470e"] = "Os POKéMONS que\nviveram comigo…\fEu os amei como os\nmeus netos…",
  ["5d:47f2"] = "Bem-vindo!\nSinta a vontade\vpara olhar tudo\vnesse andar.",
  ["5d:482d"] = "Desculpe-me, voce\nso pode visitar o\vandar térreo.\fDesde quando a\nTORRE DE RADIO DE\vJOHTO foi envadida\vpor uma gangue\vcriminosa, nos\vtemos tomado\vmedidas de\vseguranca.",
  ["5d:48c3"] = "Muitas pessoas\ntrabalham duro\vaqui na TORRE DE\vRADIO. \fEles dao o\nmelhor de si para\vtransmitirem\vprogramas de\vqualidade.",
  ["5d:492e"] = "Oh, nao, nao, nao!\fNos saimos do ar\ndesde quando a\vUSINA DE ENERGIA\vfoi desligada.\fTodos os meus\nesforcos para\vconstruir esta\vestacao poderiam\vter sidos em vao\vse eu nao fazer\vtransmissoes.\fEu vou ser\narruindado!",
  ["5d:49d4"] = "Ah! Entao voce é\n{PLAYER}, a pessoa\vque resolveu o\vproblema na USINA\vDE ENERGIA?\fGracas a voce, eu\nnao perdi o meu\vemprego.\fEu admito, voce é\num verdadeiro\vsalva-vidas!\fLeve isso\ncomo forma de\vagradecimento.",
  ["5d:4a74"] = "Com essa coisa,\nvoce pode\vsintonizar em\vprogramas que vem\vde KANTO.\fHahahaha!",
  ["5d:4ac6"] = "Como vai, colega!\fEu sou o\nsuper DIRETOR DE\vM→SICAS!\fHa? Sua POKéGEAR\nnao pode\vsintonizar em\vminhas musicas?\vQue tristeza!   \fSe voce adquirir\na atualizacao do\vCARTAO EXPANSOR,\vvoce podera\vsintonizar em\vnossa programacao.\fE melhor voce\nadquirir um!",
  ["5d:4b83"] = "Ola colega!\fEu sou o super\nDIRETOR DE M→SICA!\fEu sou responsavel\npelas belas\vmelodias que vao\vao ar.\fNao seja quadrado.\nLargue as musicas\vque ficam fora do\var!",
  ["5d:4d5c"] = "Voce ja foi a\nCI…… LAVANDA?\fHa uma grande\nTORRE DE RADIO la.",
  ["5d:4e72"] = "Sim, sim. Como\neu imaginei.\fEi, fa da pesca!\fLeve esta--SUPER\nVARA!",
  ["5d:4ebf"] = "Tente pescar em\nqualquer lugar\vque tenha agua.\fLembre-se--voce\npode capturar\vdiferentes\vPOKéMONS usando\vdiferentes VARAS.",
  ["5d:4f2f"] = "Ha? Meus proprios\nolhos estao me\venganando?",
  ["5d:4ff8"] = "Estou chocado!\nUm menino da sua\vidade, com cabelo\vgrande entrou\vaqui em casa.\fEle me assustou e\ntentou fazer eu\vdar o meu POKéMON.\fEu fugi, mas\ne se ele voltar\vpara tentar\vpega-lo?\fVoce é forte.\nVoce pode cuidar\vdo meu POKéMON\vpor enquanto?",
  ["5d:50e2"] = "Oh, obrigado!\nCuide bem dele,\vpor favor!",
  ["5d:5110"] = "{PLAYER}\nrecebeu o \vPOKéMON.",
  ["5d:5124"] = "A sua equipe esta\ncheia.",
  ["5d:513e"] = "Oh, nao…\nO que vou fazer\vagora?",
  ["5d:5165"] = "Oi! Como vai meu\nPOKéMON?\fAcho que ele esta\nseguro agora,\ventao eu poderia\vte-lo de volta?",
  ["5d:51a6"] = "Obrigado!",
  ["5d:51b2"] = "Ei, voce nao esta\ncom o meu POKéMON.",
  ["5d:51d8"] = "Meu POKéMON gostou\nde voce.\fCerto, voce deve\nficar com ele.\fMas me prometa\nque sera bom com\vele!",
  ["5d:5234"] = "Oh, nao… E o\nmesmo de ter sido\vroubado.",
  ["5d:5261"] = "Para o POKéMON,\nfelicidade é estar\vcom a pessoa que\vo trata bem.",
  ["5d:53ee"] = "HAHAHAH!\fEntao veio de\nlonge.\fDeixe-me avisar,\nsou forte!\fMeu POKéMON\nesmagara pedras\ve quebrara seus\vossos!\fVeja so\nisto!",
  ["5d:547f"] = "Ja se assustou\nseu pivete?\fO que?\nNao tem nada a ver\vcom POKéMONS?\fE verdade!\fVamos.\nNos devemos\vbatalhar!",
  ["5d:54eb"] = "O que? Ha?\nperdi?\fBom, voce ganhou\na INSIGNIA da\vTEMPESTADE!",
  ["5d:552a"] = "{PLAYER} foi\npresenteado com\vuma INSIGNIA DA\vTEMPESTADE do\vGINASIO da CI……\vCIANWOOD.",
  ["5d:5542"] = "A INSIGNIA DA\nTEMPESTADE faz\vPOKéMONS até o\vNIVEL 70 lhe\vobedecerem!\fE também permite\nseu POKéMON usar a\vtécnica VOAR fora\vde batalhas\vPOKéMON.\fEi, leve isso\naqui.",
  ["5d:55cf"] = "Isto é SOCO\nDINAMICO.\fNao atinge sempre,\nmas quando\vatinge causa uma\vconfusao!",
  ["5d:5625"] = "HAHAHAH! Eu\napreciei nossa\vluta!\fMas a perda foi\nruim!\fA partir de agora,\ntreinarei 24 horas\vpor dia.",
  ["5d:58dd"] = "Voce encontrou o\nPOKéMANIACO?\fEle vive falando\nsobre seus\vPOKéMONS raros.",
  ["5d:5a2a"] = "{PLAYER}! Voce\nvenceu!\fEstava torcendo\npor voce!",
  ["5d:5ac6"] = "Seu POKéMON\nparece estar bem.\fMas tem algo\npreocupando voce?\fO POKéMON do\nFAROL esta com\vproblemas?\fPegue isto, ele\ndeve dar um jeito\vno POKéMON.",
  ["5d:5b52"] = "{PLAYER} recebeu\nPO'sAO SECRETA.",
  ["5d:5b6c"] = "Minha PO'sAO\nSECRETA é muito\vforte.\fEu so ofereco em\ncasos de urgencia.",
  ["5d:5bf5"] = "Voce tem um\nPOKéMON magnifico\vcom voce. \fQue tal uma foto\nde lembranca?",
  ["5d:5c3e"] = "Certo! De um\ngrande sorriso\vagora!",
  ["5d:5c52"] = "Oh, isto é muito\nruim. Eu achei\vque ia dar tudo\vcerto!…",
  ["5d:5cb5"] = "Voce veio de\nOLIVINE?\fSe lembra das\nquatro ilhas ao\vlongo do caminho?\fEu ouvi dizer que\numa criatura\vmistica vive\vnestas ilhas.",
  ["5d:5d3b"] = "Eu soube que voce\nso podera ve-lo\vse tiver a ASA\vPRATEADA.\fEla e essa\ncriatura devem ter\vo mesmo cheiro.",
  ["5d:5da5"] = "Os redemoinhos em\ntorno da ilha sao\vcausados por uma\vcriatura do mar.",
  ["5e:4057"] = "Esta loja faz\nparte do mesmo\vDEPARTAMENTO la da\vCI…… GOLDENROD.\n    \fElas sao ambos\nrenovados ao mesmo\vtempo.",
  ["5e:40cb"] = "E minha primeira\nvez aqui.\fE tao grande.\nTenho medo de\vsubir.",
  ["5e:41ea"] = "Me tornei\ntreinador\vrecentemente.  \fFoi meu filho quem\nme ajudou.\fEstou admirado\ncom esta selecao\vde produtos.",
  ["5e:4262"] = "Meu pai esta tendo\ntrabalho para\vdecorar o nome dos\vitems e como\veles devem ser\vusados…",
  ["5e:4377"] = "Nao consigo\nme decidir em qual\vPOKéMON devo por\veste TM…",
  ["5e:43aa"] = "Opa!\nEu negociei o meu\vPOKéMON sem\vretirar a minha\vATUALIZA'sAO dele.",
  ["5e:43eb"] = "Isso! Finalmente\nconsegui um\vPORYGON.\fEu sou ruim nas\nmaquinas, nunca\vconseguiria muitas\vmoedas…\f…Ha?\fO PORYGON trocado\nevoluiu em um \vPOKéMON diferente.",
  ["5e:4485"] = "A LOJA de TM\nvende golpes\vraros.",
  ["5e:4542"] = "Vim comprar a\nCARTA SURFE para\va minha namorada.",
  ["5e:4579"] = "Este é o unico\nlugar onde voce\vencontra a CARTA\vAMOR.",
  ["5e:4644"] = "Quero comprar\nartigos que elevam\vo estado do\vPOKéMON, mas nao\vtenho tanto\vdinheiro…",
  ["5e:4696"] = "Quero PP MAIS,\npara elevar o PP\vdos golpes.\fMas nao posso\ncomprar.",
  ["5e:46da"] = "Os POKéMONS ficam\nfelizes se voce\vusar itens neles.\fEles odeiam alguns\nitens.",
  ["5e:486c"] = "Uma maquina de\nvenda.\fOlha o menu.",
  ["5e:4890"] = "Click!\f{STRBUF}\nsaiu.",
  ["5e:48aa"] = "Opa, dinheiro\ninsuficiente.",
  ["5e:48c3"] = "Nao tem mais\nespaco para\visto…",
  ["5e:48e3"] = "Uma maquina de\nvendas com uma\vroleta de premios.\fNunca verei uma\nigual.",
  ["5e:492c"] = "Ahh! Nao ha jogos\naqui!\fEu queria jogar…",
  ["5e:4a2f"] = "Os meus POKéMONS\nme fazem companhia\vpor isto nao fico\vso.\fO MEOWTH até me\ntraz dinheiro.",
  ["5e:4b52"] = "PC de {PLAYER}\nfoi ligado.\f…\fAlguém estava\ntentando passar um\vnovo e-mail.\fEspero que venha\nme visitar em\vKANTO.\fAcho que voce\nficara surpreso,\vcom as mudancas\vque ocorreram\vaqui.\fVoce vera alguns\nPOKéMONS que nao\vexistem em JOHTO.\fPara o PRODUTOR\f…",
  ["5e:4c48"] = "GAME FREAK\nSALA DE ENCONTROS.",
  ["5e:4cea"] = "Esta certo!\nEu sou o\vDESENHISTA do\vJOGO!\fCompletar sua\nPOKéDEX é duro,\vmas nao desista!",
  ["5e:4d41"] = "Uau! Excelente!\nVoce completou sua\vPOKéDEX!\fMeus Parabens!",
  ["5e:4d7f"] = "O ARTISTA GRAFICO\nvai imprimir um\vDIPLOMA para voce.\fVoce deve lhe\nmostrar isto.",
  ["5e:4dd0"] = "Sou o ARTISTA\nGRAFICO.\fEu fiz  oce!",
  ["5e:4df4"] = "Sou o ARTISTA\nGRAFICO.\fOh, voce completou\nsua POKéDEX?\fQuer que eu\nimprima o seu\vDIPLOMA?",
  ["5e:4e4c"] = "De-me um grito se\nquiser a impressao\vdo DIPLOMA.",
  ["5e:4ee6"] = "As GEMEAS nao sao\nlegais?\fJASMINE também é!\nOh, Eu os\vadoro!",
  ["5e:4f27"] = "GAME FREAK\nSALA DE PRODU'sAO.",
  ["5e:4f44"] = "E um desenho\ndetalhado de uma\vmenina.",
  ["5e:4f6e"] = "E o programa do\njogo.\fSe usar errado,\npode causar erros\vno jogo!",
  ["5e:4fb2"] = "Existem materiais\nsobre eles.    \fExiste até uns\nBONECOS POKéMON.",
  ["5e:50ad"] = "Deixe-me contar\nalgo assustador…",
  ["5e:50d0"] = "Nao sera\ntao assustador\venquanto haver luz\vsolar la fora.\fVolte apos o\npor-do-sol, ta?",
  ["5e:5129"] = "Era uma vez, um\ngaroto que ainda\vpequeno recebeu\vuma BICICLETA\vNOVA…\fEle tentou andar\nnela na mesma\vhora…\fEle se divertia\ntanto que nem viu\vo sol se por…   \fEnquanto voltava\na sua casa no\vmeio da noite, a\vBICICLETA diminuia\vde velocidade.\fOs pedais ficaram\nduros!\fQuando ele parou\nde pedalar, a\vBICICLETA foi\vpuxada para tras.\fEra como\nse estivesse\vamaldicoada e\vtentasse leva-lo\va algum lugar!\f…\n…KABUMMM!\fO menino havia\nvoltado para a\vPISTA DE CICLISMO!\f…Ba-dum ba-dum!\fPor ter ouvido\na minha historia,\vleve este TM03.",
  ["5e:5339"] = "O TM03 é a\nMALDI'sAO.\fE um golpe que\napavora a vitima\ve a faz perder PS\vlentamente.",
  ["5e:53b4"] = "ERIKA é a mestra\nde POKéMONS grama.\fEla lhe fara pagar\nse nao agir\voriginalmente!",
  ["5e:553f"] = "{PLAYER}o",
  ["5e:5571"] = "Bem-vindo!\fVoce pode trocar\nmoedas por premios\vna casa ali ao\vlado.",
  ["5e:55b6"] = "Estas maquinas sao\ngrandes obras de\vartes.",
  ["5e:55e3"] = "Eu quero esta\nmaquina.\fMe limpou\ntotalmente ontem,\ventao devia me\vpagar hoje.",
  ["5e:5636"] = "Acho que esta\nmaquina ainda me\vpagara…\fAs chances variam\nentre elas.",
  ["5e:567d"] = "Hahahaha!\fAs moedas\ncontinuam caindo!\fHum?\nO que menino?\vVoce quer jogar?\fVou compartilhar\nminha sorte!",
  ["5e:56e6"] = "Hahahaha!\fMe sinto bem\nquando eu ajudo\vos meus varios\vcolegas!",
  ["5e:572b"] = "Ei, voce nao tem\numa BOLSA de\vMOEDAS!\fComo eu poderei\nlhe dar umas\vmoedas?",
  ["5e:577a"] = "Ei, sua BOLSA\nde MOEDAS, esta\vcheia.\fVoce deve estar\ntramando algo,\vnao é?",
  ["5e:57c6"] = "Ei! Ganhar\nfaz bem!\fVoce esta jogando\naqui também?\fEstou tentando\nconseguir moedas\vpara ganhar\vpremios.\fMas nao tenho\nmuitas moedas…",
  ["5e:584e"] = "Hum… Eu tenho\nmais chances de\vter um PIKACHU\vdo que…\fO que eu\vfaco?",
  ["5e:5c59"] = "Eu queria um\nMR.MIME, mas so\vtinha 100 moedas…",
  ["5e:5c8a"] = "Bem…\nPreciso ficar\vcalmo e alegre…\fNao posso perder\na calma senao\vperderei dinheiro…",
  ["5e:6051"] = "ERIKA: Foi uma\npartida deliciosa.\fMe senti\ninspirada.\fPor favor, fique\ncom este meu TM.\fE o GIGA DRENO.\fE um golpe\nmaravilhoso, que\vdrena metade do\vdano infligido no\vPOKéMON inimigo.\fPor favor, use\neste TM se voce\vprecisar.",
  ["5e:6130"] = "ERIKA: Perder\ndeixa um gosto\vruim…\fMas saber\nque existem\vtreinadores\vfortes, me da\vinspiracao para\vtreinar.",
  ["5e:61cd"] = "Nao é que nao\ngostamos de\vgarotos.\fMas existem certos\nassuntos que so\vgarotas devem\vconversar.",
  ["5e:634c"] = "ERIKA vai lhe dar\numa licao!",
  ["5e:639c"] = "ERIKA é muito\nmais forte!",
  ["5e:64ba"] = "Oi!\fNos estamos\nrealizando uma\vcompeticao.\fNao podemos lhe\nservir agora.",
  ["5e:6505"] = "Nhac…\nGlup…",
  ["5e:6516"] = "Nao fale\ncomigo!\fVoce quebrou a\nconcentracao!",
  ["5e:6546"] = "Glup…\nGlup…",
  ["5e:6554"] = "Quero quantidade\nacima de\vqualidade.\fEstou\ninchado!",
  ["5e:658a"] = "Nhac…\nNhac…",
  ["5e:6599"] = "A comida é boa\naqui, mas\vGOLDENROD tem a \vmelhor comida do\vmundo.",
  ["5e:65dd"] = "Nhac…\nNhac…",
  ["5e:65ee"] = "Ninguém lhe dara\numa BOLSA de\vMOEDA.\fVa procurar la\nem JOHTO.",
  ["5e:6630"] = "Nhac…\nNhac…   \fAinda posso\ncomer!",
  ["5e:6654"] = "Manda mais!",
  ["5e:6754"] = "Se voce cruzar a\nESTRADA de\vCICLISMO, voce ira\va CI…… FUCHSIA.",
  ["5e:67e6"] = "A PISTA DE CICLISMO\ncomeca aqui.  \fE tudo em declive.\nEntao é bem\vanimado.\fE um otimo\ndivertimento que\vnao se sente nem\vem navio nem em\vtrem.",
  ["5e:6874"] = "Ei! Voce! Pare!\fNao pode entrar\nna ESTRADA DE\vCICLISMO sem\vBICICLETA.",
  ["5e:690a"] = "Voce ja soube do\nacidente na USINA\vDE ENERGIA?\fEle fica a Leste,\nperto da CI……\vLAVANDA.",
  ["5e:6970"] = "Eu levo meu\ntrabalho de GUARDA\va sério.\fEi! Voce tem uma\nPOKéDEX.\fCerto. Voce pode\npassar.",
  ["5e:6a0a"] = "ESTRADA DE\nCICLISMO.\fSiga reto.",
  ["5e:6a2b"] = "Agarre-se! Voce\nnao tem BICICLETA?\fA ESTRADA DE\nCICLISMO.\fE aqui fora.\fVoce tem que ter\vuma BICICLETA.",
  ["5f:4057"] = "GARY: Finalmente\nchegou aqui.\fNao estava com\nanino em CINNABAR,\vmas agora eu quero\vbatalhar.     \f…\fVoce esta me\ndizendo que\vconseguiu todas\vINSIGNIAS de\vJOHTO?\fOs GINASIOS de\nJOHTO devem ser\vruins.  \fNao se preocupe\ncom isto.\fEu saberei se voce\né bom ou nao se\vlutarmos agora.\fPronto, menino de\nJOHTO?",
  ["5f:4188"] = "GARY: O que?\fComo? Droga!\nPerdi para voce?\f…\fHum, esta bem…\fEi, leve isto,\né a INSIGNIA DA\vTERRA.",
  ["5f:4201"] = "GARY: Certo, eu\nestava errado.\vVoce é sincero.\fVoce é um otimo\ntreinador.\fMas um dia eu\nderrotarei voce. \fNao se esqueca\ndisto!",
  ["5f:4285"] = "GARY: Escute.\fE melhor nao\nperder até que eu\vlhe venca.\fEntendeu?",
  ["5f:437a"] = "Cara, voce é mesmo\ndurao…\fEssa foi uma\nbatalha inspira-\vdora.\fEla trouxe\nlagrimas aos meus\volhos.",
  ["5f:442e"] = "Voce pensa muito\nantes de nomear\vos seus POKéMONS?\fDando a eles bons\napelidos, aumenta\va diversao de\vtodos os outros.",
  ["5f:44a5"] = "O nome SPEARY é\ndo SPEAROW--e o\vRATTEY do RATTATA.",
  ["5f:4559"] = "Bem-vindo a\nCASA DE TREINO,\vo mais novo centro\vde atividades de\vVERIDIANA.\fEstamos abertos\na treinadores.\fVoce pode lutar\ncom o melhor dos\vmelhores no andar\vabaixo.",
  ["5f:45ff"] = "VERIDIANA é a\ncidade mais\vproxima do\vPLANALTO INDIGO.\fConstruiram este\nlocal porque\vmuitos treinadores\vvem aqui para\vir ao PLANALTO\vINDIGO.",
  ["5f:468f"] = "Eles realizam\nbatalhas no andar\vde baixo.\fEu adoraria ver o\nquanto é bom um\vtreinador la de\vJOHTO.",
  ["5f:46f7"] = "Acho que voce nao\nse torna um\vCAMPEAO a menos\vque va a todos os\vlugares e enfrente\vtodos os tipos de\vpessoas.\fO CAMPEAO de\nPALLET viajou por\vtodas as cidades\vde KANTO.",
  ["5f:47a3"] = "Bem…\nEstou tirando um\vdescanso de\vbatalhas.",
  ["5f:49fa"] = "Oi. Bem-vindo ao\nSAGUAO DE\vTREINAMENTO.\fSo pode batalhar\num vez ao dia.",
  ["5f:4a44"] = "{STRBUF} sera o\nseu oponente.",
  ["5f:4a61"] = "Voce quer batalhar\nagora?",
  ["5f:4a7c"] = "Por favor, va a\ndireita.\fVoce ja\npode comecar.",
  ["5f:4ab0"] = "Desculpe.\nSo trenadores que\vbatalharao hoje\vpodem entrar neste\vlocal.",
  ["5f:4af7"] = "Desculpe, senhor.\fSeria sua segunda\nvez hoje.\fSo é permitido\nvoce neste local\vuma vez por dia.",
  ["5f:4b57"] = "Perdi…\nDroga…",
  ["5f:4b66"] = "Vim de fora\npara aqui.\fSo assim poderia\nlutar.",
  ["5f:4bf9"] = "Voce tem ido a\nCINNABAR?\fE uma ilha que\nfica ao sul daqui.",
  ["5f:4da7"] = "Meu sonho, é\nser um LIDER DE\vGINASIO.",
  ["5f:4e44"] = "Oi! Uau, estou\ncontente por te\vver.\fVoce é a primeira\nvisita em muito\vtempo.\fEstou super-feliz.\fDeixe-me lhe dar\num presente.",
  ["5f:4ec4"] = "Isto é uma PEPITA.\fNao posso te dar\npepitas do saber,\vvoce tera que\vfaze-las.",
  ["5f:5008"] = "So os treinadores\nque provaram seus\vvalores podem\vpassar.",
  ["5f:5093"] = "Oh! As oito\nINSIGNIAS DE\vJOHTO!\fPor favor, siga\nem frente, senhor!",
  ["60:43f7"] = "ELM: {PLAYER}!\nAi esta voce! \fPreciso te pedir\num favor.\fEu tenho um\nconhecido chamado\vSENHOR POKéMON.\fEle fica achando\ncoisas estranhas,\vdelirando com as\vdescobertas! \fDe qualquer modo,\neu recebi um\ve-mail dele\vdizendo que dessa\vvez era verdade.\fIsto é incrivel,\nmas estamos\vocupados com uma\vpesquisa POKéMON.\fVoce poderia\nchecar isto para\vnos?\fEu lhe darei um\nPOKéMON, amigo. \fSao todos POKéMONS\nraros que\vencontramos. \fVai!\nEscolha um!",
  ["60:4590"] = "Se um POKéMON\naparecer, deixe\vseu POKéMON\vbatalhar!",
  ["60:45c2"] = "ELM: Espere!\nOnde voce vai?",
  ["60:45e3"] = "ELM: Voce quer o\nCYNDAQUIL,\vPOKéMON fogo?",
  ["60:460e"] = "ELM: Voce quer o\nTOTODILE,\vPOKéMON agua?",
  ["60:463a"] = "ELM: Voce quer a\nCHIKORITA,\vPOKéMON grama?",
  ["60:4668"] = "ELM: Pense\ncuidadosamente!   \fSeu POKéMON\né necessario.",
  ["60:46a2"] = "ELM: Acho que ele\né um otimo \vPOKéMON!",
  ["60:46c8"] = "{PLAYER} recebeu\n{STRBUF}!",
  ["60:46db"] = "O SENHOR POKéMON\nvive perto da\vCI…… CEREJEIRA.\fTem uma rota que\nvai a casa dele!",
  ["60:472f"] = "Se seu POKéMON\nse ferir, voce\vpode cura-lo\vnaquela maquina.",
  ["60:476c"] = "Ah, aqui esta meu\nnumero.\fMe ligue se\ndescobrir algo\vnovo.",
  ["60:47a9"] = "{PLAYER} pegou o\nnumero do ELM.",
  ["60:47c3"] = "O SENHOR POKéMON\nviaja muito e\vencontra coisas\vraras, porém elas\vnao tem muita\vimportancia.      \f{PLAYER}, tenha\nboa sorte!",
  ["60:4835"] = "Contém um POKéMON\npego pelo\vPROFESSOR ELM.",
  ["60:4883"] = "ELM: {PLAYER}, isso\né terrivel… \fAh, sim, qual\nfoi a grande\vdescoberta?",
  ["60:48c8"] = "{PLAYER} deu o\nOVO ESTRANHO ao\vPROFESSOR ELM.",
  ["60:48ef"] = "ELM: Isto?",
  ["60:48fb"] = "Mas… E um OVO\nPOKéMON?\fSe for, sera uma\ngrande descoberta!",
  ["60:4af2"] = "ELM: Tenha calma!\nEu te ligo se\vdescobrir algo\vsobre este OVO.",
  ["60:4b33"] = "ELM: {PLAYER}?\nVoce nao achou meu\vassistente?\fEle devia ter lhe\nencontrado com o\vOVO no CENTRO\vPOKéMON de\vVIOLETA.\fVoces devem ter se\ndesencontrado.\fTente encontra-lo.",
  ["60:4bf6"] = "{PLAYER}? Achei\nque o OVO havia\vchocado.\fOnde esta\no POKéMON?",
  ["60:4c28"] = "ELM: {PLAYER}, esta\notimo!",
  ["60:4c41"] = "O que?\nAquele POKéMON!",
  ["60:4c55"] = "O OVO ja chocou!\nEntao POKéMONS\vnascem de OVOS…\fTem razao, talvez\nnem todos\vPOKéMONS. \fUau, existem\nmuitas pesquisas\va serem feitas.",
  ["60:4cd2"] = "Obrigado, {PLAYER}!\nVoce esta\vnos ajudando\va resolver\vmistérios!\fPegue isto em\nforma do nosso\vagradecimento a\vvoce!",
  ["60:4d43"] = "Isto é a\nPEDRAETERNA.\fAlguns POKéMONS\nevoluem quando\vchegam a um\vdeterminado nivel.\fO POKéMON que\nestiver com a\vPEDRAETERNA nao\vevolui.\fDe isto ao\nPOKéMON se voce\vnao o quiser\vevoluido.",
  ["60:4ded"] = "ELM: {PLAYER}, eu\nte chamarei se\valgo ocorrer,\vcerto?",
  ["60:4e1b"] = "…Buuaaa…\nAquele POKéMON\vroubado.\fQueria saber o que\nele esta fazendo\vagora.\fDizem que POKéMONS\nroubados por\vpessoas mas,\vacabam ficando\vmaus também.",
  ["60:4e86"] = "Ola, {PLAYER}.\nGracas a voce,\vminha pesquisa\vesta ficando\votima!\fLeve isso como\nrecompensa!",
  ["60:4ee7"] = "A MASTER BOLA é\na melhor!\fE a BOLA defini-\ntiva! Ela captura\vqualquer POKéMON\vsem falhar.\fEla é dada apenas\naos reconhecidos\vpesquisadores\vPOKéMON.\fEu acho que voce\npode fazer melhor\vuso dela que eu,\v{PLAYER}!",
  ["60:4fa4"] = "ELM: {PLAYER}! Ai\nesta voce!\fEu te chamei\nporque eu tenho\valgo para voce.\fViu? E uma\nPASSAGEM de navio.\fAgora voce pode\ncapturar POKéMONS\vem KANTO.",
  ["60:5020"] = "O navio parte da\nCI…… OLIVINE.\fMas voce ja sabe\ndisso, {PLAYER}.\fDepois de tudo,\nvoce ja viajou o\vtempo todo com o\vseu POKéMON.\fCumprimente por\nmim o PROFESSOR\vCARVALHO em KANTO!",
  ["60:50e9"] = "{PLAYER}, eu quero\nque voce leve isto\vcom voce.",
  ["60:5116"] = "Agora, so me resta\nlhe desejar uma\vboa aventura.",
  ["60:5146"] = "Nos ouvimos\num barulho fora\vdaqui…\fQuando saimos do\nLABORATORIO,\valguém roubou um\vPOKéMON.\fEu nao acredito\nque alguém fez\visto!\f… Poxa… Um POKéMON\nfoi roubado.\fEu queria saber\nquem fez isto.\fAcho que este\nPOKéMON ficara mal\vcom o seu novo\vtreinador!",
  ["60:5229"] = "{PLAYER}!\fUse isso para\najudar sua jornada\vda POKéDEX.",
  ["60:524b"] = "Para preencher a\nsua POKéDEX, voce\vdeve capturar\vPOKéMONS.\fUse isso para\ncapturar POKéMONS\vselvagens.",
  ["60:52a1"] = "Ouvi dizer que\num POKéMON foi\vroubado…\fEstou colhendo\ninformacoes com o\vPROFESSOR ELM.\fAparentemente,\nfoi um garoto\vforte, com cabelo\vvermelho.\fO que?\fVoce batalhou\ncontra este\vgaroto?\fVoce sabe qual\né o nome dele?",
  ["60:5719"] = "Ah, {PLAYER}…!\nNosso vizinho\vPROFESSOR ELM,\vprocura por voce!\fEle quer que voce\npegue uma coisa\vcom ele.\fAh! Quase me\nesqueci!\fSua agenda ja\nchegou da loja\vde reparos.\fEsta bem aqui!",
  ["60:57d2"] = "POKéMON GEAR ou\nPOKéGEAR!\fE essencial se\nvoce quer ser\vum bom treinador!\fA proposito, sabe\nque dia da\vsemana é hoje,\vmeu filho?",
  ["60:5857"] = "Nos estamos no\nHORARIO DE VERAO?",
  ["60:5878"] = "Venha para casa\npara ajustar seu\vrelogio para o\vHORARIO DE VERAO!\fA proposito, voce\nsabe como usar\vo seu CELULAR?",
  ["60:58e0"] = "Voce so vera o\nicone do CELULAR\vse acessar a sua\vPOKéGEAR!",
  ["60:591c"] = "Entao eu vou te\nexplicar.\fAcesse a POKéGEAR\ne entre no icone\vdo CELULAR.",
  ["60:5965"] = "Os numeros ficarao\nguardados na\vmemoria dele.\fE so escolher o\nnome da pessoa!\fIsso nao é\nsimples?",
  ["60:59ca"] = "PROFESSOR ELM\nesta te esperando.\fRapido, meu filho!",
  ["60:59fa"] = "Ah, qual era\no recado do\vPROFESSOR ELM?\f……\fMas isto é um\ngrande desafio.\fVoce deve estar\nfeliz pois ganhou\vum POKéMON lindo.",
  ["60:5a6c"] = "{PLAYER}, pode ir!\fEstarei sempre\ncom voce!",
  ["60:5d64"] = "PIKACHU é um\nPOKéMON evoluido.\fFoi o PROFESSOR\nELM quem\vdescobriu isto!\fEle é famoso\npelas pesquisas\vsobre a evolucao\vPOKéMON. \f…hum… \fEu poderia ser\numa pesquisadora\vtambém…",
  ["60:5eb5"] = "Oi, {PLAYER}! Meu\nmarido esta\vsempre ocupado.\vEu gosto de\vajuda-lo.\fQuando ele comeca\numa pesquisa, ele\vesquece de comer!",
  ["60:5f2c"] = "Quando eu crescer,\neu vou ajudar\vmeu pai!\fEu vou ser um\ngrande professor\vPOKéMON!",
  ["60:6108"] = "Seus POKéMONS\nparecem bem\vcansados.\fVoce deve\ndescansa-los.",
  ["60:6149"] = "Ah! Os seus\nPOKéMONS parecem\votimos!\fContinue assim!",
  ["60:61b7"] = "Ha algo escrito\naqui? Quer ler?",
  ["60:61e0"] = "Aos meus irmaos\ne irmas:\fNos temos\norgulho em servir\vos treinadores\vPOKéMON.\fQuando eles\nfalarem com voces,\vde algo util a\veles.\fCom amor, M'lNICA.\fContinuar lendo?",
  ["60:6277"] = "Segunda, M'lNICA\nROTA 40.\fTerca, TUSCANY\nROTA 29.\fQuarta, WESLEY\nLAGO DA RAIVA.\fQuinta, ARTHUR,\nROTA 36.\fSexta, FRIEDA,\nROTA 32\fSabado, SANTOS,\nVILA BLACKTHORN\fDomingo, SUNNY,\nROTA 37.",
  ["60:6381"] = "Onde voce esta\nindo com seus\vPOKéMONS?\fLIGA POKéMON?\fOs seus POKéMONS\nsao bem leais para\vvoce vencer?\fDeixe-me ver…",
  ["60:63e9"] = "Ah! Seu POKéMON\nconfia muito em\vvoce.\fE otimo ver um\nbom treinador.\fEi. Um presente\npara a sua\vjornada.",
  ["60:644d"] = "O TM 37 é a\nTEMPESTADE.\fE um golpe que\ncausa em danos em\vambos lutadores.\fE so para\ntreinadores\vavancados.\fUse isso se\nquiser. Boa sorte!",
  ["60:64dd"] = "Se ele nao confiar\nmais em voce, ele\vpoderia se tornar\vviolento.\fA confianca é o\nlaco que une\vtreinadores aos\vPOKéMONS.",
  ["60:657f"] = "Voce nao pode\nsubir margens.\fMas pode salta-las\npara pegar um\vatalho!",
  ["60:65cb"] = "Diferentes\nespécies de\vPOKéMON aparecem\vaqui.\fSe quiser pegar\ntodos, voce deve\vprocurar em todo\vlugar.",
  ["61:400d"] = "Ola! O REI CARATE,\no mestre do\vGINASIO DE LUTA,\vesta em uma\vcarverna em JOHTO\vpara treinar.",
  ["61:4180"] = "SABRINA: Eu sabia\nque voce viria…\fHa tres anos\natras, eu previ\vo momento que\vchegaria.\fVoce quer minha\nINSIGNIA.\fNao gosto muito de\nbatalhar, mas é\vmeu dever de LIDER\vconceder INSIGNIAS\va quem provar a si\vmesmo o seu valor.\fComo voce quer, eu\nte mostrarei meus\vpoderes psiquicos!",
  ["61:4295"] = "SABRINA: Seu\npoder…   \fUltrapassa muito\no que eu previ…\fTalvez seja\nimpossivel prever\vo que o futuro\voferecera…\fCerto, voce\nvenceu, voce\vmerece a INSIGNIA\vDA LAMA.",
  ["61:434e"] = "SABRINA: A\nINSIGNIA DA\vLAMA extrai\vseus poderes\vadormecidos…\fPorém, eu falhei\nna precisao ao\vprever os seus\vpoderes, esta é a\vverdade.\fVoce se tornara\num celebrado e\vidolatrado CAMPEAO\vPOKéMON.",
  ["61:440d"] = "SABRINA: Seu amor\npelos seus\vPOKéMONS oprimiram\vos meus poderes\vpsiquicos…\fO poder do amor,\neu acho, é também\vum tipo de poder\vpsiquico…",
  ["61:46a2"] = "Voce, CAMPEAO em\nprogresso!\fUm treinador\nhabilidoso como\vvoce nao deve ser\vavisado de\vcomo batalhar\vcom POKéMONS\vpsiquicos, certo?\fEu espero boas\ncoisas de voce!\fBoa sorte!",
  ["61:4741"] = "Essa foi outra\nbatalha incrivel!",
  ["61:486d"] = "Existe uma grande\nTORRE DE RADIO em\vLAVANDA.",
  ["61:4894"] = "Eu quero me tornar\nmais forte, mas eu\vnao sou muito boa\vainda…\fVoce poderia me\nmostrar alguma\vcoisa?",
  ["61:493b"] = "Ha uma grande\nUSINA DE ENERGIA\vao norte da\vCI…… LAVANDA.",
  ["61:496e"] = "Eu tinha acabado\nde atravessar o\vT→NEL DE PEDRA.\fHavia uma confusao\nna USINA DE\vENERGIA.",
  ["61:49c9"] = "As cavernas\nse destroem\vfacilmente.\fMuitas cavernas\ndesapareceram no\vpassado, como a\vque esta fora de\vCERULEANA.\fIsso é um\nconhecimento comum\vdos ANDARILHOS\vexperientes.",
  ["61:4b30"] = "…\f…\f…\f…Eu tenho isso!\fVoce quer isso!",
  ["61:4c45"] = "Desculpe-me, mas\no TREM MAGNETO nao\vesta funcionando\vainda.",
  ["61:4c79"] = "Em breve, nos\npartiremos para\vGOLDENROD.\fVoce deseja\nembarcar?",
  ["61:4cb3"] = "Eu posso conferir\no seu PASSE?\fCerto, é por aqui\nsenhor.",
  ["61:4cef"] = "Desculpe-me, mas\nvoce nao tem o\vPASSE do TREM\vMAGNETO.",
  ["61:4d11"] = "Nos esperamos\nve-lo novamente.",
  ["61:4d2c"] = "Nos chegamos em\nSAFFRON.\fNos esperamos\nve-lo novamente.",
  ["61:4d63"] = "O TREM MAGNETO\né um veiculo\vferroviario super\vmoderno que usa\veletricidade e\vimas para alcancar\vuma velocidade\vincrivel.\fPorém, se\nnao tiver\veletricidade…",
  ["61:4dfa"] = "Uau…\fQuantas vezes\neu ja devo ter\vviajado entre os\vcontinentes KANTO\ve JOHTO?",
  ["61:4e44"] = "Antes da ESTA'sAO\ndo TREM MAGNETO\vfor construida,\vexistia uma casa\vaqui.\fUma garotinha\nchamada DUPLICA\vmorava aqui.",
  ["61:4eb9"] = "Ola. Voce tem um\nPASSE de TREM?\vEu tenho um. Todas\vas pessoas em\vSAFFRON que usam\vo TREM MAGNETO\vpossuem PASSES.",
  ["61:4f9c"] = "Bem-vindo.\fEsse é o PREDIO\nPRINCIPAL DA\vCORPOPA'sAO SILPH.",
  ["61:4fcf"] = "Apenas os\nempregados podem\vir ao andar de\vcima.    \fMas como voce veio\nde um longo\vcaminho, eu vou te\vdar essa pequena\ve nitida\vlembranca.",
  ["61:5041"] = "E o produto mais\nrecente da\vCORPORA'sAO SILPH.\fEle nao se\nencontra a venda\vainda.",
  ["61:50cd"] = "Minha filha gosta\nde imitar pessoas.\fEssa técnica a fez\nficar conhecida\vpor aqui como\vDUPLICA.",
  ["61:512e"] = "Minha filha é tao\negoista…\fEla possui muito\npoucos amigos.",
  ["61:516c"] = "Ela recentemente\nperdeu uma BONECA\vque um garoto lhe\vdeu a tres anos\vatras.\fDesde la, ele vem\nmelhorado suas\vmimicas…",
  ["61:52f1"] = "{PLAYER}: Oi! Voce\ngosta de POKéMONS?\f{PLAYER}: Uh, nao,\neu so te\vperguntei.\f{PLAYER}, nao é?\nVoce é estranho!",
  ["61:533f"] = "DUPLICA: Hmm?\nParar de imitar?\vMas é o que eu\vadoro fazer!",
  ["61:542d"] = "DUPLICA: Como\ndisse?\fNao devo decidir\no que voce deve\vfazer?\fMas eu\nestou realmente\vpreocupada.\fSera que alguém\npoderia ter a\vgentileza de\vacha-la para mim?",
  ["61:5496"] = "Ei! Essa é a minha\nBONECA CLEFARY!\fEsta vendo\na rasgadura\vcosturada na perna\vdireita?\fEssa é a prova\nque a BONECA é\vminha!",
  ["61:54f9"] = "Certo. Aqui esta\no PASSE para o\vTREM MAGNETO como\veu prometi!",
  ["61:552b"] = "DUPLICA: Esse é\no PASSE para o\vTREM MAGNETO.\fO rapaz da empresa\nde trens me\vdeu quando eles\vdemoliram nossa\vvelha casa para\vconstruir a\vESTA'sAO.",
  ["61:55af"] = "{PLAYER}: Ola!\nMuito obrigado\vpelo PASSE do TREM\vMAGNETO!\f{PLAYER}: Como\ndisse?\f{PLAYER}: E tao\ndivertido assim\vimitar todos os\vmeus movimentos?",
  ["61:560c"] = "DUPLICA: Esta\ncerto!\fE arrepiante!",
  ["61:567b"] = "Isso é um POKéMON\nraro!\fHa? E apenas um\nboneco…",
  ["61:5702"] = "Muitas cidades\ndo continente\vJOHTO possuem\vlongas historias.\fEu amaria conhecer\numa delas!",
  ["61:5766"] = "Voce veio do\ncontinente JOHTO,\vnao é?\fO que esta\nachando de KANTO?\fE um continente\nmaravilhoso,\vconcorda comigo?",
  ["61:57fc"] = "Eeyaaaah!\fEu sinto uma\nsombra sinistra\vte encobrindo.\fLeve isto para se\nproteger!",
  ["61:5851"] = "Voce estava num\nperigo mortal,\vmas agora esta\vprotegido.",
  ["61:5888"] = "Minha avo esta\neliminando o que\vela acredita ser\vmaus espiritos.\fPerdao por ela\nassustar voce.",
  ["62:402c"] = "Poxa! Nao chegaram\nas POKé BOLAS.\fSera que vao\ndemorar a chegar?",
  ["62:406b"] = "Chegaram as POKé\nBOLAS!\fAgora posso\ncapturar POKéMONS!",
  ["62:4182"] = "Isso é otimo! Eu\nposso armazenar\vPOKéMONS e depois\vlibera-los!",
  ["62:41c0"] = "Os treinadores\nusam aquele PC de\vgraca.",
  ["62:41e9"] = "O CENTRO de\nCOMUNICA'sOES esta\vsendo construido.\fMas eles vao\ntermina-lo rapido!",
  ["62:423e"] = "O CENTRO DE\nCOMUNICA'sOES ja\vesta funcionando.\fJa troquei uns\nPOKéMONS hoje!",
  ["62:435d"] = "Quando eu crescer,\nvou ser LIDER DE\vGINASIO.\fEu farei meu\nPOKéMON batalhar\vcom o do meu\vamigo e torna-lo\vforte!",
  ["62:4402"] = "Quando eu era\nnovo, fui um\votimo treinador\vPOKéMON!\fAqui vai uma\nsuper dica:\vCapture muitos\vPOKéMONS!\fTrate-os com\ngentileza!",
  ["62:44b8"] = "Os POKéMONS ganham\nexperiencia\vpara evoluirem e\vficarem fortes!",
  ["62:44f4"] = "POKéMONS evoluem!\nEstou chocada,\vpois vi um\vevoluir",
  ["62:4577"] = "Voce sabe,\nPOKéMONS comem\vGRAOS. \fBem, meu POKéMON\nficou saudavel\vpois comeu um\vGRAO. \fTome! Pode levar\num GRAO!",
  ["62:45e4"] = "Cheque as arvores.\nElas sempre deixam\vcair GRAOS.",
  ["62:4755"] = "Ola! Voce deve\nser o famoso\v{PLAYER}.\fO PROFESSOR ELM\nme disse que voce\vviria.",
  ["62:4797"] = "E isto o que eu\nquero que o\vPROFESSOR ELM\vexamine para mim.",
  ["62:47c1"] = "{PLAYER} recebeu\nOVO ESTRANHO.",
  ["62:47da"] = "Eu conheco um\ncasal que comanda\vo CRIATORIO\vPOKéMON.\fForam eles que me\nderam este OVO.\fEu fiquei\nimpressionado,\ventao eu mandei\vuma carta para o\vPROFESSOR ELM.\fEle é um perito\nna evolucao\vPOKéMON!",
  ["62:4881"] = "Até o PROFESSOR\nCARVALHO reconhece\visto.",
  ["62:48a6"] = "Se o que eu acho\nestiver certo, o\vPROFESSOR ELM\vconfirmara.",
  ["62:4923"] = "Eu dependo de\nvoce!",
  ["62:4939"] = "A vida é\ndeliciosa!\fHa sempre novas\ndescobertas a\vserem feitas!",
  ["62:4974"] = "CARVALHO: Ah! Voce\né {PLAYER}!\fEu sou CARVALHO.\nUm pesquisador\vPOKéMON.\fEu estava\nvisitando meu\vamigo SENHOR\vPOKéMON.  \fOuvi dizer\nque voce tinha um\vrecado do\vPROFESSOR ELM,\ventao eu esperei\vaqui.\fOh! O que é isto?\nUm POKéMON raro!\fDeixe-me ver…\fHum, entendi!\fEu sei porque o\nPROFESSOR ELM te\vdeu um POKéMON\vpara esta missao.\fPara pesquisadores\ncomo o PROFESSOR\vELM e eu,\vos POKéMONS\vsao nossos\vamigos.\fEle percebeu que\nvoce trataria seu\vPOKéMON com amor e\vcarinho.\f…Ah!\fVoce parece ser\nconfiante.\fComo voce gostaria\nde me ajudar?\fViu? Essa é a mais\nnova versao da\vPOKéDEX.\fEla registra\nautomaticamente\vas informacoes dos\vPOKéMONS que voce\vviu ou capturou.\fE uma enciclopédia\nde tecnologia\valta!",
  ["62:4bbb"] = "{PLAYER} recebeu\nPOKéDEX.",
  ["62:4bcd"] = "Saia para pegar\ntodos os POKéMONS\ve completar a\vPOKéDEX.\fEu demorei muito\naqui.\fEu devo ir a\nGOLDENROD para o\vmeu usual show de\vradio.\f{PLAYER}, eu estou\ncontando com voce!",
  ["62:4cfc"] = "Isso é muito\ntriste.\fIsso parece ser\nmuito raro.",
  ["62:4e29"] = "Ola rapaz!\nVoce ja visitou a\vTORRE BROTINHO?",
  ["62:4e4f"] = "Eu vim de longe.\nE melhor eu tele-\vfonar para minha\vcasa!",
}
